window.CLASS_DATA = [{"key": "acei", "topic": "cardio", "name": "ACE Inhibitors", "pronunciation": "ay-see-ee in-HIB-ih-ters", "blurb": "First-line for hypertension, heart failure, and renal protection in diabetes/CKD.", "general": ["Mechanism: Block ACE, so angiotensin I can't convert to angiotensin II — less vasoconstriction, less aldosterone release. ACE also normally breaks down bradykinin, so blocking it lets bradykinin build up (this is why the class causes cough and angioedema).", "Class indications: Hypertension, HFrEF, post-MI, diabetic nephropathy/proteinuric CKD.", "Class side effects: Dry cough (bradykinin), hyperkalemia, first-dose hypotension, angioedema (rare, serious), acute kidney injury if bilateral renal artery stenosis.", "Class contraindications: Pregnancy, bilateral renal artery stenosis, prior ACEi-induced angioedema.", "Class monitoring: SCr and K+ at baseline, then 1-2 weeks after starting or any dose increase."], "memberCols": ["Prodrug?", "Dosing", "Notable"], "members": [{"name": "Captopril", "a": "No", "b": "TID", "c": "First-in-class; short half-life; food reduces absorption; used historically in hypertensive urgency"}, {"name": "Enalapril", "a": "Yes", "b": "BID", "c": "Active metabolite enalaprilat also available IV"}, {"name": "Lisinopril", "a": "No", "b": "OD", "c": "Not hepatically metabolized — renally eliminated as-is; useful in hepatic impairment"}, {"name": "Ramipril", "a": "Yes", "b": "OD", "c": "HOPE trial — CV risk reduction independent of BP lowering"}, {"name": "Perindopril", "a": "Yes", "b": "OD", "c": "Long half-life, high tissue ACE affinity"}, {"name": "Quinapril", "a": "Yes", "b": "OD–BID", "c": "Absorption reduced by high-fat meals"}, {"name": "Fosinopril", "a": "Yes", "b": "OD", "c": "Dual hepatic + renal elimination — preferred in significant renal impairment"}, {"name": "Benazepril", "a": "Yes", "b": "OD–BID", "c": "Extensively protein bound"}, {"name": "Trandolapril", "a": "Yes", "b": "OD", "c": "Very long half-life; TRACE trial post-MI evidence"}, {"name": "Moexipril", "a": "Yes", "b": "OD–BID", "c": "Take on empty stomach — food significantly reduces absorption"}, {"name": "Cilazapril", "a": "Yes", "b": "OD", "c": "Available in Canada; long-acting"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Contraindicated in all trimesters — fetotoxic (oligohydramnios, renal dysgenesis, skull hypoplasia). Switch to labetalol, methyldopa, or nifedipine as soon as pregnancy is identified."}, {"label": "Breastfeeding", "warn": false, "text": "Captopril and enalapril have the most reassurance data (low milk transfer) if an ACEi is needed while breastfeeding."}, {"label": "Renal impairment", "warn": true, "text": "Most members are renally eliminated — reduce starting dose and monitor SCr/K+ closely. Avoid entirely in bilateral renal artery stenosis. Fosinopril's dual elimination makes it a common choice here."}, {"label": "Hepatic impairment", "warn": false, "text": "Most class members are prodrugs needing hepatic activation — efficacy may be reduced in severe liver disease. Lisinopril (not a prodrug) is often preferred."}, {"label": "Elderly", "warn": true, "text": "Higher risk of first-dose hypotension and hyperkalemia — start low, monitor renal function more frequently after initiation/titration."}, {"label": "Pediatrics", "warn": false, "text": "Used off-label for pediatric hypertension and proteinuric renal disease; weight-based dosing. Captopril's short half-life makes it easier to titrate carefully in infants."}], "diagramNote": "Same pathway, different blocking point across the class family: ACE inhibitors block the ACE step itself; ARBs block the angiotensin II receptor one step later (no bradykinin effect, so no cough); direct renin inhibitors (e.g. aliskiren) block the very first step.", "diagramSvg": "<svg viewBox=\"0 0 720 260\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"arr1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"var(--text-muted)\"/></marker></defs><rect x=\"10\" y=\"30\" width=\"130\" height=\"50\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"75\" y=\"60\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--text)\" font-family=\"sans-serif\">Angiotensinogen</text><line x1=\"140\" y1=\"55\" x2=\"185\" y2=\"55\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr1)\"/><text x=\"162\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--text-muted)\">Renin</text><rect x=\"190\" y=\"30\" width=\"120\" height=\"50\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"250\" y=\"60\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--text)\" font-family=\"sans-serif\">Angiotensin I</text><line x1=\"310\" y1=\"55\" x2=\"365\" y2=\"55\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr1)\"/><rect x=\"315\" y=\"6\" width=\"46\" height=\"34\" rx=\"6\" fill=\"var(--danger-soft)\" stroke=\"var(--danger)\"/><text x=\"338\" y=\"27\" text-anchor=\"middle\" font-size=\"10\" fill=\"var(--danger)\" font-weight=\"700\">ACE</text><line x1=\"338\" y1=\"40\" x2=\"338\" y2=\"50\" stroke=\"var(--danger)\" stroke-width=\"2\"/><text x=\"338\" y=\"98\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"var(--gold)\" font-weight=\"700\">⛔ ACE inhibitors block here</text><rect x=\"370\" y=\"30\" width=\"130\" height=\"50\" rx=\"8\" fill=\"var(--accent-soft)\" stroke=\"var(--accent)\"/><text x=\"435\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--text)\" font-family=\"sans-serif\">Angiotensin II</text><text x=\"435\" y=\"70\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--text-muted)\">(reduced)</text><line x1=\"500\" y1=\"55\" x2=\"545\" y2=\"55\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr1)\"/><rect x=\"550\" y=\"10\" width=\"150\" height=\"42\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"625\" y=\"35\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--text)\" font-family=\"sans-serif\">Vasoconstriction ↓</text><rect x=\"550\" y=\"62\" width=\"150\" height=\"42\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"625\" y=\"87\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--text)\" font-family=\"sans-serif\">Aldosterone ↓</text><rect x=\"190\" y=\"150\" width=\"140\" height=\"50\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"260\" y=\"180\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--text)\" font-family=\"sans-serif\">Bradykinin</text><line x1=\"330\" y1=\"175\" x2=\"365\" y2=\"175\" stroke=\"var(--danger)\" stroke-width=\"2\" stroke-dasharray=\"4 3\" marker-end=\"url(#arr1)\"/><text x=\"347\" y=\"165\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--danger)\">normally degraded by ACE</text><rect x=\"370\" y=\"150\" width=\"200\" height=\"60\" rx=\"8\" fill=\"var(--danger-soft)\" stroke=\"var(--danger)\"/><text x=\"470\" y=\"172\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--danger)\" font-family=\"sans-serif\">Accumulates when ACE is blocked</text><text x=\"470\" y=\"190\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--danger)\" font-weight=\"700\">→ dry cough, angioedema</text><line x1=\"338\" y1=\"80\" x2=\"260\" y2=\"150\" stroke=\"var(--text-muted)\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/></svg>"}, {"key": "arb", "topic": "cardio", "name": "ARBs (Angiotensin Receptor Blockers)", "pronunciation": "an-jee-oh-TEN-sin re-SEP-ter BLOK-ers", "blurb": "Alternative to ACE inhibitors for hypertension, heart failure, and diabetic nephropathy in patients who can't tolerate ACEi cough/angioedema.", "general": ["Mechanism: Block angiotensin II from binding the AT1 receptor, preventing vasoconstriction and aldosterone release — same downstream effect as ACE inhibitors but achieved by receptor blockade rather than by stopping angiotensin II synthesis. Because ACE (and bradykinin breakdown) is untouched, bradykinin doesn't accumulate.", "Class indications: Hypertension, HFrEF (add-on or ACEi-intolerant), diabetic nephropathy/proteinuric CKD, post-MI in ACEi-intolerant patients.", "Class side effects: Hyperkalemia, hypotension (especially first dose or volume-depleted patients), acute kidney injury with bilateral renal artery stenosis. Cough and angioedema are much rarer than with ACEi because bradykinin isn't affected, though angioedema can still rarely occur.", "Class contraindications: Pregnancy, bilateral renal artery stenosis, concurrent use with aliskiren in diabetics.", "Class monitoring: SCr and K+ at baseline and 1-2 weeks after initiation or dose titration; blood pressure response."], "memberCols": ["Renal/Hepatic Elim.", "Dosing", "Notable"], "members": [{"name": "Losartan", "a": "Hepatic (active metabolite)", "b": "OD-BID", "c": "First-in-class; mild uricosuric effect useful if gout coexists; prodrug-like conversion via CYP2C9"}, {"name": "Valsartan", "a": "Hepatic/biliary", "b": "OD-BID", "c": "Component of sacubitril-valsartan (Entresto) for HFrEF"}, {"name": "Candesartan", "a": "Renal", "b": "OD", "c": "CHARM trials — strong HF evidence; prodrug (candesartan cilexetil)"}, {"name": "Irbesartan", "a": "Hepatic", "b": "OD", "c": "Strongest diabetic nephropathy trial data (IRMA-2, IDNT) of the class"}, {"name": "Telmisartan", "a": "Hepatic/biliary (longest half-life)", "b": "OD", "c": "~24h half-life gives the most consistent trough BP control; partial PPAR-gamma agonist activity"}, {"name": "Olmesartan", "a": "Renal/biliary", "b": "OD", "c": "Associated with rare sprue-like enteropathy (chronic diarrhea, weight loss) — distinct class-specific caution"}, {"name": "Eprosartan", "a": "Biliary/renal", "b": "OD-BID", "c": "Least commonly used; also blocks presynaptic AT1 receptors reducing norepinephrine release"}, {"name": "Azilsartan", "a": "Hepatic", "b": "OD", "c": "Highest AT1 receptor affinity/potency in the class; not widely available in Canada"}, {"name": "Fimasartan", "a": "Hepatic/biliary", "b": "OD", "c": "Newer agent, limited Canadian availability/experience"}, {"name": "Sacubitril/Valsartan", "a": "Hepatic (valsartan) + esterase (sacubitril)", "b": "BID", "c": "ARNI combo — neprilysin inhibition boosts natriuretic peptides; first-line over ACEi/ARB alone in HFrEF (PARADIGM-HF)"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Contraindicated in all trimesters — same fetotoxic profile as ACE inhibitors (oligohydramnios, renal dysgenesis, hypocalvaria). Discontinue as soon as pregnancy is confirmed or planned."}, {"label": "Breastfeeding", "warn": true, "text": "Limited data; generally avoided, especially in newborns/preterm infants, due to theoretical effects on the infant renin-angiotensin system. Preferred agents (e.g., enalapril, captopril) exist if an ACEi/ARB is truly needed postpartum."}, {"label": "Renal impairment", "warn": true, "text": "Can cause an initial rise in SCr (up to 30% is acceptable) from reduced glomerular filtration pressure; monitor closely and avoid in bilateral renal artery stenosis. Still renoprotective long-term in proteinuric CKD."}, {"label": "Hepatic impairment", "warn": false, "text": "Most ARBs need no dose adjustment in mild-moderate hepatic impairment; use caution and lower starting doses in severe impairment given increased bioavailability (e.g., valsartan)."}, {"label": "Elderly", "warn": true, "text": "Increased risk of hypotension and hyperkalemia, particularly with volume depletion, diuretics, or NSAID co-use; start low and monitor renal function/electrolytes more frequently."}, {"label": "Pediatrics", "warn": false, "text": "Losartan and a few others are approved for pediatric hypertension (usually age 6+); weight-based dosing is used and pregnancy-risk counselling matters for adolescents."}]}, {"key": "beta-blocker", "topic": "cardio", "name": "Beta-Blockers", "pronunciation": "BAY-tuh BLOK-ers", "blurb": "Mainstay for HFrEF, post-MI, rate control in AFib, and angina; used for hypertension mainly as a later-line agent.", "general": ["Mechanism: Competitively block beta-adrenergic receptors, reducing heart rate, contractility, and AV nodal conduction (beta-1) and, depending on selectivity, bronchial/vascular smooth muscle tone (beta-2). In HF, chronic beta-1 blockade blunts the harmful effects of sympathetic overactivation and remodels the heart favourably over months.", "Class indications: HFrEF (bisoprolol, carvedilol, metoprolol succinate only), post-MI, angina, AFib/SVT rate control, hypertension (later-line), migraine prophylaxis, essential tremor, performance anxiety.", "Class side effects: Bradycardia, fatigue, cold extremities, bronchospasm (nonselective agents), masking of hypoglycemia symptoms, erectile dysfunction, vivid dreams/depression (lipophilic agents crossing the blood-brain barrier).", "Class contraindications: Severe bradycardia, high-grade AV block without a pacemaker, decompensated/acute HF (cardiogenic shock), severe reactive airway disease (relative for nonselective agents).", "Class monitoring: Heart rate and blood pressure at each titration; in HFrEF, start low and go slow (uptitrate no faster than every 2 weeks) watching for worsening congestion."], "memberCols": ["Selectivity/ISA", "Lipid/Water Soluble", "Notable"], "members": [{"name": "Metoprolol (tartrate/succinate)", "a": "Beta-1 selective", "b": "Lipophilic", "c": "Succinate (extended-release) is the HFrEF-evidence formulation (MERIT-HF); tartrate is short-acting, used for acute rate control"}, {"name": "Bisoprolol", "a": "Beta-1 selective (most cardioselective)", "b": "Balanced (lipo/hydrophilic)", "c": "CIBIS-II HFrEF trial; renal and hepatic dual elimination gives flexibility in organ dysfunction"}, {"name": "Carvedilol", "a": "Nonselective + alpha-1 blockade", "b": "Lipophilic", "c": "COPERNICUS/US-Carvedilol HFrEF trials; added vasodilation can cause more orthostatic hypotension"}, {"name": "Atenolol", "a": "Beta-1 selective", "b": "Hydrophilic (renally eliminated)", "c": "Less favoured now — weaker CV outcome data than other agents in hypertension trials (e.g., LIFE, ASCOT)"}, {"name": "Propranolol", "a": "Nonselective", "b": "Highly lipophilic", "c": "Crosses BBB well — used for migraine prophylaxis, essential tremor, and performance anxiety; avoid in asthma/COPD"}, {"name": "Nebivolol", "a": "Beta-1 selective + nitric oxide-mediated vasodilation", "b": "Lipophilic", "c": "Vasodilating properties may reduce fatigue/cold extremities relative to older agents"}, {"name": "Labetalol", "a": "Nonselective + alpha-1 blockade", "b": "Lipophilic", "c": "IV form used in hypertensive emergency and safe oral option in pregnancy"}, {"name": "Sotalol", "a": "Nonselective + Class III antiarrhythmic (K+ channel block)", "b": "Hydrophilic", "c": "Used for arrhythmia (AFib/VT) rather than routine HTN/HF; requires QTc monitoring — torsades risk"}, {"name": "Acebutolol", "a": "Beta-1 selective with ISA", "b": "Balanced", "c": "Intrinsic sympathomimetic activity causes less resting bradycardia — rarely first choice today"}, {"name": "Pindolol", "a": "Nonselective with ISA", "b": "Balanced", "c": "ISA agents avoided post-MI/HFrEF since outcome trials used non-ISA drugs"}, {"name": "Timolol", "a": "Nonselective", "b": "Balanced", "c": "Oral form post-MI; ophthalmic form for glaucoma — systemic absorption can still cause bradycardia/bronchospasm"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Labetalol is a preferred agent for hypertension in pregnancy; atenolol is best avoided (associated with fetal growth restriction). Most other beta-blockers are used cautiously when benefit outweighs risk."}, {"label": "Breastfeeding", "warn": false, "text": "Generally compatible; metoprolol and propranolol have low milk transfer and are preferred. Atenolol and acebutolol concentrate more in breast milk — monitor infant for bradycardia/hypoglycemia if used."}, {"label": "Renal impairment", "warn": true, "text": "Hydrophilic, renally-cleared agents (atenolol, sotalol, nadolol) need dose reduction; sotalol particularly requires renal dosing to avoid QT-related arrhythmia. Hepatically cleared agents (metoprolol, carvedilol) are preferred in renal failure."}, {"label": "Hepatic impairment", "warn": true, "text": "Lipophilic, hepatically metabolized agents (metoprolol, carvedilol, propranolol, labetalol) can accumulate — reduce dose/frequency in significant hepatic impairment; renally cleared agents are an alternative."}, {"label": "Elderly", "warn": true, "text": "Increased sensitivity to bradycardia, falls from orthostatic hypotension, and fatigue/depression from lipophilic agents crossing into the CNS; start at low doses and titrate slowly."}, {"label": "Pediatrics", "warn": false, "text": "Propranolol is actually first-line therapy for infantile hemangioma and is used in pediatric arrhythmias/hypertension; dosing is weight-based with hypoglycemia risk monitored in infants."}]}, {"key": "ccb", "topic": "cardio", "name": "Calcium Channel Blockers (CCBs)", "pronunciation": "KAL-see-um CHAN-el BLOK-ers", "blurb": "Split into two functionally distinct subclasses — dihydropyridines for hypertension/angina via vasodilation, and non-dihydropyridines for rate control via cardiac conduction slowing.", "general": ["Mechanism: Block L-type calcium channels, reducing calcium influx into vascular smooth muscle and cardiac cells. Dihydropyridines (e.g., amlodipine) act mainly on vascular smooth muscle causing arterial vasodilation with little cardiac effect; non-dihydropyridines (verapamil, diltiazem) act more on the heart, slowing SA/AV nodal conduction and reducing contractility.", "Class indications: Hypertension, chronic stable/vasospastic angina (dihydropyridines and non-DHPs), rate control in AFib/SVT (non-DHPs only), Raynaud phenomenon (dihydropyridines).", "Class side effects: Dihydropyridines — peripheral edema (arteriolar dilation without matching venodilation), flushing, headache, reflex tachycardia. Non-dihydropyridines — bradycardia, AV block, constipation (especially verapamil), negative inotropy.", "Class contraindications: Non-DHPs contraindicated in HFrEF (negative inotropy worsens outcomes), sick sinus syndrome or high-grade AV block without a pacemaker, and concurrent use with beta-blockers in decompensated HF (additive AV block/bradycardia risk). Avoid combining verapamil/diltiazem with beta-blockers when possible.", "Class monitoring: Blood pressure and heart rate; watch for peripheral edema with dihydropyridines and PR interval/bradycardia with non-dihydropyridines."], "memberCols": ["Subclass", "Half-life/Dosing", "Notable"], "members": [{"name": "Amlodipine", "a": "Dihydropyridine", "b": "~40h, OD", "c": "Longest half-life in class — very forgiving of missed doses; most peripheral edema of the DHPs at higher doses"}, {"name": "Nifedipine (extended-release)", "a": "Dihydropyridine", "b": "OD (ER only)", "c": "Immediate-release form avoided (reflex tachycardia, historically linked to MI risk) — ER formulation only for chronic use"}, {"name": "Felodipine", "a": "Dihydropyridine", "b": "OD", "c": "Notable grapefruit juice interaction (CYP3A4 inhibition raises levels significantly)"}, {"name": "Amlodipine/Atorvastatin", "a": "Dihydropyridine combo", "b": "OD", "c": "Combination product for patients needing both BP and lipid control — improves adherence"}, {"name": "Verapamil", "a": "Non-dihydropyridine (phenylalkylamine)", "b": "TID (IR) / OD (ER)", "c": "Most negative inotropic/AV nodal effect of the class; significant constipation; strong CYP3A4/P-gp inhibitor (digoxin, statin interactions)"}, {"name": "Diltiazem", "a": "Non-dihydropyridine (benzothiazepine)", "b": "TID-QID (IR) / OD (ER)", "c": "Intermediate between verapamil and DHPs on vasodilation vs. cardiac effects; also a moderate CYP3A4 inhibitor"}, {"name": "Nimodipine", "a": "Dihydropyridine", "b": "Q4H", "c": "Selective cerebral vasodilation — used specifically to prevent vasospasm after subarachnoid hemorrhage, not for routine HTN"}, {"name": "Nicardipine", "a": "Dihydropyridine", "b": "IV infusion (also PO TID)", "c": "IV form used for hypertensive emergencies/perioperative BP control given rapid titratability"}, {"name": "Clevidipine", "a": "Dihydropyridine", "b": "IV infusion only", "c": "Ultra-short half-life (~1 min, esterase metabolism) — used for precise BP control in hypertensive emergency/surgery"}, {"name": "Lercanidipine", "a": "Dihydropyridine", "b": "OD", "c": "Highly lipophilic — slower onset, smoother BP control, and less edema reported than amlodipine"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Nifedipine (extended-release) is a preferred agent for hypertension in pregnancy, including for acute severe hypertension; amlodipine is used when a DHP is needed chronically. Non-DHPs are used less often but not strictly contraindicated."}, {"label": "Breastfeeding", "warn": false, "text": "Nifedipine and verapamil are considered compatible with breastfeeding with low milk transfer; monitor infant for rare irritability or feeding issues."}, {"label": "Renal impairment", "warn": false, "text": "Most CCBs are hepatically metabolized and require little to no dose adjustment in renal impairment, making them attractive antihypertensives in CKD (though they lack the proteinuria-reduction benefit of ACEi/ARB)."}, {"label": "Hepatic impairment", "warn": true, "text": "Extensively hepatically metabolized (CYP3A4) — significant hepatic impairment can raise levels substantially; reduce dose and titrate slowly, especially for verapamil and diltiazem."}, {"label": "Elderly", "warn": true, "text": "Increased risk of peripheral edema and orthostatic hypotension with dihydropyridines, and of bradycardia/constipation with non-dihydropyridines; start at lower doses."}, {"label": "Pediatrics", "warn": false, "text": "Not first-line for pediatric hypertension but used off-label when needed (e.g., amlodipine); IV nicardipine is used in pediatric hypertensive emergencies under specialist guidance."}]}, {"key": "thiazide", "topic": "cardio", "name": "Thiazide / Thiazide-like Diuretics", "pronunciation": "THY-uh-zide DY-yoo-RET-iks", "blurb": "First-line agents for hypertension, often combined with an ACEi/ARB or CCB; weaker diuretics than loops but with strong long-term BP-lowering evidence.", "general": ["Mechanism: Inhibit the Na+/Cl- cotransporter in the distal convoluted tubule, reducing sodium (and secondarily water) reabsorption. Increased distal sodium delivery drives more Na+/K+ exchange in the collecting duct, causing potassium and (via increased calcium reabsorption elsewhere in the nephron) reduced calcium excretion.", "Class indications: Hypertension (first-line, per Hypertension Canada), mild edema, nephrolithiasis prevention (idiopathic hypercalciuria), nephrogenic diabetes insipidus (paradoxical antidiuretic effect).", "Class side effects: Hypokalemia, hyponatremia, hypomagnesemia, hypercalcemia, hyperuricemia (can precipitate gout), hyperglycemia, dyslipidemia, photosensitivity.", "Class contraindications: Sulfonamide allergy (relative — cross-reactivity risk is low but often cited), severe renal impairment (ineffective once eGFR is very low, except metolazone which retains activity), symptomatic hyponatremia or gout as relative cautions.", "Class monitoring: Electrolytes (Na+, K+, Mg2+, Ca2+) and renal function at baseline, 2-4 weeks after starting/titrating, then periodically; blood glucose and uric acid in at-risk patients."], "memberCols": ["Type", "Duration of Action", "Notable"], "members": [{"name": "Hydrochlorothiazide (HCTZ)", "a": "Thiazide", "b": "~6-12h", "c": "Most commonly combined in fixed-dose antihypertensive combos (with ACEi/ARB); shorter duration than chlorthalidone limits 24h BP control"}, {"name": "Chlorthalidone", "a": "Thiazide-like", "b": "~48-72h (longest)", "c": "Preferred over HCTZ in several guidelines/trials (ALLHAT) for superior 24h BP control and CV outcome data at equivalent doses"}, {"name": "Indapamide", "a": "Thiazide-like", "b": "~14-24h", "c": "Some additional direct vasodilatory effect; commonly used in Canada/Europe; HYVET trial showed benefit in elderly hypertension"}, {"name": "Metolazone", "a": "Thiazide-like (quinazoline)", "b": "~12-24h", "c": "Retains efficacy even in advanced CKD (low eGFR) — used synergistically with loop diuretics for diuretic resistance in HF/edema"}, {"name": "Bendroflumethiazide", "a": "Thiazide", "b": "~18-24h", "c": "Less commonly used in Canada; found in some combination products historically"}, {"name": "Methyclothiazide", "a": "Thiazide", "b": "~24h", "c": "Longer-acting thiazide, infrequently prescribed now"}, {"name": "Xipamide", "a": "Thiazide-like", "b": "~12-24h", "c": "Not commonly available in Canada; retains some efficacy in mild-moderate renal impairment"}, {"name": "Chlorothiazide", "a": "Thiazide", "b": "~6-12h (also IV)", "c": "Original thiazide; IV formulation exists for hospitalized patients unable to take oral diuretics"}, {"name": "Hydrochlorothiazide/Amiloride", "a": "Thiazide + K+-sparing combo", "b": "~12-24h", "c": "Combination mitigates thiazide-induced hypokalemia by adding a potassium-sparing diuretic"}, {"name": "Hydrochlorothiazide/Triamterene", "a": "Thiazide + K+-sparing combo", "b": "~12-16h", "c": "Another potassium-sparing combination product reducing need for separate K+ supplementation"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Generally avoided, particularly in preeclampsia risk, due to potential to mask/worsen volume contraction and theoretical neonatal thrombocytopenia/electrolyte disturbance with third-trimester use; other antihypertensives are preferred."}, {"label": "Breastfeeding", "warn": false, "text": "Low doses are generally considered compatible with breastfeeding, though high doses may reduce milk supply via volume depletion; monitor infant for jaundice/electrolyte issues if used."}, {"label": "Renal impairment", "warn": true, "text": "Efficacy drops sharply as eGFR falls (largely ineffective below ~30 mL/min/1.73m2) except metolazone, which remains effective and is often paired with a loop diuretic in this setting."}, {"label": "Hepatic impairment", "warn": true, "text": "Electrolyte disturbances (especially hypokalemia and hyponatremia) can precipitate hepatic encephalopathy in cirrhosis — use cautiously with close electrolyte monitoring."}, {"label": "Elderly", "warn": true, "text": "Higher risk of hyponatremia (sometimes severe/symptomatic) and dehydration/orthostatic hypotension; check sodium and potassium within the first few weeks of therapy."}, {"label": "Pediatrics", "warn": false, "text": "Used off-label for pediatric hypertension and edema at weight-based doses; electrolyte monitoring follows the same principles as in adults."}]}, {"key": "loop-diuretics", "topic": "cardio", "name": "Loop Diuretics", "pronunciation": "loop dy-yoo-RET-iks", "blurb": "The most potent diuretic class - first-line for edema of heart failure, cirrhosis, and CKD, and useful for hypertension when renal function is reduced.", "general": ["Mechanism: Block the Na-K-2Cl (NKCC2) cotransporter in the thick ascending limb of the loop of Henle, preventing reabsorption of a large fraction of filtered sodium - this makes them the most potent (\"high-ceiling\") diuretics. The same transporter also drives Ca2+ and Mg2+ reabsorption in that segment, so loop diuretics increase urinary loss of both.", "Class indications: Edema due to heart failure, hepatic cirrhosis, nephrotic syndrome, and CKD; hypertension (especially with reduced GFR where thiazides lose efficacy); adjunct treatment of hyperkalemia and hypercalcemia.", "Class side effects: Hypokalemia, hypomagnesemia, hyponatremia, and metabolic (contraction) alkalosis from the electrolyte losses; ototoxicity with high-dose IV or concurrent ototoxic drugs; hyperuricemia/gout flares; volume depletion and orthostatic hypotension.", "Class contraindications: Anuria unresponsive to a test dose, severe pre-existing electrolyte depletion, and known hypersensitivity - furosemide, bumetanide, and torsemide are sulfonamide derivatives with theoretical cross-reactivity, but ethacrynic acid is not and is the alternative for a true sulfa allergy.", "Class monitoring: Serum K+, Mg2+, and Na+, renal function, weight/fluid status, and blood pressure regularly after initiation or dose changes; hearing assessment with prolonged high-dose IV therapy."], "memberCols": ["Availability/Status", "Duration/Handling", "Notable"], "members": [{"name": "Furosemide", "a": "Widely available (Lasix)", "b": "Variable, ~50% oral bioavailability; duration ~6-8h", "c": "Most commonly used loop diuretic; erratic absorption means IV and PO doses are not equivalent"}, {"name": "Bumetanide", "a": "Available (Burinex)", "b": "~80-100% oral bioavailability; duration ~4-6h", "c": "More predictable absorption than furosemide, useful when gut edema limits furosemide response; ~1mg bumetanide ≈ 40mg furosemide"}, {"name": "Torsemide", "a": "Limited availability in Canada", "b": ">80% bioavailability; longest duration of the marketed agents (~12h)", "c": "Longer, steadier action may blunt post-dose sodium-retention rebound; TORIC trial suggested fewer HF hospitalizations vs furosemide"}, {"name": "Ethacrynic Acid", "a": "Available (Edecrin), rarely used", "b": "Duration ~6-8h", "c": "The only non-sulfonamide loop diuretic - the go-to choice for patients with a true sulfa allergy"}, {"name": "Piretanide", "a": "Not marketed in Canada (used in Europe)", "b": "Duration ~4-6h", "c": "Similar potency to furosemide; illustrates that the class extends beyond the four Canadian agents"}, {"name": "Azosemide", "a": "Not marketed in Canada (Japan/South Korea)", "b": "Slow absorption gives a longer natriuretic effect (~12h)", "c": "Sustained, delayed natriuresis produces less post-dose sodium retention than furosemide"}, {"name": "Muzolimine", "a": "Withdrawn worldwide", "b": "N/A", "c": "Pulled from the market in the 1980s after reports of peripheral neuropathy - a classic pharmacovigilance example"}, {"name": "Etozolin", "a": "Not marketed in Canada", "b": "Prodrug - slower onset until converted to its active form", "c": "Hepatically converted to the active metabolite ozolinone; historical use in Japan and parts of Europe"}, {"name": "Ozolinone", "a": "Not marketed as a standalone drug", "b": "Active metabolite of etozolin", "c": "Good exam example of a prodrug/active-metabolite pair within one drug class"}, {"name": "Tienilic Acid (Ticrynafen)", "a": "Withdrawn (early 1980s)", "b": "Also uricosuric (lowers uric acid, unlike other loop diuretics)", "c": "Withdrawn after causing fatal hepatotoxicity - a landmark case in post-marketing drug safety"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not first-line - reserved for clear indications (e.g., pulmonary edema) because they reduce plasma volume and can compromise placental perfusion; use the lowest effective dose and monitor volume status closely."}, {"label": "Breastfeeding", "warn": true, "text": "Furosemide can suppress lactation, especially early postpartum; generally compatible in small doses but monitor infant and milk supply."}, {"label": "Renal impairment", "warn": true, "text": "Reduced GFR means less drug is delivered to its site of action in the tubule, so doses often need to be substantially increased (loop diuretics remain effective even in advanced CKD, unlike thiazides)."}, {"label": "Hepatic impairment", "warn": true, "text": "Use cautiously - aggressive diuresis and the resulting electrolyte shifts (especially hypokalemia and alkalosis) can precipitate hepatic encephalopathy; diurese gradually."}, {"label": "Elderly", "warn": true, "text": "Higher risk of dehydration, orthostatic falls, and electrolyte disturbances; start at lower doses and monitor renal function and electrolytes more frequently."}, {"label": "Pediatrics", "warn": false, "text": "Used for pediatric heart failure and renal disease with weight-based dosing; rapid IV administration carries an ototoxicity risk, so infuse slowly."}]}, {"key": "statins", "topic": "cardio", "name": "Statins (HMG-CoA Reductase Inhibitors)", "pronunciation": "STAT-ins (aitch-em-jee koh-AY reh-DUK-tase in-HIB-ih-ters)", "blurb": "Cornerstone of ASCVD prevention - lower LDL more effectively than any other oral class and are backed by the largest cardiovascular outcomes evidence base.", "general": ["Mechanism: Competitively inhibit HMG-CoA reductase, the rate-limiting enzyme of hepatic cholesterol synthesis. Lower intracellular cholesterol upregulates hepatic LDL-receptor expression, pulling more LDL out of circulation. The class also has proposed pleiotropic effects (plaque stabilization, anti-inflammatory) that partly explain benefits beyond the degree of LDL lowering.", "Class indications: Primary and secondary prevention of atherosclerotic cardiovascular disease (MI, ischemic stroke), dyslipidemia, diabetes with additional risk factors, and familial hypercholesterolemia.", "Class side effects: Myalgia/myopathy (rare progression to rhabdomyolysis), asymptomatic transaminase elevation, small increase in new-onset diabetes risk, and rare reports of cognitive complaints (not consistently reproduced in trials).", "Class contraindications: Active liver disease or unexplained persistent transaminase elevation, pregnancy, and (for simvastatin/lovastatin at higher doses) concurrent strong CYP3A4 inhibitors due to markedly increased myopathy risk.", "Class monitoring: Baseline lipid panel and LFTs before starting; routine CK monitoring is not needed unless the patient is symptomatic; recheck lipids 4-12 weeks after starting or titrating to assess response."], "memberCols": ["Intensity (typical dose)", "Metabolism", "Notable"], "members": [{"name": "Atorvastatin", "a": "High-intensity 40-80mg (moderate 10-20mg)", "b": "CYP3A4", "c": "Longest half-life (~14h) of the routinely used statins, so it can be dosed any time of day"}, {"name": "Rosuvastatin", "a": "High-intensity 20-40mg", "b": "Minimal CYP metabolism (mainly CYP2C9); largely excreted unchanged", "c": "Most potent LDL-lowering per milligram; fewer CYP3A4-mediated interactions than atorvastatin/simvastatin"}, {"name": "Simvastatin", "a": "Moderate-intensity 20-40mg (80mg restricted)", "b": "CYP3A4", "c": "80mg dose restricted after the SEARCH trial showed higher myopathy risk; capped at 20mg when combined with amlodipine"}, {"name": "Pravastatin", "a": "Moderate-intensity 40-80mg", "b": "Not significantly CYP-metabolized (sulfation pathway)", "c": "Preferred when avoiding CYP3A4 interactions matters (e.g., with protease inhibitors or cyclosporine)"}, {"name": "Fluvastatin", "a": "Low-to-moderate intensity 40-80mg (XL)", "b": "CYP2C9", "c": "Lower potency than newer agents; the XL formulation allows once-daily dosing"}, {"name": "Lovastatin", "a": "Low-to-moderate intensity 20-40mg", "b": "CYP3A4", "c": "First statin ever marketed (1987), derived from Aspergillus terreus; absorption improves when taken with food"}, {"name": "Pitavastatin", "a": "Moderate-intensity 2-4mg", "b": "Minimal CYP metabolism (mainly glucuronidation)", "c": "Newest statin available in Canada; essentially glucose-neutral, a reasonable choice in patients with diabetes"}, {"name": "Cerivastatin", "a": "Formerly 0.2-0.8mg", "b": "CYP3A4/CYP2C8", "c": "Withdrawn worldwide in 2001 after fatal rhabdomyolysis, particularly when combined with gemfibrozil - a key pharmacovigilance case"}, {"name": "Mevastatin (Compactin)", "a": "Never marketed", "b": "N/A - natural fungal metabolite", "c": "The first HMG-CoA reductase inhibitor ever discovered (Akira Endo, 1976, from Penicillium citrinum); proof-of-concept for the entire class"}, {"name": "Dalvastatin", "a": "Never marketed", "b": "N/A", "c": "Discontinued during clinical development before approval - illustrates typical attrition in statin drug development"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Contraindicated - cholesterol and its synthetic pathway are needed for normal fetal development; discontinue before conception when possible or as soon as pregnancy is identified."}, {"label": "Breastfeeding", "warn": true, "text": "Generally avoided due to insufficient safety data and a theoretical risk to infant lipid synthesis/development."}, {"label": "Renal impairment", "warn": true, "text": "Most statins need no adjustment, but rosuvastatin is capped at 10mg starting dose in severe impairment (CrCl <30) and high-dose simvastatin is used cautiously."}, {"label": "Hepatic impairment", "warn": true, "text": "Contraindicated in active liver disease or unexplained persistent transaminase elevation; use the lowest effective dose otherwise and monitor LFTs."}, {"label": "Elderly", "warn": true, "text": "Increased susceptibility to myopathy and drug interactions from polypharmacy; start at a lower dose and titrate carefully."}, {"label": "Pediatrics", "warn": false, "text": "Used for familial hypercholesterolemia starting around age 8-10 depending on the agent, at fixed low starting doses with periodic lipid and LFT monitoring."}]}, {"key": "oral-anticoagulants", "topic": "cardio", "name": "Oral Anticoagulants (DOACs & Warfarin)", "pronunciation": "OR-al an-tee-koh-AG-yoo-lants", "blurb": "Prevent and treat thromboembolism - DOACs are now first-line for non-valvular AF and VTE, while warfarin remains essential for mechanical valves and valvular AF.", "general": ["Mechanism: DOACs directly inhibit a single activated clotting factor - factor Xa (apixaban, rivaroxaban, edoxaban) or thrombin/factor IIa (dabigatran) - giving predictable, dose-dependent anticoagulation without routine monitoring. Warfarin instead blocks vitamin K epoxide reductase, preventing hepatic synthesis of functional factors II, VII, IX, and X (and proteins C/S), which produces a delayed onset and offset and requires INR monitoring to keep effect in range.", "Class indications: Stroke prevention in non-valvular atrial fibrillation, treatment and secondary prevention of VTE (DVT/PE); warfarin is additionally required for mechanical heart valves and valvular AF (moderate-severe mitral stenosis), settings where DOACs are contraindicated.", "Class side effects: Bleeding is the defining risk shared by every agent in this class - GI bleed, intracranial hemorrhage (lower with DOACs than warfarin), bruising; dabigatran also causes dyspepsia; warfarin uniquely carries risk of skin/tissue necrosis and purple toe syndrome early in therapy (protein C depletion).", "Class contraindications: Active clinically significant bleeding; mechanical heart valves (DOACs are contraindicated here - the RE-ALIGN trial showed harm with dabigatran); severe renal impairment (degree of restriction varies by DOAC); warfarin is teratogenic and contraindicated in pregnancy.", "Class monitoring: Warfarin requires regular INR monitoring (usual target range 2-3, higher for mechanical valves); DOACs need no routine coagulation monitoring but require periodic renal function (CrCl) checks since both clearance and dosing depend on it."], "memberCols": ["Target/Renal clearance", "Reversal agent", "Notable"], "members": [{"name": "Apixaban", "a": "Factor Xa; ~27% renal clearance", "b": "Andexanet alfa (PCC used off-label where unavailable)", "c": "BID dosing; lowest bleeding rates among DOACs in head-to-head-adjacent trial data (ARISTOTLE) - often preferred in higher bleeding-risk patients"}, {"name": "Rivaroxaban", "a": "Factor Xa; ~33% renal clearance", "b": "Andexanet alfa (PCC off-label)", "c": "Once-daily; the 15-20mg doses must be taken with food for adequate absorption"}, {"name": "Edoxaban", "a": "Factor Xa; ~50% renal clearance", "b": "No specific approved antidote in Canada (PCC used)", "c": "Dose reduced for CrCl 15-50, low body weight, or a potent P-gp inhibitor; paradoxically less effective if CrCl is too high (>95)"}, {"name": "Dabigatran", "a": "Direct thrombin (factor IIa); ~80% renal clearance", "b": "Idarucizumab - specific, rapid reversal", "c": "The only DOAC with a dedicated reversal agent; capsules contain tartaric acid causing dyspepsia and must not be opened/chewed"}, {"name": "Warfarin", "a": "Inhibits VKOR; hepatic metabolism with major CYP2C9/VKORC1 genetic variability", "b": "Vitamin K + PCC (or FFP) for urgent reversal", "c": "Numerous food (vitamin K) and drug interactions; the only oral anticoagulant proven safe/effective for mechanical heart valves"}, {"name": "Unfractionated Heparin", "a": "Antithrombin-mediated inhibition of Xa and IIa; reticuloendothelial + renal clearance", "b": "Protamine sulfate - full reversal", "c": "IV/SC only; short half-life makes it useful when rapid on/off control is needed (surgery); requires aPTT monitoring and carries HIT risk"}, {"name": "Enoxaparin (LMWH)", "a": "Predominantly anti-Xa activity; renal clearance", "b": "Protamine - partial reversal only", "c": "Weight-based SC dosing with predictable pharmacokinetics; routine monitoring not needed except in renal failure, obesity, or pregnancy (anti-Xa level)"}, {"name": "Dalteparin (LMWH)", "a": "Anti-Xa predominant; renal clearance", "b": "Protamine - partial", "c": "Historically preferred LMWH in cancer-associated thrombosis (CLOT trial)"}, {"name": "Tinzaparin (LMWH)", "a": "Anti-Xa predominant; renal clearance (least accumulation of the LMWHs)", "b": "Protamine - partial", "c": "Higher average molecular weight gives more hepatic clearance, often favoured in renal impairment among the LMWHs"}, {"name": "Fondaparinux", "a": "Pure synthetic, antithrombin-mediated factor Xa inhibitor; renal clearance", "b": "No effective reversal agent (recombinant factor VIIa considered)", "c": "Does not cross-react with HIT antibodies - a go-to anticoagulant when HIT is suspected or confirmed"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Warfarin is teratogenic and contraindicated (especially weeks 6-12); DOACs are also avoided due to limited data and placental transfer. LMWH, which does not cross the placenta, is the anticoagulant of choice in pregnancy."}, {"label": "Breastfeeding", "warn": true, "text": "Warfarin and heparins/LMWH are considered compatible with breastfeeding (not transferred into milk in clinically significant amounts); DOACs are generally avoided due to a lack of infant safety data."}, {"label": "Renal impairment", "warn": true, "text": "Dabigatran is the most renally dependent DOAC (avoid if CrCl <30); other DOACs, LMWHs, and fondaparinux need dose reduction or avoidance as renal function worsens. Warfarin dosing is not renally driven, but bleeding risk rises with uremia."}, {"label": "Hepatic impairment", "warn": true, "text": "Warfarin's effect is enhanced (reduced clotting factor synthesis and reduced hepatic metabolism, raising bleeding risk); DOACs are generally avoided in significant hepatic impairment or coagulopathy (Child-Pugh B/C)."}, {"label": "Elderly", "warn": true, "text": "Bleeding risk rises with age for every agent in this class; dabigatran dose is reduced in some jurisdictions for patients ≥75-80 years, and falls risk should be assessed before starting any anticoagulant."}, {"label": "Pediatrics", "warn": true, "text": "Anticoagulation in children is specialized - LMWH, UFH, and warfarin remain the mainstay, though some DOACs now have pediatric VTE approvals; dosing is weight-based and requires careful, individualized management."}], "diagramSvg": "<svg viewBox=\"0 0 700 300\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"arr2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"var(--text-muted)\"/></marker></defs><rect x=\"10\" y=\"20\" width=\"150\" height=\"46\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"85\" y=\"48\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"var(--text)\" font-family=\"sans-serif\">Vitamin K</text><line x1=\"85\" y1=\"66\" x2=\"85\" y2=\"100\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr2)\"/><rect x=\"10\" y=\"104\" width=\"150\" height=\"52\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"85\" y=\"126\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"var(--text)\" font-family=\"sans-serif\">Liver synthesis of</text><text x=\"85\" y=\"142\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"var(--text)\" font-family=\"sans-serif\">Factors II, VII, IX, X</text><rect x=\"20\" y=\"164\" width=\"130\" height=\"30\" rx=\"6\" fill=\"var(--danger-soft)\" stroke=\"var(--danger)\"/><text x=\"85\" y=\"184\" text-anchor=\"middle\" font-size=\"10\" fill=\"var(--danger)\" font-weight=\"700\">⛔ Warfarin blocks here</text><line x1=\"160\" y1=\"130\" x2=\"230\" y2=\"130\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr2)\"/><rect x=\"235\" y=\"105\" width=\"110\" height=\"50\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"290\" y=\"128\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--text)\" font-family=\"sans-serif\">Factor X</text><text x=\"290\" y=\"144\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--text-muted)\">(intrinsic + extrinsic)</text><line x1=\"345\" y1=\"130\" x2=\"410\" y2=\"130\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr2)\"/><rect x=\"330\" y=\"60\" width=\"140\" height=\"34\" rx=\"6\" fill=\"var(--danger-soft)\" stroke=\"var(--danger)\"/><text x=\"400\" y=\"81\" text-anchor=\"middle\" font-size=\"10\" fill=\"var(--danger)\" font-weight=\"700\">⛔ Xa inhibitors block here</text><text x=\"400\" y=\"96\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"var(--text-muted)\">apixaban, rivaroxaban, edoxaban</text><line x1=\"400\" y1=\"94\" x2=\"400\" y2=\"106\" stroke=\"var(--danger)\" stroke-width=\"2\"/><rect x=\"415\" y=\"105\" width=\"110\" height=\"50\" rx=\"8\" fill=\"var(--accent-soft)\" stroke=\"var(--accent)\"/><text x=\"470\" y=\"128\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--text)\" font-family=\"sans-serif\">Factor Xa</text><line x1=\"525\" y1=\"130\" x2=\"580\" y2=\"130\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr2)\"/><rect x=\"410\" y=\"200\" width=\"150\" height=\"46\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"485\" y=\"222\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--text)\" font-family=\"sans-serif\">Prothrombin (II)</text><text x=\"485\" y=\"237\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--text-muted)\">↓</text><line x1=\"485\" y1=\"155\" x2=\"485\" y2=\"198\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr2)\"/><rect x=\"585\" y=\"105\" width=\"105\" height=\"50\" rx=\"8\" fill=\"var(--accent-soft)\" stroke=\"var(--accent)\"/><text x=\"637\" y=\"128\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--text)\" font-family=\"sans-serif\">Thrombin (IIa)</text><line x1=\"560\" y1=\"223\" x2=\"600\" y2=\"160\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr2)\"/><rect x=\"530\" y=\"60\" width=\"150\" height=\"34\" rx=\"6\" fill=\"var(--danger-soft)\" stroke=\"var(--danger)\"/><text x=\"605\" y=\"81\" text-anchor=\"middle\" font-size=\"10\" fill=\"var(--danger)\" font-weight=\"700\">⛔ Dabigatran blocks here</text><line x1=\"620\" y1=\"94\" x2=\"637\" y2=\"103\" stroke=\"var(--danger)\" stroke-width=\"2\"/><line x1=\"637\" y1=\"155\" x2=\"637\" y2=\"200\" stroke=\"var(--text-muted)\" stroke-width=\"2\" marker-end=\"url(#arr2)\"/><rect x=\"555\" y=\"204\" width=\"165\" height=\"46\" rx=\"8\" fill=\"var(--surface-2)\" stroke=\"var(--border)\"/><text x=\"637\" y=\"223\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"var(--text)\" font-family=\"sans-serif\">Fibrinogen → Fibrin</text><text x=\"637\" y=\"238\" text-anchor=\"middle\" font-size=\"10\" fill=\"var(--gold)\" font-weight=\"700\">Clot forms</text></svg>", "diagramNote": "Warfarin works upstream (blocks liver synthesis of factors II/VII/IX/X — takes days to have effect, needs bridging). DOACs act directly and instantly on one specific factor: Xa inhibitors (apixaban, rivaroxaban, edoxaban) block Factor Xa; dabigatran blocks thrombin (IIa) directly."}, {"key": "antiplatelets", "topic": "cardio", "name": "Antiplatelets", "pronunciation": "AN-tee-PLAYT-lets", "blurb": "Prevent arterial (platelet-driven) thrombosis - foundational for ACS, stroke/TIA prevention, PAD, and stent patency after PCI.", "general": ["Mechanism: Different agents interrupt different steps of platelet activation and aggregation - ASA irreversibly inhibits COX-1, blocking thromboxane A2 production; P2Y12 inhibitors (clopidogrel, prasugrel, ticagrelor, ticlopidine) block ADP-mediated platelet activation; GPIIb/IIIa inhibitors block the final common pathway of fibrinogen cross-linking between platelets; dipyridamole and cilostazol inhibit phosphodiesterase, raising platelet cAMP and reducing aggregation.", "Class indications: Secondary (and select primary) prevention of atherosclerotic cardiovascular events, acute coronary syndrome management, dual antiplatelet therapy (DAPT) after PCI/stenting, secondary stroke/TIA prevention, and peripheral arterial disease/claudication.", "Class side effects: Bleeding is the shared risk across the class (GI bleed most common with ASA); GI upset/ulceration with ASA; dyspnea and ventricular pauses/bradyarrhythmia specific to ticagrelor; neutropenia/TTP rare with the older thienopyridines; headache common with dipyridamole.", "Class contraindications: Active major bleeding, recent major surgery or trauma with high rebleed risk, and prior intracranial hemorrhage (an absolute contraindication for the more potent agents such as prasugrel); cilostazol is contraindicated in heart failure.", "Class monitoring: No routine laboratory monitoring is required for most agents - watch clinically for bleeding and bruising; platelet function or CYP2C19 genotype testing is sometimes used to identify clopidogrel non-responders."], "memberCols": ["Mechanism/Class", "Reversibility", "Notable"], "members": [{"name": "ASA (Aspirin)", "a": "COX-1 inhibitor", "b": "Irreversible - effect lasts the platelet's ~7-10 day lifespan", "c": "Low dose (81mg) gives the antiplatelet effect; the foundation of nearly every ASCVD secondary prevention regimen"}, {"name": "Clopidogrel", "a": "P2Y12 inhibitor, thienopyridine (prodrug)", "b": "Irreversible", "c": "Requires hepatic activation via CYP2C19 - poor metabolizers get reduced efficacy, prompting consideration of genotype testing or an alternative agent"}, {"name": "Prasugrel", "a": "P2Y12 inhibitor, thienopyridine (prodrug)", "b": "Irreversible", "c": "Faster onset and more potent platelet inhibition than clopidogrel but higher bleeding risk; avoid with prior stroke/TIA, age ≥75, or weight <60kg"}, {"name": "Ticagrelor", "a": "P2Y12 inhibitor, non-thienopyridine, direct-acting", "b": "Reversible (non-covalent binding)", "c": "BID dosing (unlike other P2Y12 inhibitors); can cause dyspnea and bradyarrhythmia; not a prodrug so effect is independent of CYP2C19 status"}, {"name": "Ticlopidine", "a": "P2Y12 inhibitor, thienopyridine (prodrug)", "b": "Irreversible", "c": "First thienopyridine developed - largely abandoned due to neutropenia and TTP risk, superseded by clopidogrel"}, {"name": "Dipyridamole", "a": "Phosphodiesterase inhibitor / adenosine reuptake inhibitor", "b": "Reversible", "c": "Combined with ASA (as Aggrenox) for secondary stroke prevention; headache is a very common side effect"}, {"name": "Cilostazol", "a": "Phosphodiesterase-3 inhibitor (also vasodilator)", "b": "Reversible", "c": "Used for intermittent claudication in PAD; contraindicated in heart failure - a class effect of PDE-3 inhibitors linked to increased mortality"}, {"name": "Abciximab", "a": "GPIIb/IIIa inhibitor (monoclonal antibody fragment)", "b": "Irreversible binding, but clinical effect is short due to redistribution", "c": "IV only, used periprocedurally in PCI; platelet-bound effect actually outlasts its short plasma half-life"}, {"name": "Eptifibatide", "a": "GPIIb/IIIa inhibitor (cyclic peptide)", "b": "Reversible, short-acting", "c": "Renally cleared - requires dose adjustment in renal impairment; used periprocedurally in high-risk PCI/ACS"}, {"name": "Tirofiban", "a": "GPIIb/IIIa inhibitor (small non-peptide molecule)", "b": "Reversible, short-acting", "c": "Renally cleared; platelet function recovers within hours of stopping the infusion"}, {"name": "Vorapaxar", "a": "PAR-1 (thrombin receptor) antagonist", "b": "Irreversible binding, very long half-life (~8 days)", "c": "Add-on to ASA/clopidogrel for secondary prevention post-MI or in PAD; contraindicated with any history of stroke, TIA, or intracranial hemorrhage"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Low-dose ASA is used and considered safe for pre-eclampsia prevention, but higher doses are avoided near term (bleeding risk, premature ductus arteriosus closure); other antiplatelets lack safety data and are generally avoided unless clearly necessary."}, {"label": "Breastfeeding", "warn": false, "text": "Low-dose ASA is generally considered compatible with breastfeeding; data for clopidogrel, ticagrelor, and prasugrel are limited, so they are used with caution."}, {"label": "Renal impairment", "warn": true, "text": "GPIIb/IIIa inhibitors (eptifibatide, tirofiban) require dose reduction; oral P2Y12 inhibitors need no major dose adjustment, but overall bleeding risk is increased in CKD."}, {"label": "Hepatic impairment", "warn": true, "text": "Ticagrelor is contraindicated in severe hepatic impairment and used cautiously in moderate impairment; clopidogrel's activation depends on hepatic CYP enzymes, so effectiveness may be reduced in significant liver disease."}, {"label": "Elderly", "warn": true, "text": "Bleeding risk rises with age across the class; prasugrel is relatively contraindicated at age ≥75 years."}, {"label": "Pediatrics", "warn": true, "text": "ASA must be avoided in children and teenagers with viral illness due to Reye syndrome risk; other antiplatelets are rarely used in pediatrics and have limited data."}]}, {"key": "biguanides", "topic": "endo", "name": "Biguanides (Metformin)", "pronunciation": "BYE-gwa-nides (met-FOR-min)", "blurb": "First-line oral agent for type 2 diabetes; lowers hepatic glucose output without causing hypoglycemia or weight gain.", "general": ["Mechanism: Activates AMP-activated protein kinase (AMPK) in the liver, which shuts down gluconeogenesis and glycogenolysis, and increases peripheral (muscle/fat) insulin sensitivity. It does not stimulate insulin release, so monotherapy essentially never causes hypoglycemia.", "Class indications: First-line oral therapy for type 2 diabetes (mono or combination), also used off-label for PCOS and prediabetes.", "Class side effects: GI upset (nausea, diarrhea, metallic taste) is very common early and dose-related; rare but serious lactic acidosis in the setting of renal failure, hypoxia, or sepsis; long-term B12 deficiency from reduced ileal absorption.", "Class contraindications: eGFR <30 mL/min/1.73m2 (use caution and reduce dose 30-45), acute or decompensated heart failure, conditions predisposing to lactic acidosis (severe infection, dehydration, IV contrast — hold 48h around contrast), significant hepatic impairment, and heavy alcohol use.", "Class monitoring: eGFR at baseline and at least annually (more often if at risk), B12 periodically with long-term use, GI tolerability during titration, and HbA1c every 3 months until at target."], "memberCols": ["Formulation", "Dosing", "Notable"], "members": [{"name": "Metformin IR (Glucophage)", "a": "Immediate-release", "b": "BID-TID with meals", "c": "Cheapest option; most GI upset — take with food and titrate slowly"}, {"name": "Metformin ER (Glumetza / Glucophage XR)", "a": "Extended-release", "b": "OD, with evening meal", "c": "Better GI tolerability than IR; intact tablet shell may appear in stool — this is expected, not malabsorption"}, {"name": "Metformin/Sitagliptin (Janumet)", "a": "Combo with DPP-4i", "b": "BID", "c": "Convenient single-pill combo; weight-neutral partner drug"}, {"name": "Metformin/Linagliptin (Jentadueto)", "a": "Combo with DPP-4i", "b": "BID", "c": "Linagliptin needs no renal dose adjustment, useful as renal function declines"}, {"name": "Metformin/Saxagliptin (Komboglyze)", "a": "Combo with DPP-4i", "b": "BID", "c": "Saxagliptin carries a caution re: heart failure hospitalization signal"}, {"name": "Metformin/Empagliflozin (Synjardy)", "a": "Combo with SGLT2i", "b": "BID", "c": "Adds CV/renal protective effect; watch for genital mycotic infections"}, {"name": "Metformin/Dapagliflozin (Xigduo XR)", "a": "Combo with SGLT2i", "b": "OD (ER)", "c": "Synergistic weight loss with two mechanisms"}, {"name": "Metformin/Glyburide (Glucovance)", "a": "Combo with sulfonylurea", "b": "BID", "c": "Older combo; inherits sulfonylurea hypoglycemia and weight gain risk"}, {"name": "Metformin/Rosiglitazone (Avandamet)", "a": "Combo with TZD", "b": "BID", "c": "Discontinued in Canada — pulled after cardiovascular safety concerns with rosiglitazone; useful historical teaching point"}, {"name": "Metformin extemporaneous oral solution", "a": "Compounded liquid", "b": "Dosed by weight/mL", "c": "Used for pediatric patients or adults with swallowing difficulty who can't take tablets"}, {"name": "Metformin/Repaglinide", "a": "Combo with meglitinide", "b": "With each meal (repaglinide component)", "c": "Niche option when a sulfonylurea can't be used but a secretagogue is still wanted"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not officially indicated, but a large body of data (including the MiG trial) supports reasonable safety; used in practice for gestational diabetes and PCOS-related infertility. Insulin remains the preferred first-line pharmacotherapy for gestational diabetes in Canada when lifestyle measures fail."}, {"label": "Breastfeeding", "warn": false, "text": "Transfers into breast milk in only small amounts and is generally considered compatible with breastfeeding."}, {"label": "Renal impairment", "warn": true, "text": "The main safety issue for this class. Contraindicated below eGFR 30; reduce dose and monitor closely between eGFR 30-45. Hold before/after IV contrast or major surgery."}, {"label": "Hepatic impairment", "warn": true, "text": "Avoid in significant hepatic impairment — reduced lactate clearance increases lactic acidosis risk."}, {"label": "Elderly", "warn": true, "text": "Age-related decline in renal function increases lactic acidosis risk — check eGFR more frequently than in younger patients."}, {"label": "Pediatrics", "warn": false, "text": "Approved for type 2 diabetes in children 10 years and older; dosing and monitoring otherwise mirror adult use."}]}, {"key": "sulfonylureas", "topic": "endo", "name": "Sulfonylureas", "pronunciation": "sul-fon-il-YOOR-ee-ahs", "blurb": "Insulin secretagogues that stimulate pancreatic beta cells to release insulin; effective and cheap, but carry real hypoglycemia and weight-gain risk.", "general": ["Mechanism: Bind the SUR1 subunit of the ATP-sensitive K+ channel on pancreatic beta cells, closing the channel and triggering membrane depolarization, calcium influx, and insulin release. This insulin release is glucose-independent — the beta cell secretes insulin whether or not glucose is actually high — which is exactly why this class (unlike metformin) can cause hypoglycemia.", "Class indications: Type 2 diabetes, usually as a second-line add-on to metformin, or first-line when rapid and inexpensive glycemic control is needed; not used in type 1 diabetes since it requires functioning beta cells.", "Class side effects: Hypoglycemia (can be severe and prolonged, especially with longer-acting agents in the elderly or renal impairment), weight gain, and rare hypersensitivity reactions.", "Class contraindications: Type 1 diabetes or DKA, severe hepatic or renal impairment (particularly glyburide, which has active renally-cleared metabolites), and known sulfonylurea hypersensitivity.", "Class monitoring: Blood glucose (especially watching for hypoglycemia with missed meals, exercise, or alcohol), HbA1c every 3 months, periodic renal and hepatic function, and weight."], "memberCols": ["Generation", "Duration/half-life", "Notable"], "members": [{"name": "Glyburide (glibenclamide)", "a": "2nd generation", "b": "Long (10-16h) with active metabolites", "c": "Highest hypoglycemia risk in the class, especially in the elderly and renal impairment — avoid per Beers/STOPP criteria"}, {"name": "Gliclazide", "a": "2nd generation", "b": "Intermediate (~10-12h)", "c": "Lower hypoglycemia risk than glyburide; often preferred agent when a sulfonylurea is needed in older adults"}, {"name": "Gliclazide MR (modified release)", "a": "2nd generation", "b": "OD dosing", "c": "Smoother plasma profile than immediate-release gliclazide, better adherence"}, {"name": "Glimepiride", "a": "2nd generation", "b": "Long (~9h, OD dosing)", "c": "Once-daily convenience; can be combined with insulin"}, {"name": "Glipizide", "a": "2nd generation", "b": "Short-intermediate", "c": "Rapid onset; far less commonly used/available in Canada than gliclazide or glimepiride"}, {"name": "Tolbutamide", "a": "1st generation", "b": "Short, multiple daily doses", "c": "Largely obsolete historical agent — high pill burden, weaker potency"}, {"name": "Chlorpropamide", "a": "1st generation", "b": "Very long (up to 36h)", "c": "Essentially discontinued — carries high hypoglycemia and SIADH risk due to its long half-life"}, {"name": "Acetohexamide", "a": "1st generation", "b": "Intermediate", "c": "Historical agent, discontinued — illustrates the shift from 1st to safer 2nd generation agents"}, {"name": "Tolazamide", "a": "1st generation", "b": "Intermediate-long", "c": "Historical agent, discontinued; rarely referenced outside exam history-of-class questions"}, {"name": "Glyburide/Metformin (Glucovance)", "a": "Combo product", "b": "BID", "c": "Fixed-dose combo — convenience comes at the cost of inheriting glyburide's hypoglycemia risk"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Generally avoided — switch to insulin (or in some cases metformin) for glycemic control in pregnancy; glyburide was historically used for gestational diabetes but has fallen out of favour."}, {"label": "Breastfeeding", "warn": true, "text": "Limited data on transfer into breast milk; caution advised and monitor the infant for hypoglycemia if used."}, {"label": "Renal impairment", "warn": true, "text": "Hypoglycemia risk rises sharply as renal clearance falls. Avoid glyburide; gliclazide or glimepiride at reduced doses are safer choices if a sulfonylurea is still needed."}, {"label": "Hepatic impairment", "warn": true, "text": "Reduced hepatic metabolism prolongs drug action and increases hypoglycemia risk — use lower doses and monitor closely, or avoid in significant impairment."}, {"label": "Elderly", "warn": true, "text": "Hypoglycemia is the major concern — avoid glyburide, prefer gliclazide/glimepiride at conservative starting doses, and counsel on recognizing/treating lows."}, {"label": "Pediatrics", "warn": true, "text": "Not well studied and not routinely used in children — type 2 diabetes in pediatrics is usually managed with metformin and/or insulin instead."}]}, {"key": "sglt2", "topic": "endo", "name": "SGLT2 Inhibitors", "pronunciation": "ess-jee-el-tee-two in-HIB-ih-ters (\"gliflozins\")", "blurb": "Block renal glucose reabsorption to cause glucosuria; deliver glycemic control plus proven cardiovascular and renal protection.", "general": ["Mechanism: Inhibit sodium-glucose cotransporter-2 (SGLT2) in the proximal renal tubule, blocking reabsorption of filtered glucose so the excess is excreted in urine. This glucose-lowering effect is insulin-independent, and the accompanying osmotic diuresis/natriuresis is what drives the class's blood pressure, heart failure, and renal benefits — separate from glycemic control.", "Class indications: Type 2 diabetes; heart failure (both HFrEF and HFpEF) regardless of diabetes status; chronic kidney disease with proteinuria, again independent of diabetes status.", "Class side effects: Genital mycotic infections (the glucosuria feeds yeast), UTIs, volume depletion/hypotension, rare euglycemic DKA (blood glucose may be only mildly elevated, so it's easy to miss), and rare Fournier's gangrene.", "Class contraindications: Type 1 diabetes (higher euglycemic DKA risk, not approved for this use), eGFR below the agent-specific cutoff, recurrent severe genital infections, and before major surgery — hold 3-4 days prior due to DKA risk.", "Class monitoring: Renal function, signs of volume depletion (especially with concurrent diuretics or in the elderly), genital hygiene symptoms, urine/blood ketones if unwell (sick-day rules: hold during illness or reduced oral intake), and HbA1c."], "memberCols": ["Renal cutoff", "CV/renal indication", "Notable"], "members": [{"name": "Empagliflozin (Jardiance)", "a": "Can continue to ~eGFR 20 for HF", "b": "T2DM, HFrEF/HFpEF, CKD", "c": "EMPA-REG OUTCOME trial showed cardiovascular death reduction"}, {"name": "Dapagliflozin (Forxiga)", "a": "Can continue to ~eGFR 25 for HF/CKD", "b": "T2DM, HFrEF/HFpEF, CKD (DAPA-CKD)", "c": "Approved for CKD protection even in patients without diabetes"}, {"name": "Canagliflozin (Invokana)", "a": "Stricter eGFR cutoffs than newer agents", "b": "T2DM, diabetic nephropathy (CREDENCE trial)", "c": "CANVAS program flagged a small increased signal for amputation and fracture"}, {"name": "Ertugliflozin (Steglatro)", "a": "Similar cutoffs to canagliflozin", "b": "T2DM only", "c": "Newer to market with less robust CV/renal outcome data than empagliflozin or dapagliflozin"}, {"name": "Empagliflozin/Metformin (Synjardy)", "a": "Follows metformin's stricter renal limit (avoid <30)", "b": "T2DM", "c": "Combines hepatic and renal mechanisms in one pill"}, {"name": "Empagliflozin/Linagliptin (Glyxambi)", "a": "Follows empagliflozin cutoff", "b": "T2DM", "c": "Pairs a weight-loss agent with a weight-neutral DPP-4 inhibitor"}, {"name": "Dapagliflozin/Metformin (Xigduo XR)", "a": "Follows metformin's stricter renal limit", "b": "T2DM", "c": "Once-daily extended-release combo"}, {"name": "Dapagliflozin/Saxagliptin (Qtern)", "a": "Follows dapagliflozin cutoff", "b": "T2DM", "c": "Combo of two once-daily oral classes without a metformin component — useful when metformin is not tolerated"}, {"name": "Canagliflozin/Metformin (Invokamet)", "a": "Follows metformin's stricter renal limit", "b": "T2DM", "c": "Inherits canagliflozin's amputation/fracture caution"}, {"name": "Sotagliflozin (dual SGLT1/2 inhibitor)", "a": "Not marketed in Canada", "b": "Adjunct in type 1 diabetes (approved elsewhere)", "c": "Also blocks intestinal SGLT1, slowing carbohydrate absorption — useful contrast point on how this differs from selective SGLT2 agents"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Contraindicated — no reassuring safety data and the diuretic/volume effects are a theoretical fetal risk; switch to insulin."}, {"label": "Breastfeeding", "warn": true, "text": "Not recommended — insufficient safety data on transfer into breast milk."}, {"label": "Renal impairment", "warn": true, "text": "Glucose-lowering efficacy falls as eGFR declines, but the heart failure and CKD indications specifically allow continuation down to lower eGFR thresholds than the diabetes indication does — check the agent-specific cutoff rather than assuming a blanket rule."}, {"label": "Hepatic impairment", "warn": true, "text": "No dose adjustment needed in mild-moderate impairment; data are limited in severe hepatic impairment, so use with caution."}, {"label": "Elderly", "warn": true, "text": "Increased risk of volume depletion, hypotension, and falls, particularly when combined with diuretics — start low and monitor volume status."}, {"label": "Pediatrics", "warn": true, "text": "Limited pediatric data; some agents (e.g., dapagliflozin, empagliflozin) now have approvals down to age 10 for type 2 diabetes, but use remains more restricted than in adults."}]}, {"key": "glp1", "topic": "endo", "name": "GLP-1 Receptor Agonists", "pronunciation": "jee-el-pee-one receptor AG-on-ists (\"incretin mimetics\")", "blurb": "Injectable (mostly) incretin-based agents that boost glucose-dependent insulin secretion, suppress glucagon, slow gastric emptying, and drive significant weight loss.", "general": ["Mechanism: Mimic endogenous GLP-1 by binding GLP-1 receptors, which enhances glucose-dependent insulin secretion, suppresses glucagon, slows gastric emptying, and acts centrally in the hypothalamus to reduce appetite. Because insulin release stays glucose-dependent, monotherapy carries low hypoglycemia risk. Newer dual agents (tirzepatide) additionally activate GIP receptors, producing greater metabolic effect than GLP-1 activity alone.", "Class indications: Type 2 diabetes; chronic weight management (at higher-dose, weight-loss-specific formulations); reduction of major adverse cardiovascular events in type 2 diabetes with established cardiovascular disease.", "Class side effects: GI effects are very common early (nausea, vomiting, diarrhea) and are the main reason for slow up-titration; injection site reactions (except with the oral tablet); rare acute pancreatitis; gallbladder disease from rapid weight loss; a class boxed warning for thyroid C-cell tumors based on rodent studies.", "Class contraindications: Personal or family history of medullary thyroid carcinoma or MEN2 syndrome, history of pancreatitis (relative caution), severe gastroparesis, and pregnancy.", "Class monitoring: Weight, GI tolerability through dose titration, signs of pancreatitis, gallbladder symptoms, and blood glucose/HbA1c."], "memberCols": ["Dosing frequency", "Route", "Notable"], "members": [{"name": "Liraglutide (Victoza)", "a": "Once daily", "b": "SC injection", "c": "First once-daily GLP-1 agonist marketed in Canada"}, {"name": "Liraglutide, weight-loss dose (Saxenda)", "a": "Once daily", "b": "SC injection", "c": "Same molecule as Victoza at a higher max dose (3 mg), approved specifically for chronic weight management"}, {"name": "Exenatide (Byetta)", "a": "Twice daily", "b": "SC injection", "c": "First-in-class GLP-1 agonist, derived from exendin-4 found in Gila monster saliva; short-acting"}, {"name": "Exenatide extended-release (Bydureon)", "a": "Once weekly", "b": "SC injection", "c": "Microsphere depot formulation; injection-site nodules are a known nuisance side effect"}, {"name": "Dulaglutide (Trulicity)", "a": "Once weekly", "b": "SC injection", "c": "Pre-filled pen with a hidden needle — often preferred by needle-phobic patients; REWIND trial showed CV benefit"}, {"name": "Semaglutide (Ozempic)", "a": "Once weekly", "b": "SC injection", "c": "Strong HbA1c and weight reduction; SUSTAIN and SELECT trial data"}, {"name": "Semaglutide, oral (Rybelsus)", "a": "Once daily", "b": "Oral tablet", "c": "Must be taken fasting with a small sip of water, waiting 30 minutes before food, drink, or other oral medications — otherwise bioavailability is very poor"}, {"name": "Semaglutide, weight-loss dose (Wegovy)", "a": "Once weekly", "b": "SC injection", "c": "Higher-dose formulation approved for chronic weight management; SELECT trial showed CV benefit in overweight/obesity without diabetes"}, {"name": "Tirzepatide (Mounjaro)", "a": "Once weekly", "b": "SC injection", "c": "Dual GIP/GLP-1 agonist — greater HbA1c and weight reduction than GLP-1-only agents in the SURPASS trial program"}, {"name": "Tirzepatide, weight-loss formulation", "a": "Once weekly", "b": "SC injection", "c": "Marketed elsewhere as Zepbound; in Canada tirzepatide's weight-management indication and branding should be confirmed at time of prescribing as availability is still rolling out"}, {"name": "Albiglutide (Tanzeum)", "a": "Once weekly (historical)", "b": "SC injection", "c": "Withdrawn from the market in 2018 for commercial reasons — a useful historical/exam teaching point about a discontinued agent"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not recommended — discontinue at least 2 months before a planned pregnancy (longer-acting agents need more lead time); switch to insulin if pharmacotherapy is needed during pregnancy."}, {"label": "Breastfeeding", "warn": true, "text": "Not recommended — these are large peptide molecules with unknown transfer into breast milk and insufficient safety data."}, {"label": "Renal impairment", "warn": true, "text": "GI side effects causing volume loss can worsen renal function in a vicious cycle; most agents need no specific dose adjustment but should be used cautiously and doses individualized at severe impairment."}, {"label": "Hepatic impairment", "warn": false, "text": "No dose adjustment is generally required, though data in severe hepatic impairment remain limited."}, {"label": "Elderly", "warn": true, "text": "More prone to GI intolerance, dehydration, and weight loss that can tip a frail patient into sarcopenia — titrate slowly and monitor nutritional status."}, {"label": "Pediatrics", "warn": true, "text": "Only specific agents (e.g., liraglutide, dulaglutide, semaglutide) are approved for adolescents down to ages 10-12 for type 2 diabetes or weight management, under defined criteria — not a general class approval."}]}, {"key": "dpp4-inhibitors", "topic": "endo", "name": "DPP-4 Inhibitors", "pronunciation": "dee-pee-pee-four in-HIB-ih-ters", "blurb": "Oral, weight-neutral agents for type 2 diabetes that enhance the body's own incretin effect with a low risk of hypoglycemia.", "general": ["Mechanism: Inhibit dipeptidyl peptidase-4, the enzyme that normally degrades endogenous incretins (GLP-1 and GIP) within minutes of release. Higher circulating incretin levels increase glucose-dependent insulin secretion and suppress glucagon, so the effect only kicks in when glucose is elevated — this is why hypoglycemia risk is low as monotherapy.", "Class indications: Type 2 diabetes as monotherapy or add-on to metformin, sulfonylureas, or insulin when an oral, weight-neutral option with low hypoglycemia risk is desired.", "Class side effects: Generally well tolerated — nasopharyngitis, headache; rare but serious risks include acute pancreatitis and severe joint pain; saxagliptin/alogliptin carry a heart failure hospitalization signal.", "Class contraindications: History of hypersensitivity reaction (angioedema/anaphylaxis) to any DPP-4 inhibitor; caution with history of pancreatitis.", "Class monitoring: A1C every 3 months until stable; renal function at baseline and periodically (most members need dose adjustment in renal impairment); watch for signs of pancreatitis (persistent severe abdominal pain) and joint pain."], "memberCols": ["Renal Dosing Needed?", "Hepatic Considerations", "Notable"], "members": [{"name": "Sitagliptin", "a": "Yes — reduce dose as CrCl falls", "b": "No adjustment needed", "c": "First-in-class; once daily; most prescribed in Canada"}, {"name": "Saxagliptin", "a": "Yes — reduce dose if CrCl <50", "b": "No adjustment needed", "c": "SAVOR-TIMI 53 showed increased heart failure hospitalizations — avoid in HF"}, {"name": "Linagliptin", "a": "No — primarily biliary/fecal excretion", "b": "No adjustment needed", "c": "Only DPP-4i needing no renal dose adjustment — useful in CKD/dialysis"}, {"name": "Alogliptin", "a": "Yes — reduce dose as CrCl falls", "b": "No adjustment needed", "c": "Also carries HF hospitalization signal (EXAMINE trial)"}, {"name": "Vildagliptin (not marketed in Canada)", "a": "Yes", "b": "Avoid in hepatic impairment (rare hepatotoxicity)", "c": "Included for exam recognition — not on the Canadian market"}, {"name": "Sitagliptin/Metformin (Janumet)", "a": "Follow metformin renal limits", "b": "Follow metformin hepatic limits", "c": "Fixed-dose combination; convenience product"}, {"name": "Saxagliptin/Metformin (Komboglyze)", "a": "Follow metformin renal limits", "b": "Follow metformin hepatic limits", "c": "Fixed-dose combination"}, {"name": "Linagliptin/Metformin (Jentadueto)", "a": "Follow metformin renal limits", "b": "Follow metformin hepatic limits", "c": "Fixed-dose combination; linagliptin component needs no renal adjustment"}, {"name": "Alogliptin/Metformin (Kazano, not marketed in Canada)", "a": "Follow metformin renal limits", "b": "Follow metformin hepatic limits", "c": "Included for exam recognition"}, {"name": "Alogliptin/Pioglitazone (Oseni, not marketed in Canada)", "a": "Yes for alogliptin component", "b": "Avoid in significant hepatic impairment", "c": "Combination with a TZD — watch for fluid retention/edema"}, {"name": "Sitagliptin/Empagliflozin combinations (used off cross-reference)", "a": "Yes, follow SGLT2 renal cutoffs", "b": "No adjustment needed", "c": "Highlights class overlap in modern combo regimens (exam context only)"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not recommended — insulin is preferred for glycemic control in pregnancy; limited human safety data for DPP-4 inhibitors."}, {"label": "Breastfeeding", "warn": true, "text": "Not recommended due to lack of safety data; unknown whether excreted in breast milk in clinically relevant amounts."}, {"label": "Renal impairment", "warn": true, "text": "Most members (sitagliptin, saxagliptin, alogliptin) require dose reduction as CrCl declines; linagliptin is the exception and needs no adjustment, making it a preferred choice in CKD."}, {"label": "Hepatic impairment", "warn": false, "text": "No dose adjustment generally needed for mild-moderate hepatic impairment; limited data in severe impairment so use with caution."}, {"label": "Elderly", "warn": false, "text": "Well tolerated with low hypoglycemia risk, making this class a reasonable choice in frail elderly patients, but still check renal function before dosing."}, {"label": "Pediatrics", "warn": true, "text": "Safety and efficacy not established in patients under 18 years — not indicated for pediatric type 2 diabetes."}]}, {"key": "insulins", "topic": "endo", "name": "Insulins", "pronunciation": "IN-suh-lins", "blurb": "A spectrum of rapid to ultra-long-acting products used to mimic physiologic basal and bolus insulin secretion in diabetes.", "general": ["Mechanism: Bind the insulin receptor to drive glucose uptake into skeletal muscle and adipose tissue via GLUT4 translocation, suppress hepatic gluconeogenesis/glycogenolysis, and inhibit lipolysis. Formulation chemistry (amino acid substitutions, protamine complexing, fatty acid acylation) is engineered purely to change absorption kinetics from the subcutaneous depot — the receptor-level mechanism is identical across all products.", "Class indications: Type 1 diabetes (absolute requirement), type 2 diabetes uncontrolled on oral/injectable agents, gestational diabetes, diabetic ketoacidosis/hyperglycemic emergencies, and perioperative or hospital glycemic control.", "Class side effects: Hypoglycemia (the dose-limiting risk for the whole class), weight gain, lipodystrophy or lipohypertrophy at injection sites with repeated use in the same spot, and local injection site reactions.", "Class contraindications: Hypoglycemia itself is an absolute contraindication to dosing at that moment; hypersensitivity to a specific product or its excipients (e.g., protamine, metacresol) requires switching formulations.", "Class monitoring: Self-monitored blood glucose or continuous glucose monitoring, A1C every 3 months, injection site rotation/inspection for lipohypertrophy, and periodic reassessment of hypoglycemia awareness, especially in long-duration type 1 diabetes."], "memberCols": ["Onset", "Peak", "Duration"], "members": [{"name": "Insulin lispro (Humalog)", "a": "10-15 min", "b": "1-2 hr", "c": "3-5 hr — rapid-acting bolus analog, dose with meals"}, {"name": "Insulin aspart (NovoRapid)", "a": "10-15 min", "b": "1-1.5 hr", "c": "3-5 hr — rapid-acting bolus analog; faster aspart (Fiasp) has near-immediate onset"}, {"name": "Insulin glulisine (Apidra)", "a": "10-15 min", "b": "1-1.5 hr", "c": "3-5 hr — rapid-acting bolus analog, comparable to lispro/aspart"}, {"name": "Regular insulin (Humulin R, Novolin ge Toronto)", "a": "30 min", "b": "2-3 hr", "c": "6.5-8 hr — short-acting; must be dosed 30 min before meals due to slower onset"}, {"name": "NPH insulin (Humulin N, Novolin ge NPH)", "a": "1-3 hr", "b": "5-8 hr", "c": "up to 18 hr — intermediate-acting, cloudy suspension, must resuspend by gentle rolling before dosing"}, {"name": "Insulin glargine U-100 (Lantus, Basaglar)", "a": "1.5 hr", "b": "relatively flat, no pronounced peak", "c": "24 hr — long-acting basal analog, once daily"}, {"name": "Insulin detemir (Levemir)", "a": "1-2 hr", "b": "relatively flat, minimal peak", "c": "16-24 hr — long-acting basal analog, may require twice-daily dosing for full 24 hr coverage"}, {"name": "Insulin glargine U-300 (Toujeo)", "a": "6 hr", "b": "flat, no peak", "c": "up to 36 hr — ultra-long acting; more concentrated depot slows absorption further than U-100 glargine"}, {"name": "Insulin degludec (Tresiba)", "a": "1 hr", "b": "no pronounced peak", "c": "up to 42 hr — ultra-long acting with the flattest profile and most dosing-time flexibility"}, {"name": "NPH/Regular 70/30 (Humulin 70/30, Novolin ge 30/70)", "a": "30 min (regular component)", "b": "dual peak, 2-3 hr and 5-8 hr", "c": "up to 18 hr — premixed, fixed ratio, dosed twice daily with meals"}, {"name": "Insulin aspart biphasic 70/30 (NovoMix 30)", "a": "10-15 min (aspart component)", "b": "dual peak, 1-4 hr", "c": "up to 18 hr — premixed rapid analog/protaminated aspart combination"}, {"name": "Insulin lispro 75/25 or 50/50 (Humalog Mix25/Mix50)", "a": "10-15 min (lispro component)", "b": "dual peak", "c": "up to 18 hr — premixed, useful when postprandial coverage plus basal is needed in one injection"}, {"name": "Insulin degludec/insulin aspart (Ryzodeg)", "a": "10-15 min (aspart component)", "b": "aspart peak ~1-2 hr, degludec flat", "c": "up to 24+ hr — co-formulation (not a mix in the traditional sense) combining ultra-long basal with rapid bolus coverage"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Insulin is the preferred glucose-lowering agent in pregnancy (any type of diabetes); NPH, regular, lispro, aspart, and detemir have the most established safety data — dose requirements rise sharply in the second/third trimester."}, {"label": "Breastfeeding", "warn": false, "text": "Compatible with breastfeeding — insulin is a large peptide destroyed in the infant GI tract and does not pass through in clinically significant amounts; watch for maternal hypoglycemia risk from lactation's added glucose demand."}, {"label": "Renal impairment", "warn": true, "text": "Insulin clearance falls as renal function declines, so total daily dose requirements typically decrease and hypoglycemia risk rises — reduce doses and monitor closely, especially with long-acting/basal products."}, {"label": "Hepatic impairment", "warn": true, "text": "Reduced hepatic insulin clearance and impaired gluconeogenesis increase hypoglycemia risk — lower starting doses and monitor glucose closely."}, {"label": "Elderly", "warn": true, "text": "Higher hypoglycemia risk due to irregular eating, polypharmacy, and reduced hypoglycemia awareness — favor simpler regimens and less hypoglycemia-prone basal analogs (degludec, glargine) over NPH where possible."}, {"label": "Pediatrics", "warn": false, "text": "Used routinely from infancy for type 1 diabetes; dosing is weight-based and requires careful titration with caregiver/patient education on carbohydrate counting and hypoglycemia recognition."}]}, {"key": "bisphosphonates", "topic": "endo", "name": "Bisphosphonates", "pronunciation": "bis-FOS-foh-nates", "blurb": "First-line antiresorptive agents for osteoporosis that bind bone mineral and shut down osteoclast-mediated bone breakdown.", "general": ["Mechanism: Bind avidly to hydroxyapatite at sites of active bone remodeling and are taken up by osteoclasts during resorption; nitrogen-containing members then inhibit farnesyl pyrophosphate synthase in the mevalonate pathway, disrupting osteoclast cytoskeleton function and inducing apoptosis. Because they embed in bone matrix, effects on bone turnover persist for months to years after stopping (especially with alendronate/zoledronic acid).", "Class indications: Osteoporosis (postmenopausal, male, and glucocorticoid-induced), Paget's disease of bone, hypercalcemia of malignancy, and bone metastases (IV members, oncology dosing).", "Class side effects: Upper GI irritation/esophagitis (oral agents), acute phase reaction with fever/myalgia after first IV dose, hypocalcemia, and rare but serious osteonecrosis of the jaw and atypical femur fractures with long-term use.", "Class contraindications: Hypocalcemia (must correct before starting), esophageal abnormalities that delay transit (achalasia, stricture) and inability to sit upright for oral agents, severe renal impairment (CrCl <30-35 mL/min depending on agent).", "Class monitoring: Baseline and periodic serum calcium/vitamin D/renal function, dental exam before starting (osteonecrosis of the jaw risk), bone mineral density every 1-3 years, and reassessment of ongoing need (drug holiday) after 3-5 years of oral or 3 years of IV therapy."], "memberCols": ["Route", "Dosing Frequency", "Notable"], "members": [{"name": "Alendronate (Fosamax)", "a": "Oral", "b": "Once weekly", "c": "Must stay upright 30 min after; first-line, extensive fracture data at hip and spine"}, {"name": "Risedronate (Actonel)", "a": "Oral", "b": "Once weekly or once monthly", "c": "Delayed-release monthly formulation allows dosing after breakfast instead of fasting"}, {"name": "Etidronate (Didrocal)", "a": "Oral", "b": "Cyclical — 14 days on, 76 days off with calcium", "c": "Older, weaker agent; largely replaced by newer bisphosphonates in practice"}, {"name": "Ibandronate (Bondronat, IV oncology use)", "a": "IV", "b": "Every 3-4 weeks (oncology dosing)", "c": "Used for bone metastases/hypercalcemia of malignancy in Canada; oral form not commonly used here"}, {"name": "Zoledronic acid (Aclasta — osteoporosis)", "a": "IV infusion", "b": "Once yearly", "c": "Best adherence of the class since dosed once a year; causes acute phase reaction in ~30% after first infusion"}, {"name": "Zoledronic acid (Zometa — oncology)", "a": "IV infusion", "b": "Every 3-4 weeks (oncology dosing)", "c": "Same molecule as Aclasta but oncology dosing/indication (bone metastases, hypercalcemia of malignancy)"}, {"name": "Pamidronate (Aredia)", "a": "IV infusion", "b": "Every 3-4 weeks (oncology) or single dose (hypercalcemia)", "c": "Older IV agent, largely for hypercalcemia of malignancy and Paget's disease"}, {"name": "Alendronate/cholecalciferol (Fosavance)", "a": "Oral", "b": "Once weekly", "c": "Fixed-dose combination adding vitamin D3 to alendronate for convenience"}, {"name": "Risedronate delayed-release (Actonel DR)", "a": "Oral", "b": "Once weekly", "c": "Enteric-coated formulation taken immediately after breakfast, avoiding the fasting requirement"}, {"name": "Clodronate (Bonefos, not routinely used in Canada)", "a": "Oral or IV", "b": "Daily (oral)", "c": "Included for exam recognition — used mainly in oncology settings in some jurisdictions"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Avoid — animal data show fetal skeletal effects and the long skeletal retention means exposure could theoretically continue into a future pregnancy; use only if benefit clearly outweighs risk."}, {"label": "Breastfeeding", "warn": true, "text": "Limited data; because bisphosphonates are retained in bone for years, avoid unless clearly needed — non-pharmacologic and calcium/vitamin D optimization preferred during lactation."}, {"label": "Renal impairment", "warn": true, "text": "Contraindicated or requires caution below specific CrCl cutoffs (commonly <30-35 mL/min depending on the agent) since they are renally eliminated and can worsen renal function, particularly IV formulations given rapidly."}, {"label": "Hepatic impairment", "warn": false, "text": "No specific dose adjustment required — bisphosphonates are not hepatically metabolized to a clinically significant degree."}, {"label": "Elderly", "warn": false, "text": "Primary population treated for osteoporosis; ensure adequate calcium/vitamin D intake and renal function assessment before starting, and address swallowing/mobility issues that affect oral dosing instructions."}, {"label": "Pediatrics", "warn": true, "text": "Not approved for routine pediatric osteoporosis; used only in specialized settings (e.g., osteogenesis imperfecta) under specialist supervision."}]}, {"key": "beta2-agonists", "topic": "resp", "name": "Beta-2 Agonists (SABA/LABA)", "pronunciation": "BAY-tuh-two AY-goh-nists", "blurb": "Bronchodilators that relax airway smooth muscle for quick relief (SABA) or maintenance control (LABA) of asthma and COPD.", "general": ["Mechanism: Stimulate beta-2 adrenergic receptors on bronchial smooth muscle, activating adenylate cyclase to raise intracellular cAMP, which relaxes smooth muscle and dilates the airway. Lipophilicity and receptor-binding kinetics determine onset/duration — highly lipophilic long-acting members partition into the membrane near the receptor for a sustained effect, explaining the SABA-vs-LABA split.", "Class indications: SABAs for quick relief of acute bronchospasm and pre-exercise prophylaxis in asthma/COPD; LABAs for maintenance bronchodilation in asthma (always with an ICS, never alone) and COPD.", "Class side effects: Tachycardia/palpitations, tremor, headache, and hypokalemia (beta-2 stimulation drives potassium intracellularly) — dose-dependent and more common with nebulized or oral routes than inhaled.", "Class contraindications: Caution rather than absolute contraindication in most cases — significant tachyarrhythmias and uncontrolled hyperthyroidism warrant caution; LABA monotherapy without a concomitant ICS is contraindicated in asthma due to increased risk of severe exacerbation and asthma-related death.", "Class monitoring: Frequency of SABA use (overuse signals poor asthma control and predicts exacerbation risk), heart rate/rhythm, serum potassium with high-dose or nebulized therapy, and inhaler technique at every visit."], "memberCols": ["SABA or LABA", "Onset", "Duration"], "members": [{"name": "Salbutamol (Ventolin, ProAir)", "a": "SABA", "b": "5 min", "c": "4-6 hr — first-line rescue inhaler; also available as nebule solution"}, {"name": "Terbutaline (Bricanyl)", "a": "SABA", "b": "5-15 min", "c": "4-6 hr — less commonly used than salbutamol in Canada; also available as subcutaneous injection"}, {"name": "Fenoterol (in combination products)", "a": "SABA", "b": "5 min", "c": "4-6 hr — mainly encountered as part of combination products internationally"}, {"name": "Formoterol (Oxeze, and in combination inhalers)", "a": "LABA", "b": "1-3 min — fast enough for as-needed use", "c": "12 hr — unique among LABAs for its rapid onset, allowing SMART/MART regimens with budesonide"}, {"name": "Salmeterol (Serevent)", "a": "LABA", "b": "10-20 min — too slow for rescue use", "c": "12 hr — must never be used as monotherapy or for acute symptom relief"}, {"name": "Indacaterol (Onbrez)", "a": "LABA (ultra-long)", "b": "5 min", "c": "24 hr — once-daily LABA used in COPD, typically in combination products"}, {"name": "Olodaterol (Striverdi)", "a": "LABA (ultra-long)", "b": "within minutes", "c": "24 hr — once-daily LABA for COPD, often paired with tiotropium (Inspiolto)"}, {"name": "Vilanterol (in combination products only, e.g., Breo Ellipta)", "a": "LABA (ultra-long)", "b": "within minutes", "c": "24 hr — never marketed alone, only as part of ICS/LABA combinations"}, {"name": "Salmeterol/fluticasone (Advair)", "a": "LABA + ICS combination", "b": "10-20 min", "c": "12 hr — classic combination inhaler for asthma and COPD maintenance"}, {"name": "Formoterol/budesonide (Symbicort)", "a": "LABA + ICS combination", "b": "1-3 min", "c": "12 hr — used for both maintenance and SMART/MART reliever therapy in asthma"}, {"name": "Formoterol/mometasone (Zenhale)", "a": "LABA + ICS combination", "b": "1-3 min", "c": "12 hr — alternative ICS/LABA combination"}, {"name": "Vilanterol/fluticasone furoate (Breo Ellipta)", "a": "LABA + ICS combination", "b": "within minutes", "c": "24 hr — once-daily combination for asthma and COPD"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Inhaled beta-2 agonists (both SABA and LABA) are considered safe in pregnancy — uncontrolled asthma poses greater fetal risk than the medication, so treatment should continue as needed."}, {"label": "Breastfeeding", "warn": false, "text": "Compatible with breastfeeding — minimal systemic absorption from inhaled routes results in negligible transfer into breast milk."}, {"label": "Renal impairment", "warn": false, "text": "No specific dose adjustment required; these agents are not significantly renally eliminated."}, {"label": "Hepatic impairment", "warn": false, "text": "No specific dose adjustment required for standard inhaled use."}, {"label": "Elderly", "warn": true, "text": "Increased sensitivity to cardiovascular side effects (tachycardia, arrhythmia) and hypokalemia, particularly with nebulized or higher doses — use the lowest effective dose and monitor cardiac status."}, {"label": "Pediatrics", "warn": false, "text": "SABAs are first-line rescue therapy from early childhood; LABAs are used only in combination with an ICS and per age-specific approvals — never as monotherapy in children with asthma."}]}, {"key": "ics", "topic": "resp", "name": "Inhaled Corticosteroids (ICS)", "pronunciation": "in-HALED kor-tih-koh-STEER-oyds", "blurb": "Foundation of maintenance therapy for persistent asthma and add-on therapy in COPD with an eosinophilic/exacerbation-prone phenotype.", "general": ["Mechanism: Diffuse into airway epithelial and inflammatory cells and bind glucocorticoid receptors, which translocate to the nucleus and switch off transcription of pro-inflammatory cytokines (IL-4, IL-5, IL-13) while upregulating anti-inflammatory genes and beta-2 receptor expression — this reduces airway mucosal inflammation, edema, and mucus hypersecretion over days to weeks, which is why ICS control disease but do not relieve acute bronchospasm.", "Class indications: First-line controller for persistent asthma at all severities (step 1-2 as needed with formoterol per GINA, or scheduled from step 2 up); add-on to LABA/LAMA in COPD patients with frequent exacerbations and blood eosinophilia; croup (nebulized budesonide).", "Class side effects: Local effects from drug deposition in the oropharynx — oral candidiasis (thrush) and dysphonia (hoarseness) from direct laryngeal muscle myopathy; systemic absorption at high doses can cause adrenal suppression, growth velocity reduction in children, easy bruising, and increased ocular pressure/cataract risk with long-term high-dose use.", "Class contraindications: No absolute contraindications at typical doses; caution with active untreated respiratory tract infections (including TB) and in patients on potent CYP3A4 inhibitors (e.g., ritonavir) which can dramatically raise systemic fluticasone/budesonide levels and cause Cushing syndrome.", "Class monitoring: Rinse mouth and spit after every dose to prevent thrush; use a spacer with MDIs to reduce oropharyngeal deposition; monitor growth (height) in children on chronic therapy; assess inhaler technique and adherence at every visit since most 'ICS failure' is technique failure."], "memberCols": ["Relative potency", "Device(s)", "Notable"], "members": [{"name": "Budesonide", "a": "Medium", "b": "Turbuhaler, nebules, Pulmicort", "c": "Only ICS available as a nebule in Canada; used for croup; combined with formoterol (Symbicort) for SMART therapy"}, {"name": "Fluticasone propionate", "a": "Medium-high", "b": "MDI (Flovent), Diskus combos", "c": "More lipophilic than budesonide — longer airway retention but more oropharyngeal deposition without a spacer"}, {"name": "Fluticasone furoate", "a": "High", "b": "Ellipta (Arnuity, Breo)", "c": "Once-daily dosing due to prolonged airway residence time"}, {"name": "Beclomethasone dipropionate (HFA, extra-fine)", "a": "Medium-high", "b": "MDI (Qvar)", "c": "Extra-fine particle formulation gives better small-airway/peripheral lung deposition"}, {"name": "Ciclesonide", "a": "Medium", "b": "MDI (Alvesco)", "c": "Prodrug activated by lung esterases only after deposition — lowest oropharyngeal side effect rate of the class"}, {"name": "Mometasone furoate", "a": "Medium-high", "b": "Twisthaler, MDI (Asmanex)", "c": "Once-daily option; also combined with formoterol (Zenhale)"}, {"name": "Fluticasone/salmeterol (Advair)", "a": "Medium-high (combo)", "b": "Diskus, MDI", "c": "First ICS/LABA combo marketed in Canada; not approved for SMART (as-needed) use"}, {"name": "Budesonide/formoterol (Symbicort)", "a": "Medium (combo)", "b": "Turbuhaler", "c": "Approved for both maintenance and SMART/MART reliever use because formoterol has fast onset"}, {"name": "Fluticasone furoate/vilanterol (Breo Ellipta)", "a": "High (combo)", "b": "Ellipta", "c": "Once-daily ICS/LABA; also approved for COPD"}, {"name": "Mometasone/formoterol (Zenhale)", "a": "Medium-high (combo)", "b": "MDI", "c": "Twice-daily ICS/LABA combination"}, {"name": "Fluticasone furoate/umeclidinium/vilanterol (Trelegy Ellipta)", "a": "High (triple)", "b": "Ellipta", "c": "Once-daily ICS/LAMA/LABA triple therapy for COPD"}, {"name": "Budesonide nebules (Pulmicort Respules)", "a": "Medium", "b": "Nebulizer", "c": "First-line for pediatric croup and for patients unable to use handheld devices"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Considered safe throughout pregnancy — uncontrolled asthma poses greater fetal risk (hypoxia, IUGR) than ICS exposure; budesonide has the most reassurance data and is often preferred, but continuing the patient's existing effective ICS is reasonable."}, {"label": "Breastfeeding", "warn": false, "text": "Compatible — minimal systemic absorption at standard doses means negligible transfer into breast milk."}, {"label": "Renal impairment", "warn": false, "text": "No dose adjustment needed; ICS are cleared hepatically, not renally."}, {"label": "Hepatic impairment", "warn": true, "text": "Severe hepatic impairment can reduce first-pass metabolism of swallowed drug, modestly increasing systemic exposure — use the lowest effective dose and monitor for systemic corticosteroid effects."}, {"label": "Elderly", "warn": true, "text": "Higher risk of oral candidiasis, skin bruising, and cataracts/glaucoma with long-term high-dose use; ensure spacer use and good inhaler technique, which is often reduced by arthritis or cognitive impairment."}, {"label": "Pediatrics", "warn": true, "text": "Monitor linear growth at least annually — chronic ICS use causes a small (~1 cm), largely non-cumulative reduction in growth velocity in the first year of therapy; use the lowest dose that controls symptoms."}]}, {"key": "lama", "topic": "resp", "name": "LAMAs (Long-Acting Muscarinic Antagonists)", "pronunciation": "long-ACT-ing mus-kuh-RIN-ik an-TAG-oh-nists (LAH-muhz)", "blurb": "First-line maintenance bronchodilator for COPD and add-on option for uncontrolled asthma, providing 24-hour bronchodilation via anticholinergic blockade.", "general": ["Mechanism: Competitively and selectively block M3 muscarinic receptors on airway smooth muscle, preventing acetylcholine-mediated bronchoconstriction and mucus gland secretion; because they dissociate slowly from the receptor (unlike ipratropium), they provide sustained 24-hour bronchodilation with once- or twice-daily dosing.", "Class indications: First-line maintenance monotherapy or combination therapy for COPD (reduces exacerbation frequency); add-on therapy (tiotropium mist inhaler) for severe asthma uncontrolled on ICS/LABA; some agents used pre-operatively/for chronic rhinorrhea off-label.", "Class side effects: Dry mouth is most common; also constipation, urinary retention/hesitancy, and blurred vision if the spray contacts the eyes; systemic absorption is low because these are quaternary ammonium compounds that don't readily cross the blood-brain barrier or membranes.", "Class contraindications: Caution (relative contraindication) in narrow-angle glaucoma (mist can precipitate an acute attack if it contacts the eye) and in men with symptomatic benign prostatic hyperplasia/bladder outlet obstruction due to urinary retention risk.", "Class monitoring: Assess symptom control and exacerbation frequency; ask about urinary symptoms and eye pain/blurred vision; ensure correct inhaler/mist technique, including keeping the Respimat spray away from the eyes."], "memberCols": ["Dosing frequency", "Device", "Notable"], "members": [{"name": "Tiotropium (Spiriva HandiHaler)", "a": "Once daily", "b": "Dry powder capsule inhaler", "c": "First LAMA approved; extensive COPD exacerbation-reduction evidence (UPLIFT trial)"}, {"name": "Tiotropium (Spiriva Respimat)", "a": "Once daily", "b": "Soft-mist inhaler", "c": "Also approved for severe asthma add-on (only LAMA with this asthma indication in Canada)"}, {"name": "Umeclidinium (Incruse Ellipta)", "a": "Once daily", "b": "Ellipta dry powder", "c": "Simple once-daily monotherapy device; also in combo products"}, {"name": "Glycopyrronium (Seebri Breezhaler)", "a": "Once daily", "b": "Breezhaler capsule", "c": "Fast onset of action (within 5 minutes)"}, {"name": "Aclidinium (Tudorza Genuair)", "a": "Twice daily", "b": "Genuair multi-dose device", "c": "Shorter systemic half-life — twice-daily dosing theoretically reduces cardiovascular anticholinergic burden"}, {"name": "Revefenacin", "a": "Once daily", "b": "Nebulizer solution", "c": "Not currently marketed in Canada; nebulized option used in the US for patients unable to use handheld devices"}, {"name": "Umeclidinium/vilanterol (Anoro Ellipta)", "a": "Once daily (combo)", "b": "Ellipta", "c": "LAMA/LABA combination for COPD maintenance"}, {"name": "Glycopyrronium/indacaterol (Ultibro Breezhaler)", "a": "Once daily (combo)", "b": "Breezhaler", "c": "LAMA/LABA combo; indacaterol component gives rapid onset"}, {"name": "Aclidinium/formoterol (Duaklir Genuair)", "a": "Twice daily (combo)", "b": "Genuair", "c": "Twice-daily LAMA/LABA combination"}, {"name": "Tiotropium/olodaterol (Inspiolto Respimat)", "a": "Once daily (combo)", "b": "Respimat", "c": "LAMA/LABA soft-mist combination"}, {"name": "Fluticasone furoate/umeclidinium/vilanterol (Trelegy Ellipta)", "a": "Once daily (triple)", "b": "Ellipta", "c": "ICS/LAMA/LABA triple therapy in one device"}, {"name": "Ipratropium (for comparison — SAMA, not LAMA)", "a": "QID (short-acting)", "b": "MDI/nebule", "c": "Short-acting muscarinic antagonist; included for contrast — dissociates quickly from M2/M3 receptors so needs frequent dosing"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Limited human data but minimal systemic absorption is reassuring; use only if clearly needed and benefit outweighs theoretical risk, generally reserved for patients already stable on a LAMA pre-pregnancy."}, {"label": "Breastfeeding", "warn": false, "text": "Low systemic bioavailability makes clinically significant transfer into breast milk unlikely; considered compatible."}, {"label": "Renal impairment", "warn": true, "text": "Several agents (tiotropium, umeclidinium) are partly renally eliminated — use with caution and monitor for anticholinergic side effects in severe renal impairment (CrCl <50 mL/min for HandiHaler)."}, {"label": "Hepatic impairment", "warn": false, "text": "No dose adjustment generally required as hepatic metabolism is a minor elimination pathway for most agents."}, {"label": "Elderly", "warn": true, "text": "Higher baseline risk of undiagnosed narrow-angle glaucoma and BPH — screen for urinary retention and eye pain; anticholinergic burden adds to other medications (antihistamines, tricyclics) and may worsen constipation or cognitive fog."}, {"label": "Pediatrics", "warn": true, "text": "Not established/approved for children in Canada except select nebulized ipratropium use in acute asthma exacerbations; LAMAs are not routine pediatric maintenance therapy."}]}, {"key": "ltra", "topic": "resp", "name": "Leukotriene Receptor Antagonists", "pronunciation": "loo-koh-TRY-een ree-SEP-ter an-TAG-oh-nists", "blurb": "Oral add-on/alternative controller for asthma and allergic rhinitis, particularly useful for exercise-induced bronchoconstriction and aspirin-exacerbated respiratory disease.", "general": ["Mechanism: Block the cysteinyl leukotriene receptor (CysLT1) on airway smooth muscle and inflammatory cells, preventing leukotrienes (released from mast cells and eosinophils) from causing bronchoconstriction, mucus secretion, and airway edema — leukotrienes are especially important in exercise-induced and aspirin-induced bronchospasm, which is why this class works well in those specific triggers.", "Class indications: Add-on maintenance therapy for mild-to-moderate persistent asthma (alternative or add-on to ICS), exercise-induced bronchoconstriction prevention, allergic rhinitis (seasonal and perennial), and aspirin-exacerbated respiratory disease (Samter's triad).", "Class side effects: Generally well tolerated; headache and GI upset are most common; montelukast carries a boxed warning (Health Canada advisory) for neuropsychiatric events — agitation, aggression, nightmares, depression, and rarely suicidal thinking, especially in children/adolescents.", "Class contraindications: No absolute contraindications; zafirlukast and zileuton (not marketed in Canada) can cause hepatotoxicity and require liver enzyme monitoring; caution using montelukast in patients with a personal/family history of depression or self-harm given the neuropsychiatric signal.", "Class monitoring: Counsel patients/caregivers to report any mood, behavior, or sleep changes (nightmares, irritability, agitation) after starting montelukast and to seek care immediately for suicidal thoughts; this class is NOT a rescue medication — it does not treat acute bronchospasm."], "memberCols": ["Target", "Dosing", "Notable"], "members": [{"name": "Montelukast (Singulair, generics)", "a": "CysLT1 receptor", "b": "Once daily, evening", "c": "Only LTRA widely used in Canada; available as tablet, chewable, and granules for pediatric use as young as 6 months"}, {"name": "Zafirlukast", "a": "CysLT1 receptor", "b": "Twice daily, empty stomach", "c": "Not currently marketed in Canada; requires dosing away from food and periodic LFT monitoring"}, {"name": "Pranlukast", "a": "CysLT1 receptor", "b": "Twice daily", "c": "Not available in Canada or the US; used in Japan and parts of Asia"}, {"name": "Zileuton", "a": "5-lipoxygenase inhibitor (upstream of receptor)", "b": "Multiple times daily", "c": "Not marketed in Canada; inhibits leukotriene synthesis itself rather than blocking the receptor, requires regular LFT monitoring"}, {"name": "Montelukast 10 mg tablet", "a": "CysLT1 receptor", "b": "Once daily, evening", "c": "Standard adult/adolescent (≥15 years) dose"}, {"name": "Montelukast 5 mg chewable", "a": "CysLT1 receptor", "b": "Once daily, evening", "c": "Pediatric formulation for ages 6-14 years"}, {"name": "Montelukast 4 mg chewable", "a": "CysLT1 receptor", "b": "Once daily, evening", "c": "Pediatric formulation for ages 2-5 years"}, {"name": "Montelukast 4 mg oral granules", "a": "CysLT1 receptor", "b": "Once daily, evening", "c": "For children 6 months to 5 years; can be sprinkled on soft food or given directly"}, {"name": "Montelukast (exercise-induced bronchoconstriction dosing)", "a": "CysLT1 receptor", "b": "Single dose ≥2h pre-exercise", "c": "Distinct PRN regimen for EIB prevention rather than daily scheduled dosing; do not double-dose if already on daily montelukast"}, {"name": "Montelukast (allergic rhinitis dosing)", "a": "CysLT1 receptor", "b": "Once daily, evening", "c": "Same tablet/dose as asthma indication; approved alternative to intranasal steroids/antihistamines for seasonal and perennial allergic rhinitis"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Montelukast is considered a reasonable option in pregnancy when already effective, as observational data have not shown a clear increase in major malformations; ICS remain preferred first-line, but LTRAs can continue if well-controlled asthma depends on them."}, {"label": "Breastfeeding", "warn": false, "text": "Limited data but montelukast is minimally excreted into breast milk and considered compatible."}, {"label": "Renal impairment", "warn": false, "text": "No dose adjustment required — montelukast is eliminated almost entirely via hepatic/biliary excretion."}, {"label": "Hepatic impairment", "warn": true, "text": "Use with caution in moderate-severe hepatic impairment as montelukast is extensively hepatically metabolized (CYP3A4/2C9); zafirlukast and zileuton require baseline and periodic LFT monitoring due to hepatotoxicity risk."}, {"label": "Elderly", "warn": false, "text": "No specific dose adjustment needed, but monitor for neuropsychiatric side effects which can be mistaken for or worsen underlying cognitive changes."}, {"label": "Pediatrics", "warn": true, "text": "Widely used and approved down to 6 months of age, but the neuropsychiatric warning is particularly relevant — sleep disturbance, nightmares, and behavioral changes are reported more often in children; counsel parents specifically on this before starting."}]}, {"key": "antihistamines", "topic": "resp", "name": "Antihistamines (1st- vs 2nd-Generation)", "pronunciation": "an-tee-HISS-tuh-meens", "blurb": "Mainstay symptomatic relief for allergic rhinitis, urticaria, and pruritus, with 2nd-generation agents now preferred over sedating 1st-generation agents for most indications.", "general": ["Mechanism: Inverse agonists at the H1 histamine receptor that stabilize the receptor in its inactive conformation, blocking histamine's effects on vascular permeability, sensory nerve stimulation (itch/sneeze), and smooth muscle — 1st-generation agents are small, lipophilic molecules that readily cross the blood-brain barrier and also block muscarinic, alpha-adrenergic, and serotonin receptors (causing sedation and anticholinergic effects), while 2nd-generation agents are larger, more polar, and are actively pumped out of the CNS by P-glycoprotein, making them far less sedating and more H1-selective.", "Class indications: Allergic rhinitis (seasonal/perennial), urticaria and pruritus, allergic conjunctivitis; 1st-generation agents are also used for insomnia (off-label, via sedation), motion sickness/nausea, and as adjuncts in anaphylaxis management (not first-line treatment).", "Class side effects: 1st-generation — sedation, psychomotor impairment (comparable to alcohol intoxication, often unrecognized by the patient), anticholinergic effects (dry mouth, blurred vision, urinary retention, constipation), and paradoxical excitation in children/elderly; 2nd-generation — minimal sedation at standard doses (though cetirizine is more sedating than the others in the class), headache, and rare QT prolongation with some older agents like terfenadine (withdrawn).", "Class contraindications: 1st-generation agents should be avoided in narrow-angle glaucoma, symptomatic BPH/urinary retention, and in the elderly generally (Beers Criteria — high anticholinergic burden, fall/delirium risk); 2nd-generation agents have essentially no absolute contraindications at standard doses.", "Class monitoring: Counsel on sedation and impaired driving/machinery operation with 1st-generation agents (and warn that tolerance to sedation is unreliable); for 2nd-generation agents, monitor efficacy at 1-2 weeks and consider switching agents within the class if one doesn't work (individual response varies)."], "memberCols": ["Generation", "Sedation level", "Notable"], "members": [{"name": "Diphenhydramine (Benadryl)", "a": "1st", "b": "High", "c": "Prototype 1st-gen; also used for insomnia, allergic reactions, and antitussive/antiemetic effects; strong anticholinergic burden"}, {"name": "Chlorpheniramine", "a": "1st", "b": "Moderate-high", "c": "Common in OTC cough/cold combination products"}, {"name": "Hydroxyzine", "a": "1st", "b": "High", "c": "Used for anxiety and pruritus (especially in dermatology) due to potent sedative/anxiolytic effect beyond H1 blockade"}, {"name": "Doxylamine", "a": "1st", "b": "High", "c": "Combined with pyridoxine (Diclectin) as first-line for nausea/vomiting of pregnancy in Canada"}, {"name": "Dimenhydrinate (Gravol)", "a": "1st", "b": "High", "c": "Diphenhydramine salt marketed specifically for motion sickness/nausea"}, {"name": "Cetirizine (Reactine)", "a": "2nd", "b": "Low-moderate", "c": "Most sedating of the 2nd-gen agents (~10-15% report drowsiness) — active metabolite of hydroxyzine"}, {"name": "Loratadine (Claritin)", "a": "2nd", "b": "Minimal", "c": "Prodrug converted to active desloratadine hepatically; non-sedating at standard dose"}, {"name": "Desloratadine (Aerius)", "a": "2nd", "b": "Minimal", "c": "Active metabolite of loratadine; marketed separately"}, {"name": "Fexofenadine (Allegra)", "a": "2nd", "b": "Minimal", "c": "Least CNS penetration of the class — considered the least sedating option; avoid taking with fruit juices which reduce absorption"}, {"name": "Bilastine", "a": "2nd", "b": "Minimal", "c": "Newer 2nd-gen agent; not a CYP substrate, low drug interaction potential"}, {"name": "Rupatadine", "a": "2nd", "b": "Minimal", "c": "Dual H1-antihistamine and PAF (platelet-activating factor) antagonist activity"}, {"name": "Azelastine (intranasal/ophthalmic)", "a": "2nd (topical)", "b": "Low (local route)", "c": "Topical antihistamine for allergic rhinitis/conjunctivitis; minimal systemic absorption but can still cause mild drowsiness and bitter taste"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Loratadine and cetirizine have the most reassuring safety data and are generally preferred; doxylamine/pyridoxine (Diclectin) is a first-line, well-studied option specifically for nausea/vomiting of pregnancy in Canada."}, {"label": "Breastfeeding", "warn": true, "text": "2nd-generation agents (loratadine, cetirizine) are preferred; 1st-generation agents can cause sedation/irritability in the infant and may reduce milk supply via anticholinergic effects, so should be minimized."}, {"label": "Renal impairment", "warn": true, "text": "Cetirizine and fexofenadine are renally eliminated and require dose reduction in significant renal impairment; loratadine/desloratadine are primarily hepatically metabolized."}, {"label": "Hepatic impairment", "warn": true, "text": "Loratadine and desloratadine require dose reduction (e.g., every-other-day dosing) in significant hepatic impairment since they depend on hepatic conversion/clearance."}, {"label": "Elderly", "warn": true, "text": "1st-generation agents are on the Beers Criteria list to avoid in older adults due to anticholinergic burden, fall risk, confusion, and urinary retention; 2nd-generation agents are preferred, with cetirizine's mild sedation still worth noting."}, {"label": "Pediatrics", "warn": true, "text": "1st-generation agents can cause paradoxical hyperactivity/excitation in young children rather than sedation, and are not recommended for sleep or routine allergy use; 2nd-generation agents have pediatric-specific dosing and formulations (syrups, chewables) down to 6 months to 2 years depending on the agent."}]}, {"key": "smoking-cessation", "topic": "resp", "name": "Smoking Cessation Agents", "pronunciation": "SMOH-king seh-SAY-shun AY-jents", "blurb": "Pharmacologic aids (NRT, varenicline, bupropion) that roughly double or triple long-term quit rates compared with willpower alone, and are recommended for every patient ready to quit.", "general": ["Mechanism: Nicotine replacement therapy (NRT) delivers nicotine without the combustion toxins of cigarettes, blunting withdrawal and craving by maintaining partial nicotinic receptor occupancy; varenicline is a partial agonist at the alpha4-beta2 nicotinic acetylcholine receptor — it stimulates enough dopamine release to ease withdrawal while blocking nicotine from fully activating the receptor if the patient smokes (reducing the reward/relapse cycle); bupropion is an NDRI (norepinephrine-dopamine reuptake inhibitor) that reduces craving and withdrawal symptoms through a non-nicotinic dopaminergic mechanism, independent of its antidepressant use.", "Class indications: Adjunct to behavioral counseling for nicotine dependence/smoking cessation in adults motivated to quit; combination NRT (patch + fast-acting form) or varenicline are generally more effective than any single NRT product alone; bupropion is an alternative, particularly useful when depression or weight-gain concerns coexist.", "Class side effects: NRT — local irritation (patch site, gum/lozenge mouth/throat irritation, nasal spray irritation), insomnia/vivid dreams (from nocturnal nicotine absorption via patch), palpitations; varenicline — nausea (most common, reduced by taking with food), vivid/abnormal dreams, and a historical (since downgraded) boxed warning for neuropsychiatric events; bupropion — insomnia, dry mouth, and a dose-dependent seizure risk.", "Class contraindications: Bupropion is contraindicated in seizure disorders, eating disorders (anorexia/bulimia), and with concurrent MAOI use (within 14 days) due to seizure and hypertensive crisis risk; NRT should be used cautiously post-MI/unstable angina (within 2 weeks) or with serious arrhythmias, though this is a relative rather than absolute contraindication given the greater harm of continued smoking; varenicline requires renal dose adjustment but has no absolute contraindications.", "Class monitoring: Set a quit date and reassess craving/withdrawal control and side effects within 1-2 weeks of starting; monitor mood and behavior changes with varenicline and bupropion (both carry cautions, though the varenicline boxed warning was removed after EAGLES trial data); counsel that combination NRT (patch plus PRN gum/lozenge) outperforms monotherapy."], "memberCols": ["Class/Type", "Duration of use", "Notable"], "members": [{"name": "Nicotine patch (transdermal)", "a": "NRT — long-acting", "b": "8-12 weeks, tapering doses", "c": "Provides steady baseline nicotine level; apply to hairless skin, rotate sites; remove at bedtime if vivid dreams/insomnia occur"}, {"name": "Nicotine gum", "a": "NRT — fast-acting", "b": "Up to 12 weeks, PRN", "c": "Chew-and-park technique required for buccal absorption; acidic beverages (coffee, juice) impair absorption if used within 15 min"}, {"name": "Nicotine lozenge", "a": "NRT — fast-acting", "b": "Up to 12 weeks, PRN", "c": "Alternative for patients with denture issues or who dislike chewing gum"}, {"name": "Nicotine inhaler", "a": "NRT — fast-acting", "b": "Up to 12 weeks, PRN", "c": "Mimics hand-to-mouth ritual of smoking, which some patients find behaviorally helpful"}, {"name": "Nicotine nasal spray", "a": "NRT — fast-acting", "b": "Up to 12 weeks, PRN", "c": "Fastest nicotine delivery of NRT products (closest to cigarette pharmacokinetics); most nasal/throat irritation of the NRT options"}, {"name": "Nicotine mouth spray", "a": "NRT — fast-acting", "b": "Up to 12 weeks, PRN", "c": "Newer fast-acting oral spray formulation, rapid buccal absorption"}, {"name": "Varenicline (Champix)", "a": "Partial nicotinic agonist", "b": "12 weeks (can extend to 24)", "c": "Most effective single agent for quit rates in head-to-head trials; start 1 week before quit date, titrate dose over first week"}, {"name": "Bupropion SR (Zyban)", "a": "NDRI antidepressant", "b": "7-12 weeks", "c": "Start 1-2 weeks before quit date; also useful in patients concerned about post-cessation weight gain"}, {"name": "Combination NRT (patch + gum/lozenge)", "a": "NRT — long + fast-acting", "b": "8-12 weeks", "c": "More effective than any single NRT product; patch provides baseline coverage, PRN form manages breakthrough cravings"}, {"name": "Varenicline + NRT (combination)", "a": "Partial agonist + NRT", "b": "12 weeks", "c": "Emerging evidence for combining, though not yet standard first-line; considered for highly dependent smokers who fail monotherapy"}, {"name": "Nortriptyline (off-label)", "a": "Tricyclic antidepressant", "b": "12 weeks", "c": "Second-line off-label alternative with evidence for smoking cessation, used when first-line agents fail or are contraindicated"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Behavioral counseling is first-line; NRT may be considered if counseling alone fails, weighing continued smoking's clear fetal harm against uncertain NRT risk; varenicline and bupropion are generally avoided due to limited safety data — clinician discussion of risk/benefit is essential."}, {"label": "Breastfeeding", "warn": true, "text": "NRT is preferred over continued smoking and is considered compatible, ideally dosed after breastfeeding/before the infant's longest sleep period to minimize infant exposure; data for varenicline and bupropion are limited, so NRT is generally favored."}, {"label": "Renal impairment", "warn": true, "text": "Varenicline is renally eliminated and requires dose reduction in moderate-severe renal impairment (and further reduction in dialysis patients); bupropion and NRT require no specific renal adjustment but bupropion metabolites can accumulate in severe impairment."}, {"label": "Hepatic impairment", "warn": true, "text": "Bupropion should be used with caution and at reduced dose/frequency in hepatic impairment due to risk of drug accumulation and lowered seizure threshold; NRT and varenicline require no specific hepatic adjustment."}, {"label": "Elderly", "warn": false, "text": "All agents can generally be used, but start at lower doses and monitor for cardiovascular symptoms with NRT and for confusion/dizziness with bupropion or varenicline given increased sensitivity in older adults."}, {"label": "Pediatrics", "warn": true, "text": "Not approved/routinely recommended for adolescents under 18 in Canada — evidence for efficacy and safety in this age group is limited, and behavioral counseling remains the primary approach for youth smoking/vaping cessation."}]}, {"key": "ssri", "topic": "cns", "name": "SSRIs (Selective Serotonin Reuptake Inhibitors)", "pronunciation": "ess-ess-ar-eyes (SELL-eck-tiv sair-oh-TOE-nin ree-UP-take in-HIB-ih-ters)", "blurb": "First-line pharmacotherapy for major depressive disorder and most anxiety disorders due to favourable safety profile relative to older antidepressants.", "general": ["Mechanism: Selectively block the serotonin transporter (SERT) on the presynaptic neuron, preventing reuptake of serotonin from the synaptic cleft. This raises synaptic serotonin acutely, but the antidepressant effect lags 2-6 weeks because it depends on downstream adaptive changes (receptor downregulation, neuroplasticity), not the acute reuptake block itself.", "Class indications: Major depressive disorder, generalized anxiety disorder, panic disorder, social anxiety disorder, OCD, PTSD, and premenstrual dysphoric disorder (some agents).", "Class side effects: Nausea/GI upset and headache early on (excess serotonin in the gut and CNS); sexual dysfunction (decreased libido, delayed orgasm) from serotonergic action on 5-HT2/5-HT3 pathways; increased bleeding risk (platelets rely on serotonin for aggregation, and SSRIs deplete platelet serotonin stores); hyponatremia/SIADH especially in elderly; and at high serotonin burden or with other serotonergic drugs, serotonin syndrome (agitation, hyperthermia, clonus, hyperreflexia).", "Class contraindications: Concurrent or recent (within 14 days) MAOI use (serotonin syndrome risk), known hypersensitivity; use caution with other serotonergic agents (triptans, tramadol, linezolid, St. John's Wort).", "Class monitoring: Suicidality/mood changes closely in the first 1-4 weeks and after dose changes (black box warning, especially under age 25); response and tolerability at 4-6 weeks before judging efficacy; sodium levels in elderly; bleeding signs if on concurrent antiplatelets/anticoagulants/NSAIDs."], "memberCols": ["Half-life", "Key CYP interactions", "Notable"], "members": [{"name": "Fluoxetine", "a": "Long (~1-4 days; active metabolite ~7-15 days)", "b": "Potent CYP2D6 inhibitor", "c": "Long half-life means minimal discontinuation syndrome; can be given as a self-taper; activating, best given in the morning"}, {"name": "Sertraline", "a": "~26 hours", "b": "Mild CYP2D6 inhibition", "c": "Most favourable GI tolerability data among SSRIs; preferred in cardiac patients (SADHART trial, post-MI depression) and often first-line in pregnancy/lactation"}, {"name": "Paroxetine", "a": "~21 hours", "b": "Most potent CYP2D6 inhibitor of the class", "c": "Most anticholinergic and sedating SSRI; highest discontinuation syndrome risk (short half-life, no active metabolite); avoid in pregnancy (cardiac malformation signal) and in the elderly (anticholinergic burden)"}, {"name": "Citalopram", "a": "~35 hours", "b": "Minimal CYP interactions", "c": "Dose-dependent QT prolongation — Health Canada caps dose at 40 mg/day (20 mg/day if >65 years or hepatic impairment)"}, {"name": "Escitalopram", "a": "~27-32 hours", "b": "Minimal CYP interactions", "c": "Active enantiomer of citalopram; generally better tolerated at equivalent efficacy; still carries some QT signal at high doses"}, {"name": "Fluvoxamine", "a": "~15 hours", "b": "Potent CYP1A2 and CYP3A4 inhibitor", "c": "Mainly used for OCD in Canada; significant interaction potential (e.g., clozapine, theophylline, caffeine)"}, {"name": "Vortioxetine", "a": "~66 hours", "b": "CYP2D6 substrate", "c": "Multimodal (also 5-HT receptor modulation); marketed with pro-cognitive claims; nausea is prominent early side effect"}, {"name": "Vilazodone", "a": "~25 hours", "b": "CYP3A4 substrate", "c": "Partial 5-HT1A agonist plus reuptake inhibition; must be taken with food for adequate absorption; limited Canadian use"}, {"name": "Fluoxetine (pediatric use)", "a": "See above", "b": "See above", "c": "One of the few antidepressants with strong pediatric MDD evidence — often preferred agent in youth"}, {"name": "Sertraline (panic disorder)", "a": "See above", "b": "See above", "c": "Start at lower dose (25 mg) in panic disorder to minimize early activation/jitteriness"}, {"name": "Escitalopram (GAD)", "a": "See above", "b": "See above", "c": "Strong first-line evidence base in GAD with good tolerability"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not absolutely contraindicated — untreated depression carries its own risks. Sertraline is often preferred (most reassurance data); paroxetine is best avoided due to a signal for fetal cardiac malformations. Late third-trimester exposure can cause transient neonatal adaptation syndrome (jitteriness, feeding issues)."}, {"label": "Breastfeeding", "warn": false, "text": "Generally compatible; sertraline and paroxetine have the lowest relative infant dose and are preferred. Monitor infant for sedation, poor feeding, or irritability."}, {"label": "Renal impairment", "warn": false, "text": "No dose adjustment generally required as most SSRIs are hepatically metabolized, though start low and titrate slowly in severe impairment."}, {"label": "Hepatic impairment", "warn": true, "text": "Reduce dose and/or use lower maximum doses (e.g., citalopram max 20 mg/day in hepatic impairment); clearance is reduced across the class."}, {"label": "Elderly", "warn": true, "text": "Increased risk of hyponatremia, falls, and GI bleeding; paroxetine's anticholinergic burden makes it a poor choice; use lower starting doses and titrate slowly (\"start low, go slow\")."}, {"label": "Pediatrics", "warn": true, "text": "Black box warning for increased suicidal ideation risk in children/adolescents/young adults up to 24 years — requires close monitoring, especially in first weeks and after dose changes. Fluoxetine and sertraline (OCD) have the best pediatric evidence."}]}, {"key": "snri", "topic": "cns", "name": "SNRIs (Serotonin-Norepinephrine Reuptake Inhibitors)", "pronunciation": "ess-en-ar-eyes (sair-oh-TOE-nin nor-ep-ih-NEF-rin ree-UP-take in-HIB-ih-ters)", "blurb": "Dual reuptake inhibitors used for depression, anxiety disorders, and neuropathic/chronic pain conditions where norepinephrine's analgesic effect adds benefit.", "general": ["Mechanism: Block reuptake of both serotonin and norepinephrine at presynaptic transporters (SERT and NET), increasing synaptic concentrations of both. Norepinephrine reuptake blockade contributes additional benefit for chronic pain/neuropathic pain (descending inhibitory pain pathways) and can improve energy/concentration, but also drives the class's noradrenergic side effects.", "Class indications: Major depressive disorder, generalized anxiety disorder (venlafaxine, duloxetine), diabetic peripheral neuropathy and fibromyalgia (duloxetine), chronic musculoskeletal pain, and stress urinary incontinence (duloxetine, off-label/used in some jurisdictions).", "Class side effects: Nausea (serotonergic, most common early complaint); dose-dependent increases in blood pressure and heart rate (noradrenergic — most notable with venlafaxine at higher doses); sweating; sexual dysfunction; and, like SSRIs, serotonin syndrome risk when combined with other serotonergic agents.", "Class contraindications: Concurrent/recent MAOI use (serotonin syndrome), uncontrolled narrow-angle glaucoma; use caution in uncontrolled hypertension given the class's pressor effect.", "Class monitoring: Blood pressure at baseline and periodically, especially with venlafaxine dose increases; suicidality/mood in first weeks (same black box warning as SSRIs); renal/hepatic function as relevant to specific agent dosing; response at 4-6 weeks."], "memberCols": ["Relative NE:5-HT potency", "Renal/hepatic dosing note", "Notable"], "members": [{"name": "Venlafaxine", "a": "Serotonergic at low dose; noradrenergic effect emerges >150 mg/day", "b": "Reduce dose in renal impairment (CrCl <30: reduce by 50%)", "c": "Most significant dose-dependent BP elevation of the class; short half-life gives prominent discontinuation syndrome (\"brain zaps\"); available as XR for once-daily dosing"}, {"name": "Desvenlafaxine", "a": "Similar to venlafaxine, active metabolite", "b": "Renal dose adjustment needed", "c": "Active metabolite of venlafaxine; fewer CYP interactions since it bypasses CYP2D6 metabolism step"}, {"name": "Duloxetine", "a": "Balanced 5-HT and NE inhibition", "b": "Avoid in significant hepatic impairment or CrCl <30 (hepatotoxicity risk, active metabolites accumulate)", "c": "Strong evidence for neuropathic pain (diabetic neuropathy) and fibromyalgia in addition to MDD/GAD; can cause hepatotoxicity — avoid with chronic liver disease or heavy alcohol use"}, {"name": "Levomilnacipran", "a": "More noradrenergic-predominant than other SNRIs", "b": "Renal dose adjustment required", "c": "Limited Canadian availability/use; more NE-selective, so more noradrenergic side effects (urinary hesitancy, elevated HR)"}, {"name": "Milnacipran", "a": "NE:5-HT ratio favours norepinephrine (~3:1)", "b": "Renal dose adjustment required", "c": "Approved primarily for fibromyalgia (not MDD) in some markets; prominent noradrenergic side effects"}, {"name": "Venlafaxine XR (high dose)", "a": "Predominantly noradrenergic effect", "b": "Same as above", "c": "At doses >225 mg/day, triple mechanism debated (some dopaminergic contribution proposed); highest BP risk point in the class"}, {"name": "Duloxetine (fibromyalgia)", "a": "Balanced", "b": "Same as above", "c": "One of only a few agents with a Health Canada indication specifically for fibromyalgia-associated pain"}, {"name": "Desvenlafaxine (menopausal symptoms)", "a": "Balanced/serotonergic-leaning", "b": "Same as above", "c": "Some evidence for vasomotor symptom reduction in menopause (used off-label)"}, {"name": "Venlafaxine (panic disorder)", "a": "Serotonergic at typical starting doses", "b": "Same as above", "c": "XR formulation has specific approval for panic disorder; start low (37.5 mg) to reduce early jitteriness"}, {"name": "Duloxetine (GAD)", "a": "Balanced", "b": "Same as above", "c": "First-line option in GAD per Canadian guidelines, comparable efficacy to SSRIs with added benefit if comorbid chronic pain"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not first-line in pregnancy given more limited safety data compared to SSRIs and the class's blood-pressure effects; continue if a patient is already stable on one and switching risks relapse. Watch for neonatal adaptation syndrome with late third-trimester exposure."}, {"label": "Breastfeeding", "warn": false, "text": "Considered generally compatible with breastfeeding; venlafaxine and its metabolite do pass into breast milk in measurable amounts — monitor infant for irritability or poor feeding."}, {"label": "Renal impairment", "warn": true, "text": "Venlafaxine, desvenlafaxine, milnacipran, and levomilnacipran all require dose reduction as renal clearance decreases; duloxetine should be avoided if CrCl <30 mL/min."}, {"label": "Hepatic impairment", "warn": true, "text": "Duloxetine should be avoided in any hepatic impairment or significant alcohol use due to reports of hepatotoxicity; venlafaxine requires dose reduction in hepatic impairment."}, {"label": "Elderly", "warn": true, "text": "Increased sensitivity to blood pressure effects and hyponatremia; start at lower doses and monitor BP with titration, particularly with venlafaxine."}, {"label": "Pediatrics", "warn": true, "text": "Same black-box suicidality warning as SSRIs applies to the class up to age 24; evidence for efficacy in pediatric depression is weaker than for SSRIs, so SNRIs are not typically first-line in this population."}]}, {"key": "tca", "topic": "cns", "name": "TCAs (Tricyclic Antidepressants)", "pronunciation": "tee-see-ays (try-SY-klik an-tee-dee-PRESS-ants)", "blurb": "Older antidepressant class effective for depression and chronic pain/neuropathic pain, limited clinically by anticholinergic, antihistaminic, and cardiotoxic (quinidine-like) side effects.", "general": ["Mechanism: Inhibit reuptake of both serotonin and norepinephrine (similar to SNRIs) but also block muscarinic (M1), histamine (H1), and alpha-1 adrenergic receptors non-selectively — this 'dirty' receptor profile is why TCAs cause far more side effects than newer antidepressants. At high doses/overdose, they also block cardiac fast sodium channels, producing quinidine-like cardiotoxicity.", "Class indications: Major depressive disorder (now typically 2nd/3rd-line), neuropathic pain, chronic tension/migraine headache prophylaxis, and nocturnal enuresis in children (imipramine).", "Class side effects: Anticholinergic effects (dry mouth, blurred vision, urinary retention, constipation, confusion in elderly) from M1 blockade; sedation and weight gain from H1 blockade; orthostatic hypotension from alpha-1 blockade; and cardiac conduction delays (QRS/QT prolongation, arrhythmia risk) from sodium channel blockade — the latter is lethal in overdose.", "Class contraindications: Recent MI or unstable cardiac disease (conduction risk), concurrent MAOI use, narrow-angle glaucoma, severe urinary retention/BPH; caution in seizure disorders (TCAs lower seizure threshold).", "Class monitoring: Baseline ECG (especially age >40 or cardiac history) and periodically with dose increases to assess QRS/QTc; therapeutic drug levels for agents with established ranges (e.g., nortriptyline); anticholinergic burden/cognition in elderly; suicide risk — TCAs are highly lethal in overdose, so limit quantities dispensed to at-risk patients."], "memberCols": ["Anticholinergic burden", "Sedation", "Notable"], "members": [{"name": "Amitriptyline", "a": "High", "b": "High", "c": "Most anticholinergic/sedating TCA; widely used off-label for neuropathic pain and migraine prophylaxis at low doses"}, {"name": "Nortriptyline", "a": "Moderate", "b": "Moderate", "c": "Active metabolite of amitriptyline; best-tolerated TCA, has an established therapeutic plasma level range, preferred TCA in elderly/pain populations"}, {"name": "Imipramine", "a": "Moderate-high", "b": "Moderate", "c": "First TCA developed; still used for nocturnal enuresis in children due to anticholinergic effect on bladder"}, {"name": "Desipramine", "a": "Low(est) of the class", "b": "Low", "c": "Active metabolite of imipramine; most noradrenergic-selective TCA, least sedating — but still carries full cardiotoxicity risk in overdose"}, {"name": "Clomipramine", "a": "High", "b": "High", "c": "Most serotonin-selective TCA; specifically indicated for OCD; higher seizure risk than other TCAs"}, {"name": "Doxepin", "a": "High", "b": "Very high", "c": "Low-dose formulation (3-6 mg) approved specifically for insomnia via potent H1 antagonism; higher doses used for depression"}, {"name": "Trimipramine", "a": "High", "b": "High", "c": "Notably sedating; sometimes used for insomnia associated with depression"}, {"name": "Protriptyline", "a": "Moderate", "b": "Low (activating, not sedating)", "c": "Uncommon choice; one of the few TCAs that is alerting rather than sedating, so dosed in morning"}, {"name": "Amitriptyline (low-dose pain)", "a": "Same as above but dose-dependent", "b": "Same", "c": "10-25 mg at bedtime is standard starting dose for neuropathic pain, well below antidepressant doses"}, {"name": "Nortriptyline (elderly depression)", "a": "Moderate", "b": "Moderate", "c": "Preferred TCA when a TCA must be used in older adults, given comparatively lower anticholinergic/hypotensive burden"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not first-line; some TCAs (nortriptyline) have longer safety track records than newer agents if a TCA is specifically needed, but neonatal withdrawal/anticholinergic effects can occur with third-trimester exposure."}, {"label": "Breastfeeding", "warn": false, "text": "Nortriptyline is generally considered compatible with low relative infant dose; monitor infant for sedation."}, {"label": "Renal impairment", "warn": false, "text": "No major dose adjustment typically required as TCAs are primarily hepatically metabolized, but use caution with accumulation of active metabolites in severe impairment."}, {"label": "Hepatic impairment", "warn": true, "text": "Reduce dose and monitor closely — TCAs undergo extensive hepatic first-pass metabolism and levels can rise substantially with impaired clearance."}, {"label": "Elderly", "warn": true, "text": "High risk of falls, confusion, urinary retention, and orthostatic hypotension from anticholinergic/alpha-1 effects; TCAs (especially amitriptyline) are on the Beers List as potentially inappropriate; nortriptyline is the least problematic if a TCA is unavoidable."}, {"label": "Pediatrics", "warn": true, "text": "Cardiotoxicity in overdose is a major safety concern in a population with access to the same bottle as a parent's prescription; imipramine is used specifically for enuresis but requires ECG monitoring and careful dose limits given the narrow therapeutic index."}]}, {"key": "atypical-antipsychotics", "topic": "cns", "name": "Atypical Antipsychotics", "pronunciation": "ay-TIP-ih-kul an-ty-sy-KOT-iks", "blurb": "Second-generation antipsychotics used for schizophrenia, bipolar disorder, and adjunctive depression treatment, favoured over first-generation agents for their lower risk of extrapyramidal symptoms but higher metabolic risk.", "general": ["Mechanism: Antagonize dopamine D2 receptors (reducing positive psychotic symptoms) combined with significant serotonin 5-HT2A antagonism, which is thought to reduce extrapyramidal side effects (EPS) relative to first-generation antipsychotics by modulating dopamine release in the nigrostriatal pathway. Individual agents also vary widely in their affinity for histamine (H1), muscarinic (M1), and alpha-1 receptors, which drives their differing side-effect profiles.", "Class indications: Schizophrenia and other psychotic disorders, bipolar disorder (mania and/or depression), treatment-resistant depression (adjunctive, e.g., aripiprazole, quetiapine), and severe agitation.", "Class side effects: Metabolic syndrome (weight gain, dyslipidemia, new-onset diabetes) most pronounced with olanzapine and clozapine due to H1/5-HT2C antagonism; sedation from H1 blockade; orthostatic hypotension from alpha-1 blockade; hyperprolactinemia most notable with risperidone/paliperidone (less 5-HT2A/D2 dissociation in the tuberoinfundibular pathway); QT prolongation (notably ziprasidone); and, less than first-generation agents, EPS/tardive dyskinesia with high-dose or high-potency agents (risperidone).", "Class contraindications: Dementia-related psychosis in elderly patients carries a black box warning for increased mortality (cerebrovascular events, sudden cardiac death) across the entire class; caution with other QT-prolonging drugs; clozapine specifically contraindicated with severe neutropenia history or myocarditis.", "Class monitoring: Baseline and periodic metabolic panel (weight/BMI, fasting glucose/HbA1c, lipids) per Canadian metabolic monitoring guidelines; baseline ECG for QT-prolonging agents; prolactin if symptomatic (galactorrhea, sexual dysfunction, amenorrhea); ANC weekly-to-monthly for clozapine (agranulocytosis risk); and ongoing assessment for EPS/tardive dyskinesia (e.g., AIMS scale)."], "memberCols": ["Metabolic risk", "Sedation/EPS profile", "Notable"], "members": [{"name": "Olanzapine", "a": "Very high", "b": "Sedating, low EPS", "c": "Among the highest weight gain/metabolic risk; available as an IM and orally-disintegrating (ODT) form; effective but metabolically costly"}, {"name": "Risperidone", "a": "Moderate", "b": "Low-moderate sedation, dose-dependent EPS (loses D2 selectivity at higher doses)", "c": "Highest prolactin elevation risk of the class; available as long-acting injectable (Consta, Perseris) and has a paliperidone active metabolite"}, {"name": "Quetiapine", "a": "Moderate-high", "b": "Highly sedating at low doses (antihistaminic), lowest EPS of the class", "c": "Used off-label at low doses for insomnia/anxiety; XR formulation approved as adjunct for MDD; significant orthostatic hypotension on initiation"}, {"name": "Aripiprazole", "a": "Low", "b": "Activating rather than sedating; can cause akathisia", "c": "Partial D2/5-HT1A agonist rather than pure antagonist (\"dopamine stabilizer\"); lowest metabolic burden and minimal prolactin elevation; available as long-acting injectable"}, {"name": "Clozapine", "a": "Very high", "b": "Very sedating, essentially no EPS", "c": "Reserved for treatment-resistant schizophrenia given agranulocytosis risk requiring mandatory ANC monitoring registry; also carries risk of myocarditis and seizures (dose-dependent)"}, {"name": "Ziprasidone", "a": "Low (weight-neutral)", "b": "Moderate sedation", "c": "Most significant QT prolongation risk in the class; must be taken with food (≥500 kcal) for adequate absorption; limited Canadian availability"}, {"name": "Lurasidone", "a": "Low", "b": "Low sedation, some akathisia", "c": "Must be taken with food (≥350 kcal); favourable metabolic profile makes it attractive for long-term use; approved for bipolar depression"}, {"name": "Paliperidone", "a": "Moderate", "b": "Similar to risperidone (its parent compound)", "c": "Active metabolite of risperidone; renally eliminated (unlike most of the class); available as monthly and 3-monthly long-acting injectables"}, {"name": "Asenapine", "a": "Moderate", "b": "Sedating, some EPS", "c": "Sublingual formulation only — must not eat/drink for 10 minutes after dosing; used for schizophrenia and bipolar mania"}, {"name": "Brexpiprazole", "a": "Low-moderate", "b": "Less akathisia than aripiprazole", "c": "Newer partial D2/5-HT1A agonist; approved as adjunct for MDD and for schizophrenia; similar mechanism to aripiprazole with a smoother tolerability profile"}, {"name": "Cariprazine", "a": "Low", "b": "Activating, dose-dependent akathisia/EPS", "c": "Preferential D3 over D2 partial agonism; long half-life (active metabolite persists ~1-3 weeks); approved for bipolar depression and mania"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not absolutely contraindicated — untreated psychosis/mania carries significant maternal/fetal risk. Quetiapine and olanzapine have the most reassuring data; monitor for gestational diabetes given metabolic effects, and watch for neonatal EPS/withdrawal with late exposure."}, {"label": "Breastfeeding", "warn": false, "text": "Generally compatible; quetiapine and olanzapine have more accumulated safety data than newer agents. Monitor infant for sedation."}, {"label": "Renal impairment", "warn": true, "text": "Paliperidone requires dose reduction as it is primarily renally eliminated (unlike most agents in this class, which are hepatically metabolized); most others need little adjustment but caution is warranted."}, {"label": "Hepatic impairment", "warn": true, "text": "Most agents require dose reduction as they undergo extensive hepatic metabolism (CYP3A4/CYP2D6 substrates); use lower starting doses and titrate slowly."}, {"label": "Elderly", "warn": true, "text": "Black box warning for increased mortality (stroke, cardiac events) when used for dementia-related behavioural symptoms/psychosis — use only when non-pharmacologic options fail and at the lowest effective dose for the shortest duration."}, {"label": "Pediatrics", "warn": true, "text": "Approved for specific pediatric indications (e.g., aripiprazole/risperidone for irritability in autism, bipolar mania) but children are more susceptible to metabolic side effects and EPS — monitor growth, weight, and metabolic parameters closely."}]}, {"key": "typical-antipsychotics", "topic": "cns", "name": "Typical (First-Generation) Antipsychotics", "pronunciation": "TIP-ih-kul an-tie-sy-koh-TIH-ticks", "blurb": "Older D2-blocking antipsychotics that control positive psychotic symptoms but carry a high burden of extrapyramidal and anticholinergic effects.", "general": ["Mechanism: Block D2 dopamine receptors throughout the brain, most usefully in the mesolimbic pathway to reduce positive symptoms (hallucinations, delusions), but the same blockade in the nigrostriatal pathway causes movement disorders and in the tuberoinfundibular pathway raises prolactin. Many members also block muscarinic, histaminic, and alpha-1 receptors, adding anticholinergic, sedative, and hypotensive effects.", "Class indications: Schizophrenia and other psychotic disorders, acute agitation, Tourette syndrome (tics), intractable hiccups; some (e.g., prochlorperazine) are used for nausea/vomiting via central D2 blockade.", "Class side effects: Extrapyramidal symptoms (acute dystonia, akathisia, parkinsonism, tardive dyskinesia) from nigrostriatal D2 blockade; hyperprolactinemia (galactorrhea, amenorrhea, sexual dysfunction) from tuberoinfundibular blockade; anticholinergic effects (dry mouth, constipation, blurred vision, urinary retention); sedation and orthostatic hypotension from H1/alpha-1 blockade; QT prolongation, especially with haloperidol IV.", "Class contraindications: Severe CNS depression or coma, Parkinson disease (worsens motor symptoms), known neuroleptic malignant syndrome, QT prolongation/high-risk arrhythmia (particularly with high-dose IV haloperidol).", "Class monitoring: Baseline and periodic AIMS (Abnormal Involuntary Movement Scale) for tardive dyskinesia, ECG/QTc for high-risk agents, prolactin if symptomatic, weight/metabolic parameters (lower risk than atypicals but still relevant), and mental status/symptom response."], "memberCols": ["Potency", "EPS risk", "Notable"], "members": [{"name": "Haloperidol", "a": "High-potency", "b": "High", "c": "Prototype high-potency agent; IV form used for severe agitation/delirium but carries QT prolongation risk; depot (decanoate) available for adherence"}, {"name": "Fluphenazine", "a": "High-potency", "b": "High", "c": "Available as long-acting decanoate depot injection every 2-4 weeks for adherence support"}, {"name": "Perphenazine", "a": "Mid-potency", "b": "Moderate", "c": "Used in CATIE trial as the first-generation comparator; moderate sedation and anticholinergic burden"}, {"name": "Loxapine", "a": "Mid-potency", "b": "Moderate", "c": "Has some serotonergic activity; inhaled form (Adasuve) available for rapid agitation control but requires bronchospasm monitoring"}, {"name": "Trifluoperazine", "a": "High-potency", "b": "High", "c": "Similar profile to fluphenazine; less commonly used now"}, {"name": "Chlorpromazine", "a": "Low-potency", "b": "Low", "c": "First antipsychotic ever developed; prominent sedation, hypotension, and photosensitivity; used for intractable hiccups"}, {"name": "Thioridazine", "a": "Low-potency", "b": "Low", "c": "Significant QT prolongation risk and retinal pigmentation at high doses; reserved for treatment-resistant cases due to safety profile"}, {"name": "Pericyazine", "a": "Low-potency", "b": "Low", "c": "Used in Canada for severe agitation/aggression; strong sedative and anticholinergic effects"}, {"name": "Pimozide", "a": "High-potency", "b": "High", "c": "Notable QT prolongation risk; used specifically for Tourette syndrome and delusional disorder"}, {"name": "Prochlorperazine", "a": "Mid-potency", "b": "Moderate", "c": "Primarily used as an antiemetic/antivertigo agent at lower doses rather than for psychosis"}, {"name": "Methotrimeprazine", "a": "Low-potency", "b": "Low", "c": "Used in palliative care for pain, nausea, and agitation due to strong sedative and analgesic-adjunct properties"}, {"name": "Zuclopenthixol", "a": "Mid-potency", "b": "Moderate", "c": "Available as short-acting (acuphase) and long-acting depot forms for rapid tranquilization and maintenance"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not first-line; high-potency agents (e.g., haloperidol) have more safety data than low-potency ones if an antipsychotic is needed, but risk of neonatal EPS/withdrawal near term. Weigh against risk of untreated psychosis."}, {"label": "Breastfeeding", "warn": true, "text": "Most typical antipsychotics pass into breast milk in small amounts; monitor infant for sedation and feeding difficulties. Low-potency, more sedating agents warrant extra caution."}, {"label": "Renal impairment", "warn": false, "text": "Mostly hepatically metabolized; dose adjustment generally not required, but start low in significant renal impairment due to reduced clearance of active metabolites for some agents."}, {"label": "Hepatic impairment", "warn": true, "text": "Extensively hepatically metabolized — reduce dose and titrate slowly in hepatic impairment; chlorpromazine has been associated with cholestatic jaundice."}, {"label": "Elderly", "warn": true, "text": "Increased sensitivity to EPS, sedation, orthostatic hypotension, and anticholinergic cognitive effects; carries a boxed warning for increased mortality in elderly patients with dementia-related psychosis — avoid when possible."}, {"label": "Pediatrics", "warn": true, "text": "Used cautiously for specific indications (e.g., pimozide for Tourette syndrome); children are more susceptible to EPS and require lower weight-based doses with close monitoring."}]}, {"key": "benzodiazepines", "topic": "cns", "name": "Benzodiazepines", "pronunciation": "ben-zoh-dy-AZ-eh-peens", "blurb": "GABA-A receptor potentiators used for anxiety, insomnia, seizures, and acute alcohol withdrawal, with dependence and CNS depression as their major risks.", "general": ["Mechanism: Bind to a modulatory site on the GABA-A receptor distinct from GABA itself, increasing the frequency of chloride channel opening in the presence of GABA. This enhances inhibitory neurotransmission throughout the CNS, producing anxiolysis, sedation, muscle relaxation, and anticonvulsant effects in a dose-dependent continuum.", "Class indications: Generalized anxiety disorder and acute anxiety/panic attacks, insomnia (short-term), seizure disorders and status epilepticus, acute alcohol withdrawal, procedural sedation, muscle spasm, and pre-operative anxiolysis.", "Class side effects: Sedation, drowsiness, and psychomotor/cognitive impairment (dose-related CNS depression); anterograde amnesia; ataxia and fall risk, especially in elderly; paradoxical disinhibition/agitation (more common in children and elderly); respiratory depression, markedly amplified when combined with opioids or alcohol.", "Class contraindications: Severe respiratory insufficiency, untreated sleep apnea, myasthenia gravis, severe hepatic impairment (risk of encephalopathy), concurrent opioid use without careful risk assessment (boxed warning for combined respiratory depression), known hypersensitivity.", "Class monitoring: Level of sedation/respiratory status (especially with parenteral use or opioid co-administration), signs of tolerance/dependence with long-term use, cognitive and fall-risk assessment in the elderly, and withdrawal symptoms if discontinuing after prolonged use (taper required)."], "memberCols": ["Half-life", "Active metabolites?", "Notable"], "members": [{"name": "Diazepam", "a": "Long (20-100h)", "b": "Yes", "c": "Long-acting with active metabolites — self-tapers; used for alcohol withdrawal and status epilepticus (rectal gel available)"}, {"name": "Lorazepam", "a": "Intermediate (10-20h)", "b": "No", "c": "No active metabolites and not hepatically oxidized (glucuronidation only) — preferred in hepatic impairment and the elderly; first-line for status epilepticus"}, {"name": "Clonazepam", "a": "Long (18-50h)", "b": "No", "c": "Used for panic disorder and certain seizure types (absence, myoclonic); potent with long duration of action"}, {"name": "Alprazolam", "a": "Short (6-12h)", "b": "Minor", "c": "Rapid onset makes it effective for panic attacks but also gives it higher abuse potential and more pronounced interdose withdrawal"}, {"name": "Oxazepam", "a": "Short (5-15h)", "b": "No", "c": "Like lorazepam, undergoes only glucuronidation — safer in hepatic impairment and older adults; slower onset limits abuse potential"}, {"name": "Temazepam", "a": "Intermediate (8-15h)", "b": "No", "c": "Used specifically for sleep-onset and maintenance insomnia; minimal active metabolites reduce next-day residual sedation"}, {"name": "Chlordiazepoxide", "a": "Long (5-30h, metabolites longer)", "b": "Yes", "c": "Classic agent for symptom-triggered alcohol withdrawal protocols (e.g., CIWA-Ar)"}, {"name": "Midazolam", "a": "Very short (1.5-3h)", "b": "Minor", "c": "Water-soluble at low pH, used IV/IM for procedural sedation and status epilepticus (including intranasal/buccal for seizure rescue)"}, {"name": "Clobazam", "a": "Long (10-30h)", "b": "Yes (active)", "c": "1,5-benzodiazepine (different ring structure) with lower sedation burden relative to potency; adjunct for Lennox-Gastaut syndrome"}, {"name": "Bromazepam", "a": "Intermediate (10-20h)", "b": "No", "c": "Commonly used in Canada/Europe for generalized anxiety; intermediate onset and duration"}, {"name": "Flurazepam", "a": "Very long (metabolite 47-100h)", "b": "Yes", "c": "Older hypnotic with long-acting active metabolite causing significant next-day sedation — largely replaced by shorter agents"}, {"name": "Triazolam", "a": "Very short (2-6h)", "b": "No", "c": "Fast onset/short duration ideal for sleep-onset insomnia, but higher risk of rebound insomnia and anterograde amnesia"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Associated with possible risk of oral cleft with first-trimester use and floppy infant syndrome/neonatal withdrawal with use near term; avoid unless benefits clearly outweigh risks."}, {"label": "Breastfeeding", "warn": true, "text": "Enter breast milk and can cause infant sedation and poor feeding; if needed, prefer shorter-acting agents at the lowest effective dose and monitor the infant."}, {"label": "Renal impairment", "warn": false, "text": "Most are hepatically metabolized with minimal renal elimination of parent drug; generally no major dose adjustment needed, though accumulation of metabolites can occur in severe renal failure."}, {"label": "Hepatic impairment", "warn": true, "text": "Hepatically oxidized agents (diazepam, chlordiazepoxide) accumulate and risk precipitating encephalopathy — prefer lorazepam, oxazepam, or temazepam, which undergo glucuronidation only."}, {"label": "Elderly", "warn": true, "text": "Increased sensitivity to sedation, ataxia, falls, and cognitive impairment; on the Beers Criteria as potentially inappropriate — avoid long-acting agents and use the lowest dose for the shortest duration if used at all."}, {"label": "Pediatrics", "warn": true, "text": "Used for specific indications (seizures, procedural sedation) but children may show paradoxical excitation/disinhibition rather than sedation; dose carefully by weight."}]}, {"key": "anticonvulsants", "topic": "cns", "name": "Anticonvulsants (Antiepileptics)", "pronunciation": "an-tie-kon-VUL-sants (an-tie-EP-ih-lep-ticks)", "blurb": "A mechanistically diverse group of drugs that raise seizure threshold by dampening neuronal excitability, chosen by seizure type, side-effect profile, and interaction potential.", "general": ["Mechanism: No single shared mechanism — agents work by blocking voltage-gated sodium channels (stabilizing the inactivated state to prevent rapid neuronal firing), enhancing GABAergic inhibition, blocking voltage-gated calcium channels (particularly T-type in absence seizures), or modulating synaptic vesicle release (SV2A) or glutamate release. Choice of agent depends on matching mechanism to seizure type.", "Class indications: Focal and generalized seizure disorders, status epilepticus (specific agents), neuropathic pain and migraine prophylaxis (some agents), bipolar disorder/mood stabilization (valproate, carbamazepine, lamotrigine), and essential tremor or fibromyalgia for select agents.", "Class side effects: CNS effects common to most (sedation, dizziness, ataxia, diplopia); sodium-channel blockers cause diplopia/ataxia at high levels and carry rare but serious hypersensitivity syndromes (SJS/TEN, especially carbamazepine and lamotrigine, linked to HLA-B*1502 in some populations); valproate causes weight gain, tremor, hepatotoxicity, and pancreatitis; many are potent hepatic enzyme inducers or inhibitors causing significant drug interactions.", "Class contraindications: Hepatic impairment/porphyria (valproate, carbamazepine), known HLA-B*1502 or HLA-A*3101 risk alleles without genetic testing (carbamazepine in at-risk populations), pregnancy for high-teratogenicity agents (valproate especially), bone marrow suppression history (carbamazepine).", "Class monitoring: Seizure frequency/control, drug-specific therapeutic drug monitoring (TDM) where levels correlate with efficacy/toxicity, CBC and LFTs for agents with hematologic/hepatic risk, rash surveillance (especially during lamotrigine titration), and renal/electrolyte monitoring for select agents (e.g., topiramate, oxcarbazepine)."], "memberCols": ["Mechanism type", "TDM needed?", "Notable"], "members": [{"name": "Phenytoin", "a": "Na+ channel blocker", "b": "Yes", "c": "Zero-order (saturable) kinetics — small dose changes cause large level changes; causes gingival hyperplasia, hirsutism, and is a potent enzyme inducer"}, {"name": "Carbamazepine", "a": "Na+ channel blocker", "b": "Yes", "c": "Autoinduces its own metabolism over first few weeks; risk of SJS/TEN linked to HLA-B*1502 (screen in patients of Asian ancestry); causes hyponatremia (SIADH)"}, {"name": "Lamotrigine", "a": "Na+ channel blocker", "b": "No (helpful but not routine)", "c": "Requires very slow titration to minimize risk of serious rash/SJS; levels drop significantly when combined with estrogen-containing contraceptives"}, {"name": "Oxcarbazepine", "a": "Na+ channel blocker", "b": "No", "c": "Keto-analog of carbamazepine with less enzyme induction but higher risk of hyponatremia; less potent interaction profile than carbamazepine"}, {"name": "Valproate (Divalproex)", "a": "Multiple (Na+ channel, GABA transaminase inhibition, T-type Ca2+)", "b": "Yes", "c": "Broad-spectrum; highly teratogenic (neural tube defects) — avoid in women of childbearing potential when possible; hepatotoxicity and pancreatitis risk, causes tremor and weight gain"}, {"name": "Gabapentin", "a": "Ca2+ channel modulator (alpha-2-delta subunit)", "b": "No", "c": "Not hepatically metabolized — renally eliminated with no significant drug interactions; also used for neuropathic pain; low abuse potential but does occur"}, {"name": "Pregabalin", "a": "Ca2+ channel modulator (alpha-2-delta subunit)", "b": "No", "c": "Similar to gabapentin but with linear pharmacokinetics and faster onset; Schedule G controlled substance in Canada due to abuse potential"}, {"name": "Phenobarbital", "a": "GABA-A agonist (barbiturate)", "b": "Yes", "c": "Long half-life, potent enzyme inducer, significant sedation and dependence potential — largely reserved for neonatal seizures and refractory status epilepticus"}, {"name": "Levetiracetam", "a": "SV2A synaptic vesicle modulator", "b": "No", "c": "Minimal drug interactions and no hepatic metabolism (mostly renal) make it a preferred add-on agent; behavioral/psychiatric side effects (irritability) are notable"}, {"name": "Topiramate", "a": "Multiple (Na+ channel, GABA enhancement, glutamate antagonism, carbonic anhydrase inhibition)", "b": "No", "c": "Causes cognitive slowing (\"Dopamax\"), weight loss, metabolic acidosis, and increased kidney stone risk; also used for migraine prophylaxis"}, {"name": "Lacosamide", "a": "Na+ channel blocker (slow inactivation)", "b": "No", "c": "Available IV and PO with 1:1 conversion; can cause PR interval prolongation — caution with cardiac conduction abnormalities"}, {"name": "Ethosuximide", "a": "T-type Ca2+ channel blocker", "b": "Yes", "c": "First-line specifically for absence (petit mal) seizures; not effective for other seizure types"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Valproate carries the highest teratogenic risk (neural tube defects, lower IQ) and should be avoided when possible; most anticonvulsants require folic acid supplementation and specialist-guided risk-benefit discussion, as uncontrolled seizures also pose fetal risk."}, {"label": "Breastfeeding", "warn": true, "text": "Most anticonvulsants are considered compatible with breastfeeding at usual doses, but monitor infants for sedation (especially with phenobarbital); levels of some agents can be significant in milk."}, {"label": "Renal impairment", "warn": true, "text": "Renally cleared agents (gabapentin, pregabalin, levetiracetam) require significant dose reduction based on creatinine clearance; hepatically cleared agents generally do not."}, {"label": "Hepatic impairment", "warn": true, "text": "Valproate is contraindicated in significant hepatic disease due to hepatotoxicity risk; hepatically metabolized agents (carbamazepine, phenytoin) require dose caution and monitoring in liver impairment."}, {"label": "Elderly", "warn": true, "text": "Increased sensitivity to sedation, ataxia, and falls; enzyme-inducing agents increase risk of osteoporosis and drug interactions with polypharmacy — gabapentin/levetiracetam often preferred for cleaner interaction profiles but still need renal dose adjustment."}, {"label": "Pediatrics", "warn": false, "text": "Widely used for pediatric epilepsy syndromes with weight-based dosing; valproate carries a boxed warning for fatal hepatotoxicity in children under 2, especially with metabolic disorders or on multiple anticonvulsants."}]}, {"key": "cholinesterase-inhibitors", "topic": "cns", "name": "Cholinesterase Inhibitors", "pronunciation": "koh-lin-ES-ter-ays in-HIB-ih-ters", "blurb": "Boost acetylcholine levels by blocking its breakdown — centrally-acting members slow cognitive decline in Alzheimer disease, while peripherally-acting members treat myasthenia gravis and reverse neuromuscular blockade.", "general": ["Mechanism: Inhibit acetylcholinesterase (and in some cases butyrylcholinesterase), the enzyme that breaks down acetylcholine in the synaptic cleft, so more acetylcholine remains available to stimulate cholinergic receptors. Agents that cross the blood-brain barrier boost central cholinergic transmission (useful in Alzheimer disease, where cholinergic neurons are lost); agents that stay peripheral boost transmission at the neuromuscular junction (useful in myasthenia gravis and for reversing non-depolarizing neuromuscular blockers).", "Class indications: Centrally-acting agents (donepezil, rivastigmine, galantamine, tacrine) treat mild-to-moderate Alzheimer disease and, for rivastigmine, Parkinson disease dementia; peripherally-acting agents (pyridostigmine, neostigmine, ambenonium, edrophonium) treat myasthenia gravis, reverse non-depolarizing neuromuscular blockade postoperatively, and manage postoperative ileus/urinary retention (neostigmine); physostigmine is used to reverse anticholinergic toxicity because it crosses the blood-brain barrier.", "Class side effects: Excess acetylcholine at muscarinic receptors causes classic cholinergic effects — nausea, vomiting, diarrhea, salivation, bradycardia, and increased bronchial/GI secretions (\"SLUDGE\" symptoms); at nicotinic neuromuscular receptors, excess stimulation can cause muscle cramps/fasciculations and, in overdose, a paradoxical cholinergic crisis with muscle weakness that mimics undertreated myasthenia.", "Class contraindications: Mechanical GI or urinary tract obstruction (increased smooth muscle contraction can worsen obstruction), severe bradycardia/uncorrected cardiac conduction abnormalities, and known hypersensitivity; caution with concurrent depolarizing neuromuscular blockers (succinylcholine), since cholinesterase inhibition prolongs their effect.", "Class monitoring: For dementia agents — cognitive/functional status, weight, and heart rate; for myasthenia agents — muscle strength and respiratory function, watching for the fine line between undertreatment (myasthenic crisis) and overtreatment (cholinergic crisis); atropine should be available at the bedside when giving parenteral peripheral agents to manage excess muscarinic effects."], "memberCols": ["CNS penetration", "Duration", "Notable"], "members": [{"name": "Donepezil", "a": "Central", "b": "Long (once daily)", "c": "Most commonly prescribed Alzheimer agent; long half-life allows once-daily dosing at bedtime"}, {"name": "Rivastigmine", "a": "Central", "b": "Short (patch = sustained)", "c": "Transdermal patch improves GI tolerability versus oral; approved for both Alzheimer and Parkinson disease dementia"}, {"name": "Galantamine", "a": "Central", "b": "Intermediate", "c": "Also allosterically potentiates nicotinic receptors; needs renal/hepatic dose adjustment more than other dementia agents"}, {"name": "Tacrine", "a": "Central", "b": "Short (QID dosing)", "c": "First-in-class Alzheimer agent, now rarely used due to significant hepatotoxicity requiring frequent LFT monitoring"}, {"name": "Pyridostigmine", "a": "Peripheral only (quaternary amine)", "b": "Intermediate", "c": "Mainstay for chronic maintenance therapy of myasthenia gravis; does not cross the blood-brain barrier"}, {"name": "Neostigmine", "a": "Peripheral only (quaternary amine)", "b": "Short", "c": "Used IV to reverse non-depolarizing neuromuscular blockers postoperatively (with an antimuscarinic like glycopyrrolate) and for postoperative ileus/urinary retention"}, {"name": "Physostigmine", "a": "Central (tertiary amine)", "b": "Short", "c": "Crosses the blood-brain barrier, making it useful specifically to reverse severe anticholinergic (antimuscarinic) toxicity/delirium"}, {"name": "Edrophonium", "a": "Peripheral only", "b": "Very short (minutes)", "c": "Rapid onset/offset made it the classic Tensilon test agent for diagnosing myasthenia gravis; largely replaced by antibody testing"}, {"name": "Ambenonium", "a": "Peripheral only", "b": "Intermediate-long", "c": "Alternative maintenance agent for myasthenia gravis in patients intolerant of pyridostigmine; used less commonly"}, {"name": "Echothiophate", "a": "Peripheral (ophthalmic)", "b": "Very long (irreversible-like)", "c": "Long-acting ophthalmic organophosphate historically used for glaucoma; largely discontinued due to cataract formation and systemic absorption risk"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Dementia agents are rarely relevant given the patient population; myasthenia agents (pyridostigmine) are continued in pregnancy when needed since untreated myasthenic crisis poses greater maternal/fetal risk — use the lowest effective dose."}, {"label": "Breastfeeding", "warn": false, "text": "Limited data for most agents; pyridostigmine is generally considered compatible with breastfeeding at usual doses, monitor infant for GI upset."}, {"label": "Renal impairment", "warn": true, "text": "Pyridostigmine and neostigmine are renally eliminated and require dose reduction in renal impairment; galantamine also needs adjustment (avoid if CrCl less than 9 mL/min)."}, {"label": "Hepatic impairment", "warn": true, "text": "Tacrine's significant hepatotoxicity requires baseline and frequent LFT monitoring and limits its use; galantamine and donepezil need cautious dosing and slower titration in hepatic impairment."}, {"label": "Elderly", "warn": true, "text": "The primary population treated for dementia, but also most susceptible to bradycardia, syncope, falls, and GI-related weight loss from cholinergic excess — start low and titrate slowly."}, {"label": "Pediatrics", "warn": false, "text": "Dementia agents have no pediatric indication; peripheral agents (pyridostigmine, neostigmine) are used in pediatric/juvenile myasthenia gravis and for neuromuscular blockade reversal with weight-based dosing."}]}, {"key": "triptans", "topic": "cns", "name": "Triptans", "pronunciation": "TRIP-tans", "blurb": "Selective serotonin 5-HT1B/1D agonists used as first-line abortive therapy for moderate-to-severe migraine.", "general": ["Mechanism: Agonism at 5-HT1B receptors causes vasoconstriction of dilated cranial/meningeal vessels, while 5-HT1D (and presynaptic 5-HT1B/1D) agonism inhibits trigeminal nerve release of vasoactive neuropeptides (CGRP, substance P) — together this reverses the vasodilation and neurogenic inflammation that drive migraine pain.", "Class indications: Acute (abortive) treatment of migraine with or without aura, and menstrually-associated migraine; some agents used for cluster headache. Not for prophylaxis and not for basilar or hemiplegic migraine.", "Class side effects: 'Triptan sensations' — chest/neck/throat tightness or pressure (usually benign, from mild coronary/vascular constriction), flushing, paresthesia, dizziness, fatigue, somnolence. Medication overuse headache with frequent use (>10 days/month).", "Class contraindications: Ischemic heart disease, coronary vasospasm (Prinzmetal angina), uncontrolled hypertension, history of stroke/TIA, peripheral vascular disease, and use within 24 hours of another triptan or an ergot derivative. Caution with concurrent SSRIs/SNRIs/MAOIs (serotonin syndrome risk).", "Class monitoring: Cardiovascular risk assessment before first dose in patients with risk factors; monitor frequency of use to avoid medication overuse headache; assess blood pressure in hypertensive patients; watch for serotonin syndrome signs if combined with other serotonergic drugs."], "memberCols": ["Route(s)", "Onset/Half-life", "Notable"], "members": [{"name": "Sumatriptan (oral)", "a": "PO tablet", "b": "Onset ~30-60 min, t1/2 ~2.5h", "c": "Prototype/first-in-class triptan; low oral bioavailability (~15%) due to extensive first-pass metabolism"}, {"name": "Sumatriptan (SC injection)", "a": "Subcutaneous, self-injectable pen", "b": "Onset fastest of class (~10 min), t1/2 ~2.5h", "c": "Fastest relief in the class; preferred when nausea/vomiting prevents oral dosing; higher rate of triptan sensations at this dose/route"}, {"name": "Sumatriptan (nasal spray)", "a": "Intranasal", "b": "Onset ~15 min, t1/2 ~2.5h", "c": "Bypasses GI absorption issues from nausea; bitter taste is a common complaint"}, {"name": "Rizatriptan", "a": "PO tablet, ODT (wafer)", "b": "Onset ~30-60 min, t1/2 ~2-3h", "c": "ODT useful when swallowing is hard from nausea; reduce dose if on propranolol (increases rizatriptan levels)"}, {"name": "Zolmitriptan (oral/ODT)", "a": "PO, ODT", "b": "Onset ~45 min, t1/2 ~3h", "c": "Active metabolite contributes to effect; ODT does not speed absorption (still swallowed and absorbed in gut) but avoids need for water"}, {"name": "Zolmitriptan (nasal spray)", "a": "Intranasal", "b": "Onset ~15 min, t1/2 ~3h", "c": "Faster onset than oral zolmitriptan via nasal mucosal absorption; useful with nausea/vomiting"}, {"name": "Naratriptan", "a": "PO tablet", "b": "Slower onset (~1-3h), longest t1/2 ~6h", "c": "Longer half-life gives lower recurrence rate; milder side effect profile; good for patients sensitive to triptan sensations"}, {"name": "Almotriptan", "a": "PO tablet", "b": "Onset ~1-3h, t1/2 ~3-4h", "c": "Best tolerability data of the class; partly renally eliminated"}, {"name": "Frovatriptan", "a": "PO tablet", "b": "Slow onset, longest t1/2 ~26h", "c": "Longest half-life in class — favoured for menstrual migraine prophylaxis (short-term) and lowest headache recurrence"}, {"name": "Eletriptan", "a": "PO tablet", "b": "Onset ~1-2h, t1/2 ~4h", "c": "Strong CYP3A4 substrate — avoid with potent CYP3A4 inhibitors (e.g., ketoconazole, clarithromycin, ritonavir) within 72h"}, {"name": "Sumatriptan/Naproxen", "a": "PO combination tablet", "b": "Combines fast triptan onset with NSAID duration", "c": "Combination product targets both vascular and inflammatory components of migraine; more GI caution than triptan alone"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Not first-line; sumatriptan has the most reassuring pregnancy registry data among triptans if a triptan is deemed necessary. Weigh migraine severity against limited safety data for others."}, {"label": "Breastfeeding", "warn": false, "text": "Sumatriptan and eletriptan have low milk transfer and are considered compatible; short interruption of breastfeeding not required for most agents."}, {"label": "Renal impairment", "warn": true, "text": "Almotriptan and eletriptan require caution/dose consideration in significant renal impairment; avoid in severe renal disease where data are lacking."}, {"label": "Hepatic impairment", "warn": true, "text": "Avoid or reduce dose in hepatic impairment — several agents (e.g., zolmitriptan, eletriptan) undergo significant hepatic metabolism; naratriptan and rizatriptan have specific dose caps in mild-moderate impairment."}, {"label": "Elderly", "warn": true, "text": "Use cautiously — higher baseline prevalence of undiagnosed coronary artery disease increases risk of vasospasm-related events; not typically first choice over age 65."}, {"label": "Pediatrics", "warn": false, "text": "Almotriptan (≥12y) and rizatriptan/sumatriptan-naproxen (≥12y) have pediatric indications in some jurisdictions; use weight-based/age-specific dosing and confirm product-specific approval."}]}, {"key": "penicillins", "topic": "infd", "name": "Penicillins", "pronunciation": "pen-ih-SIL-ins", "blurb": "Beta-lactam antibiotics that inhibit bacterial cell wall synthesis; the original antibiotic class, still first-line for many streptococcal and susceptible infections.", "general": ["Mechanism: Beta-lactam ring binds and inhibits penicillin-binding proteins (transpeptidases) that cross-link peptidoglycan in the bacterial cell wall — without cross-linking the wall can't withstand osmotic pressure, so the cell lyses (bactericidal, time-dependent killing).", "Class indications: Narrow-spectrum agents (penicillin G/V) for streptococcal pharyngitis, syphilis; aminopenicillins (amoxicillin, ampicillin) for otitis media, sinusitis, UTI, and with beta-lactamase inhibitors for broader coverage; antistaphylococcal penicillins (cloxacillin) for MSSA; extended-spectrum (piperacillin-tazobactam) for serious/nosocomial and Pseudomonas infections.", "Class side effects: Hypersensitivity reactions (rash to anaphylaxis) are the hallmark; GI upset/diarrhea (amoxicillin especially with clavulanate); C. difficile-associated diarrhea; interstitial nephritis (rare); the classic 'ampicillin rash' in patients with concurrent EBV/mononucleosis is non-allergic.", "Class contraindications: Known IgE-mediated penicillin allergy (anaphylaxis, angioedema, urticaria) — avoid entire class; caution with cephalosporin cross-reactivity (low, ~1-2%, but higher with shared side chains).", "Class monitoring: Clinical response and signs of allergic reaction (especially with first doses); renal function with prolonged high-dose IV therapy (piperacillin-tazobactam, high-dose penicillin G); LFTs with amoxicillin-clavulanate (cholestatic hepatitis risk, more common in older adults and with longer courses)."], "memberCols": ["Spectrum/Subclass", "Beta-lactamase stable?", "Notable"], "members": [{"name": "Penicillin G (benzylpenicillin)", "a": "Narrow-spectrum, strep/syphilis", "b": "No", "c": "IV/IM only (acid-labile); benzathine depot form for single-dose syphilis/strep treatment"}, {"name": "Penicillin V", "a": "Narrow-spectrum, strep", "b": "No", "c": "Oral, acid-stable version of penicillin G; first-line for strep pharyngitis and rheumatic fever prophylaxis"}, {"name": "Amoxicillin", "a": "Aminopenicillin, extended gram-negative coverage", "b": "No", "c": "Most commonly prescribed oral penicillin; better oral bioavailability than ampicillin; first-line for AOM, CAP (mild), H. pylori regimens"}, {"name": "Ampicillin", "a": "Aminopenicillin", "b": "No", "c": "IV formulation retains activity against Listeria and Enterococcus — used in meningitis/endocarditis regimens; classic non-allergic rash with EBV"}, {"name": "Amoxicillin-clavulanate", "a": "Aminopenicillin + beta-lactamase inhibitor", "b": "Yes (via clavulanate)", "c": "Covers beta-lactamase-producing H. influenzae, M. catarrhalis, and anaerobes; higher GI intolerance and rare cholestatic hepatitis"}, {"name": "Ampicillin-sulbactam", "a": "Aminopenicillin + beta-lactamase inhibitor", "b": "Yes (via sulbactam)", "c": "IV only; used for intra-abdominal and polymicrobial infections including anaerobes"}, {"name": "Cloxacillin", "a": "Antistaphylococcal (penicillinase-resistant)", "b": "Yes (intrinsically stable)", "c": "First-line for MSSA (e.g., cellulitis, bacteremia); no activity against MRSA; frequent dosing needed"}, {"name": "Piperacillin-tazobactam", "a": "Extended-spectrum (ureidopenicillin) + beta-lactamase inhibitor", "b": "Yes (via tazobactam)", "c": "Broad empiric coverage including Pseudomonas and anaerobes; workhorse for nosocomial/polymicrobial infections; IV only"}, {"name": "Ticarcillin-clavulanate", "a": "Extended-spectrum (carboxypenicillin) + inhibitor", "b": "Yes", "c": "Historically used for Pseudomonas and gram-negative infections; largely supplanted by piperacillin-tazobactam in Canadian practice"}, {"name": "Penicillin G benzathine", "a": "Narrow-spectrum, depot", "b": "No", "c": "Long-acting IM injection; single-dose treatment for primary/secondary syphilis and strep pharyngitis in nonadherent patients"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Considered safe throughout pregnancy — penicillins are first-line for syphilis (the only proven effective treatment) and GBS prophylaxis in labour."}, {"label": "Breastfeeding", "warn": false, "text": "Compatible with breastfeeding; trace amounts in milk, watch infant for rare rash, diarrhea, or thrush (candidal overgrowth)."}, {"label": "Renal impairment", "warn": true, "text": "Most penicillins are renally eliminated — reduce dose/frequency in CrCl <30 mL/min; high-dose IV penicillin G can cause neurotoxicity/seizures if accumulated in renal failure."}, {"label": "Hepatic impairment", "warn": true, "text": "Amoxicillin-clavulanate carries a risk of cholestatic hepatitis, more common in hepatic impairment and older males — use cautiously and monitor LFTs; other penicillins largely renally cleared and safer hepatically."}, {"label": "Elderly", "warn": true, "text": "Higher risk of amoxicillin-clavulanate-associated hepatotoxicity and C. difficile infection; renal dose adjustment often needed due to age-related decline in CrCl."}, {"label": "Pediatrics", "warn": false, "text": "Widely used and well-studied in children (weight-based dosing); amoxicillin is first-line for acute otitis media and streptococcal pharyngitis in pediatric guidelines."}]}, {"key": "cephalosporins", "topic": "infd", "name": "Cephalosporins", "pronunciation": "sef-uh-loh-SPOR-ins", "blurb": "Beta-lactam antibiotics organized into generations, with each successive generation trading some gram-positive activity for broader gram-negative (and eventually anti-pseudomonal or MRSA) coverage.", "general": ["Mechanism: Like penicillins, the beta-lactam ring binds penicillin-binding proteins to block peptidoglycan cross-linking, causing bactericidal cell lysis; the dihydrothiazine ring confers greater intrinsic stability against many staphylococcal beta-lactamases than natural penicillins.", "Class indications: Generation-dependent — 1st-gen for skin/soft tissue and surgical prophylaxis (gram-positive-heavy), 2nd-gen for respiratory/intra-abdominal (added H. influenzae/anaerobe coverage), 3rd-gen for serious gram-negative and CNS infections (CSF penetration), 4th-gen for empiric coverage including Pseudomonas, 5th-gen (ceftaroline) for MRSA.", "Class side effects: Hypersensitivity (rash more common than anaphylaxis), GI upset, C. difficile-associated diarrhea (notably high risk with broad-spectrum agents), disulfiram-like reaction with alcohol (agents containing an N-methylthiotetrazole side chain, e.g., cefotetan), vitamin K-dependent coagulopathy with prolonged use of those same agents.", "Class contraindications: Known immediate hypersensitivity to cephalosporins; caution (not absolute contraindication) in patients with severe/anaphylactic penicillin allergy given a small (~1-2%) rate of cross-reactivity, higher when the R1 side chain is shared (e.g., cefadroxil/cephalexin with amoxicillin).", "Class monitoring: Renal function (most are renally cleared and need dose adjustment); signs of allergic reaction; INR if on warfarin with agents that disrupt gut flora/vitamin K synthesis; clinical response and C. difficile symptoms with prolonged broad-spectrum courses."], "memberCols": ["Generation", "Spectrum highlight", "Notable"], "members": [{"name": "Cefazolin", "a": "1st", "b": "Strong gram-positive (MSSA, strep); minimal gram-negative", "c": "Drug of choice for surgical prophylaxis and MSSA bacteremia/endocarditis (IV)"}, {"name": "Cephalexin", "a": "1st", "b": "Gram-positive; some E. coli/Proteus/Klebsiella", "c": "Oral workhorse for cellulitis and uncomplicated UTI; shares R1 side chain with amoxicillin (higher cross-reactivity)"}, {"name": "Cefadroxil", "a": "1st", "b": "Similar to cephalexin", "c": "Longer half-life allows once/twice-daily dosing, useful for adherence"}, {"name": "Cefuroxime", "a": "2nd", "b": "Gram-positive retained + H. influenzae, M. catarrhalis, N. gonorrhoeae", "c": "Available IV and oral; used for CAP, sinusitis, and early Lyme disease"}, {"name": "Cefaclor", "a": "2nd", "b": "Similar to cefuroxime, weaker overall", "c": "Oral only; largely replaced by cefuroxime/amoxicillin-clavulanate in practice"}, {"name": "Cefoxitin", "a": "2nd (cephamycin)", "b": "Adds anaerobic (B. fragilis) coverage", "c": "Used for intra-abdominal/pelvic infections and PID due to anaerobe activity"}, {"name": "Cefotaxime", "a": "3rd", "b": "Broad gram-negative + good CNS penetration", "c": "Preferred 3rd-gen for neonatal sepsis/meningitis (avoids ceftriaxone's biliary sludging/kernicterus displacement risk)"}, {"name": "Ceftriaxone", "a": "3rd", "b": "Broad gram-negative, good CNS penetration, no Pseudomonas", "c": "Once-daily IV/IM dosing (long half-life); first-line for CAP, meningitis, gonorrhea; avoid with calcium-containing IV fluids in neonates"}, {"name": "Cefixime", "a": "3rd", "b": "Gram-negative-heavy oral option", "c": "Oral 3rd-gen; used for uncomplicated gonorrhea (alternative) and susceptible UTI/respiratory infections"}, {"name": "Ceftazidime", "a": "3rd (anti-pseudomonal)", "b": "Strong Pseudomonas coverage; weaker gram-positive", "c": "Used for pseudomonal infections (e.g., febrile neutropenia, hospital-acquired pneumonia); poor gram-positive activity"}, {"name": "Cefepime", "a": "4th", "b": "Broad gram-positive AND gram-negative including Pseudomonas", "c": "'Best of both worlds' — common empiric choice for febrile neutropenia and nosocomial infections; neurotoxicity/encephalopathy risk if not renally dose-adjusted"}, {"name": "Ceftaroline", "a": "5th", "b": "Adds MRSA and VRSA coverage plus typical gram-negatives", "c": "Only beta-lactam with reliable MRSA activity; used for complicated skin/soft tissue infections and CAP; no Pseudomonas coverage"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Generally considered safe in pregnancy; ceftriaxone and cefazolin are commonly used for infections and surgical prophylaxis (e.g., cesarean section) in pregnant patients."}, {"label": "Breastfeeding", "warn": false, "text": "Compatible with breastfeeding; minimal transfer into milk, watch infant for diarrhea or thrush from flora disruption."}, {"label": "Renal impairment", "warn": true, "text": "Most cephalosporins require dose/interval adjustment based on CrCl (ceftriaxone is a notable exception — primarily biliary/hepatic elimination, no adjustment needed); cefepime accumulation in renal failure can cause neurotoxicity/seizures."}, {"label": "Hepatic impairment", "warn": true, "text": "Ceftriaxone is dually eliminated (renal + biliary) — use caution and consider dose capping in combined hepatic and renal impairment; other agents are primarily renally cleared and need less hepatic-specific adjustment."}, {"label": "Elderly", "warn": true, "text": "Higher risk of C. difficile infection with broad-spectrum agents; renal dose adjustment often required due to age-related decline in CrCl even with normal serum creatinine."}, {"label": "Pediatrics", "warn": true, "text": "Widely used with weight-based dosing; avoid ceftriaxone in neonates (especially with IV calcium) due to risk of fatal calcium-ceftriaxone precipitation and bilirubin displacement/kernicterus — cefotaxime is preferred in neonates."}]}, {"key": "fluoroquinolones", "topic": "infd", "name": "Fluoroquinolones", "pronunciation": "flor-oh-KWIN-oh-lones", "blurb": "Broad-spectrum bactericidal antibiotics that block bacterial DNA replication; reserved for specific indications due to serious class-wide toxicity warnings.", "general": ["Mechanism: Inhibit bacterial DNA gyrase (topoisomerase II, mainly gram-negative) and topoisomerase IV (mainly gram-positive), enzymes needed to unwind and supercoil DNA during replication — trapping the enzyme-DNA complex causes double-strand breaks and rapid bactericidal cell death.", "Class indications: Complicated UTI/pyelonephritis, some respiratory infections (respiratory quinolones for CAP), intra-abdominal infections (with metronidazole), traveler's diarrhea, and specific uses like anthrax prophylaxis; increasingly restricted to when alternatives are unsuitable due to safety warnings.", "Class side effects: Tendinopathy/tendon rupture (Achilles), peripheral neuropathy (can be irreversible), CNS effects (dizziness, seizure risk by lowering seizure threshold, rare psychiatric effects), QT prolongation, and aortic aneurysm/dissection risk — these black-box-level warnings led Health Canada to restrict use to when no other options are suitable for certain infections.", "Class contraindications: Prior fluoroquinolone-associated tendon or CNS/psychiatric reaction; myasthenia gravis (can worsen muscle weakness); use with caution alongside other QT-prolonging drugs; avoid concurrent corticosteroids (raises tendon rupture risk) especially in patients over 60.", "Class monitoring: Watch for tendon pain/swelling (stop immediately if present), signs of peripheral neuropathy, QTc if risk factors present, mental status changes, and blood glucose in diabetics (risk of both hypo- and hyperglycemia, especially with gatifloxacin-type effects); separate dosing from divalent/trivalent cations (antacids, calcium, iron, zinc) by 2-6 hours as they chelate and reduce absorption."], "memberCols": ["Spectrum emphasis", "QT/Tendon risk", "Notable"], "members": [{"name": "Ciprofloxacin", "a": "Strongest gram-negative (incl. Pseudomonas); weak strep/pneumococcus", "b": "Moderate QT; standard tendon risk", "c": "Not a reliable respiratory agent (poor pneumococcal coverage); first-line for pseudomonal and complicated UTI; strong CYP1A2 inhibitor (raises theophylline, caffeine, tizanidine levels)"}, {"name": "Levofloxacin", "a": "Broad gram-negative + good gram-positive (respiratory quinolone)", "b": "Higher QT risk; standard tendon risk", "c": "L-isomer of ofloxacin; used for CAP, sinusitis, complicated UTI; widely used first-line 'respiratory' fluoroquinolone in Canada"}, {"name": "Moxifloxacin", "a": "Best gram-positive/anaerobic coverage of the class (respiratory quinolone)", "b": "Highest QT risk in class; standard tendon risk", "c": "No reliable urinary excretion — NOT recommended for UTI; useful for CAP and intra-abdominal infections due to anaerobic activity"}, {"name": "Norfloxacin", "a": "Gram-negative, urinary tract only", "b": "Lower systemic exposure (poor tissue penetration)", "c": "Used almost exclusively for uncomplicated UTI; not effective for systemic infections due to low serum levels"}, {"name": "Ofloxacin", "a": "Gram-negative + some gram-positive/atypicals", "b": "Moderate QT/tendon risk", "c": "Racemic parent of levofloxacin; also available as ophthalmic/otic formulations"}, {"name": "Gemifloxacin", "a": "Enhanced gram-positive (respiratory quinolone)", "b": "Moderate-high QT risk; rash more common", "c": "Higher rate of rash (especially in younger women) limits use; reserved respiratory quinolone option"}, {"name": "Delafloxacin", "a": "Broad including MRSA activity", "b": "Lower QT risk reported vs. older agents", "c": "Newer agent with anionic structure allowing activity at acidic pH (abscess sites); used for acute bacterial skin/skin structure infections"}, {"name": "Ciprofloxacin (ophthalmic/otic)", "a": "Topical gram-negative coverage", "b": "Minimal systemic risk", "c": "Used for bacterial conjunctivitis and otitis externa; avoids systemic class warnings due to negligible absorption"}, {"name": "Ciprofloxacin (extended-release)", "a": "Same gram-negative spectrum as immediate-release", "b": "Moderate QT; standard tendon risk", "c": "Once-daily ER tablet formulated for uncomplicated UTI/pyelonephritis; improves adherence over BID immediate-release dosing"}, {"name": "Moxifloxacin (ophthalmic)", "a": "Topical broad-spectrum incl. gram-positive ocular pathogens", "b": "Minimal systemic risk", "c": "Used for bacterial conjunctivitis; negligible systemic absorption avoids the class's systemic tendon/QT warnings"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Avoid in pregnancy — animal data show arthropathy/cartilage damage in immature joints; reserve for situations with no safer alternative."}, {"label": "Breastfeeding", "warn": true, "text": "Generally avoided due to theoretical risk of arthropathy in the infant, though excreted in low amounts; use an alternative agent when possible."}, {"label": "Renal impairment", "warn": true, "text": "Most fluoroquinolones (except moxifloxacin, which is primarily hepatically metabolized) require dose/interval adjustment in renal impairment — accumulation raises CNS and tendon toxicity risk."}, {"label": "Hepatic impairment", "warn": true, "text": "Moxifloxacin is primarily hepatically eliminated — use caution and consider alternatives in significant hepatic impairment; rare reports of severe hepatotoxicity across the class."}, {"label": "Elderly", "warn": true, "text": "Significantly higher risk of tendon rupture (especially with concurrent corticosteroids), aortic aneurysm/dissection, CNS effects, and C. difficile infection — Health Canada specifically flags caution in this population."}, {"label": "Pediatrics", "warn": true, "text": "Historically avoided due to cartilage/joint toxicity seen in juvenile animal studies; now used in children only for specific indications (e.g., complicated UTI, inhalational anthrax, cystic fibrosis pulmonary exacerbations) when benefits outweigh risks."}]}, {"key": "macrolides", "topic": "infd", "name": "Macrolides", "pronunciation": "MAK-roh-lyds", "blurb": "50S-ribosome-binding antibiotics used for atypical pneumonia and as penicillin-allergy alternatives, but limited by CYP3A4 interactions and QT risk.", "general": ["Mechanism: Bind reversibly to the 50S ribosomal subunit (23S rRNA) and block the translocation step of protein synthesis, giving bacteriostatic activity against many respiratory and atypical pathogens. Several members also inhibit hepatic CYP3A4 and cardiac hERG/IKr potassium channels, which is why the class is notorious for drug interactions and dose-dependent QT prolongation.", "Class indications: Community-acquired/atypical pneumonia (Mycoplasma, Chlamydophila, Legionella), pertussis, chlamydial urethritis/cervicitis, H. pylori eradication (clarithromycin), Mycobacterium avium complex treatment/prophylaxis, and as a first-line alternative for streptococcal pharyngitis or acne in penicillin-allergic patients.", "Class side effects: GI upset and cramping (erythromycin acts as a motilin agonist and is the worst offender), QT prolongation/torsades de pointes, reversible cholestatic hepatitis (most linked to the estolate salt), reversible high-dose ototoxicity, and C. difficile diarrhea.", "Class contraindications: Concurrent use with other QT-prolonging drugs or with narrow-therapeutic-index CYP3A4 substrates (ergot alkaloids, colchicine in renal/hepatic impairment, simvastatin/lovastatin, pimozide); pre-existing QT prolongation or uncorrected electrolyte abnormalities; prior cholestatic jaundice with the same agent.", "Class monitoring: Baseline ECG/QTc in patients with cardiac risk factors or interacting drugs, LFTs with prolonged courses, clinical/symptomatic response, and a drug-interaction check (especially statins, warfarin, and CYP3A4 substrates) at every new prescription."], "memberCols": ["Dosing", "CYP3A4 inhibition", "Notable"], "members": [{"name": "Erythromycin base", "a": "TID-QID, on empty stomach", "b": "Strong", "c": "First-in-class; acid-labile, needs enteric coating; prototype motilin agonist causing GI upset"}, {"name": "Erythromycin stearate", "a": "TID-QID", "b": "Strong", "c": "Salt form improves acid stability; still frequent GI intolerance"}, {"name": "Erythromycin ethylsuccinate", "a": "TID-QID", "b": "Strong", "c": "Common pediatric suspension; better palatability"}, {"name": "Erythromycin estolate", "a": "TID-QID", "b": "Strong", "c": "Highest risk of reversible cholestatic hepatitis; avoid in pregnancy"}, {"name": "Erythromycin lactobionate (IV)", "a": "IV infusion", "b": "Strong", "c": "IV form for severe infections (e.g., Legionella) when oral not feasible; phlebitis risk"}, {"name": "Clarithromycin (IR)", "a": "BID", "b": "Strong", "c": "Active metabolite (14-OH-clarithromycin); key component of H. pylori regimens"}, {"name": "Clarithromycin XL", "a": "OD with food", "b": "Strong", "c": "Extended-release improves GI tolerability vs immediate-release"}, {"name": "Azithromycin", "a": "OD, short 3-5 day courses (Z-pak)", "b": "Minimal", "c": "Long tissue half-life allows short courses; safest macrolide for CYP3A4 interactions but still QT risk"}, {"name": "Fidaxomicin", "a": "BID x10 days", "b": "None (not absorbed)", "c": "Macrocyclic antibiotic used only for C. difficile; minimal systemic absorption, spares gut flora better than vancomycin"}, {"name": "Telithromycin", "a": "OD", "b": "Strong", "c": "Ketolide (macrolide derivative); withdrawn from the Canadian market after reports of fulminant hepatotoxicity, visual disturbance, and myasthenia exacerbation"}, {"name": "Spiramycin", "a": "Divided daily doses", "b": "Weak", "c": "Used for toxoplasmosis prophylaxis in pregnancy to reduce vertical transmission; available in Canada via Health Canada Special Access"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Azithromycin is generally preferred when a macrolide is needed; avoid the estolate salt of erythromycin (hepatotoxicity risk). Spiramycin is specifically used to reduce vertical transmission of toxoplasmosis."}, {"label": "Breastfeeding", "warn": false, "text": "Erythromycin and azithromycin are generally considered compatible; watch infant for GI upset or, rarely, infantile hypertrophic pyloric stenosis with erythromycin exposure in the first weeks of life."}, {"label": "Renal impairment", "warn": false, "text": "Mostly hepatically eliminated; clarithromycin dose should be reduced in severe renal impairment (CrCl <30 mL/min). Azithromycin needs no adjustment."}, {"label": "Hepatic impairment", "warn": true, "text": "Use caution or avoid — the class is hepatically metabolized and several members (erythromycin estolate, telithromycin) carry meaningful hepatotoxicity risk."}, {"label": "Elderly", "warn": true, "text": "Higher baseline QT-prolongation and drug-interaction risk given polypharmacy; screen concurrent medications and correct electrolytes before starting."}, {"label": "Pediatrics", "warn": false, "text": "Widely used and generally well tolerated; azithromycin and clarithromycin suspensions are common first-line agents for pediatric respiratory infections."}]}, {"key": "tetracyclines", "topic": "infd", "name": "Tetracyclines", "pronunciation": "tet-rah-SY-klleens", "blurb": "30S-ribosome-binding broad-spectrum antibiotics that chelate divalent cations, causing tooth staining and interactions with dairy/antacids/iron.", "general": ["Mechanism: Bind reversibly to the 30S ribosomal subunit and block attachment of aminoacyl-tRNA, producing bacteriostatic activity against a broad range of gram-positive, gram-negative, atypical, and protozoal organisms. The same molecule chelates divalent and trivalent cations (Ca2+, Mg2+, Fe2+, Al3+, Zn2+), which is why dairy products, antacids, and iron/mineral supplements block absorption AND why the drug deposits in growing bone and developing teeth, causing staining and enamel hypoplasia.", "Class indications: Acne vulgaris/rosacea, atypical pneumonia, Lyme disease, rickettsial infections (e.g., Rocky Mountain spotted fever), chlamydial infections, community-acquired MRSA skin infections (doxycycline), malaria chemoprophylaxis (doxycycline), and as part of H. pylori quadruple therapy.", "Class side effects: Photosensitivity/sunburn reaction, GI upset and pill-induced esophagitis (take with a full glass of water and remain upright), permanent tooth discoloration and enamel hypoplasia in children, vestibular toxicity (dizziness, more common with minocycline), and rare benign intracranial hypertension (pseudotumor cerebri).", "Class contraindications: Pregnancy (fetal bone/tooth deposition), children under 8 years for most indications (short courses may be used when benefit clearly outweighs risk, e.g., Rocky Mountain spotted fever), and concurrent administration with divalent/trivalent cation products (separate dosing by at least 2-3 hours).", "Class monitoring: Renal and hepatic function with prolonged therapy, sun-exposure/photosensitivity counselling, clinical response, and vigilance for headache or visual changes suggesting intracranial hypertension, particularly when minocycline is combined with isotretinoin."], "memberCols": ["Lipid solubility / renal clearance", "Renal dose adjustment?", "Notable"], "members": [{"name": "Tetracycline", "a": "Low lipid solubility, mainly renal clearance", "b": "Yes", "c": "Original prototype; multiple daily doses; largely replaced by doxycycline"}, {"name": "Doxycycline hyclate", "a": "High lipid solubility, mainly fecal/biliary clearance", "b": "No", "c": "Most commonly used tetracycline; can be dosed BID-OD; hyclate salt more likely to cause esophagitis if taken without water"}, {"name": "Doxycycline monohydrate", "a": "High lipid solubility, fecal/biliary clearance", "b": "No", "c": "Better GI tolerability than hyclate salt; same spectrum/dosing"}, {"name": "Minocycline (IR)", "a": "Very high lipid solubility, hepatic metabolism", "b": "No", "c": "Best CNS penetration; higher risk of vestibular toxicity (vertigo/ataxia) and drug-induced lupus with long-term acne use"}, {"name": "Minocycline extended-release", "a": "High lipid solubility, hepatic metabolism", "b": "No", "c": "Weight-based dosing for acne; lower peak levels reduce vestibular side effects vs immediate-release"}, {"name": "Demeclocycline", "a": "Low lipid solubility, renal clearance", "b": "Yes", "c": "Unique use: induces nephrogenic diabetes insipidus, used off-label to treat SIADH"}, {"name": "Oxytetracycline", "a": "Low lipid solubility, renal clearance", "b": "Yes", "c": "Similar profile to tetracycline; limited human use in Canada, mainly older formulations"}, {"name": "Chlortetracycline (topical/ophthalmic)", "a": "Topical only", "b": "N/A", "c": "Used in ophthalmic ointment for ocular infections; negligible systemic absorption"}, {"name": "Tigecycline", "a": "IV only, high tissue penetration, biliary clearance", "b": "No (mild hepatic adjustment)", "c": "Glycylcycline; bypasses common tetracycline resistance mechanisms; boxed warning for increased mortality vs comparators in serious infections"}, {"name": "Eravacycline", "a": "IV only, hepatic/biliary clearance", "b": "No", "c": "Newer fluorocycline for complicated intra-abdominal infections; active against many MDR gram-negatives including some carbapenem-resistant strains"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Contraindicated — crosses the placenta and deposits in fetal bone and developing teeth, causing discoloration and inhibited bone growth."}, {"label": "Breastfeeding", "warn": true, "text": "Generally avoided for prolonged courses; short courses are sometimes accepted since calcium in breast milk may partly bind the drug, but alternatives are preferred."}, {"label": "Renal impairment", "warn": true, "text": "Older tetracyclines (tetracycline, oxytetracycline, demeclocycline) accumulate and can worsen azotemia — avoid or reduce dose. Doxycycline, minocycline, and tigecycline are safe without adjustment since they are eliminated non-renally."}, {"label": "Hepatic impairment", "warn": true, "text": "Use caution, especially with high-dose IV tetracycline (historically linked to fatal hepatotoxicity) and with tigecycline, which requires dose reduction in severe impairment."}, {"label": "Elderly", "warn": false, "text": "No specific class restriction, but check renal function before using older agents and counsel on photosensitivity and esophagitis prevention (take upright with water)."}, {"label": "Pediatrics", "warn": true, "text": "Avoid under age 8 for routine indications due to permanent tooth staining and enamel hypoplasia; reserved for specific infections (e.g., RMSF) where benefits outweigh risk."}]}, {"key": "aminoglycosides", "topic": "infd", "name": "Aminoglycosides", "pronunciation": "ah-MEE-noh-GLY-koh-sydes", "blurb": "Bactericidal 30S-binding agents for serious gram-negative infections, requiring therapeutic drug monitoring due to nephrotoxicity and ototoxicity.", "general": ["Mechanism: Bind irreversibly to the 30S ribosomal subunit, causing misreading of mRNA codons and production of nonfunctional proteins — this gives concentration-dependent bactericidal killing with a post-antibiotic effect (activity persists after levels fall), which is why once-daily/extended-interval dosing works. Uptake into bacteria is an oxygen-dependent active process, so the class has no activity against anaerobes; the same active-transport mechanism concentrates drug in renal proximal tubule cells and inner-ear hair cells, driving the class's signature nephrotoxicity and ototoxicity.", "Class indications: Serious gram-negative infections (sepsis, hospital-acquired/ventilator-associated pneumonia, complicated pyelonephritis), synergistic combination therapy with a beta-lactam or vancomycin for gram-positive endocarditis, empiric coverage in febrile neutropenia, tuberculosis (streptomycin), and non-absorbed oral neomycin for bowel prep or hepatic encephalopathy.", "Class side effects: Nephrotoxicity (usually reversible acute tubular necrosis, dose- and duration-dependent), ototoxicity (cochlear and/or vestibular, may be irreversible and is not always dose-related), and rare neuromuscular blockade/respiratory paralysis, particularly with rapid IV infusion or concurrent neuromuscular blockers.", "Class contraindications: Myasthenia gravis (relative — neuromuscular blockade can precipitate crisis), pregnancy (fetal ototoxicity, especially streptomycin), and caution/avoidance in patients with pre-existing significant renal impairment or hearing loss unless no safer alternative exists.", "Class monitoring: Therapeutic drug monitoring (peak/trough levels for traditional dosing, or a single random level against a nomogram for extended-interval/once-daily dosing), serial serum creatinine, baseline and periodic audiometry with prolonged courses, and clinical assessment of vestibular symptoms (dizziness, ataxia, tinnitus)."], "memberCols": ["Route", "Spectrum highlight", "Notable"], "members": [{"name": "Gentamicin (systemic)", "a": "IV/IM", "b": "Broad gram-negative; synergy vs enterococcus/strep with a beta-lactam", "c": "Most commonly used aminoglycoside; workhorse for synergy in endocarditis"}, {"name": "Gentamicin (topical/ophthalmic)", "a": "Topical/ophthalmic", "b": "Skin/eye gram-negative pathogens", "c": "Minimal systemic absorption; used for superficial skin and eye infections"}, {"name": "Tobramycin (systemic)", "a": "IV/IM", "b": "Enhanced activity vs Pseudomonas aeruginosa vs gentamicin", "c": "Preferred over gentamicin when Pseudomonas is suspected"}, {"name": "Tobramycin (inhaled)", "a": "Nebulized", "b": "Pseudomonas in cystic fibrosis airways", "c": "High local airway concentration with minimal systemic absorption/toxicity"}, {"name": "Amikacin", "a": "IV/IM", "b": "Most resistant to aminoglycoside-modifying enzymes", "c": "Reserved agent for gentamicin/tobramycin-resistant gram-negatives, including some MDR TB regimens"}, {"name": "Streptomycin", "a": "IM", "b": "Mycobacterium tuberculosis, plague, tularemia", "c": "First aminoglycoside discovered; now mainly reserved for TB and select zoonoses"}, {"name": "Neomycin (oral)", "a": "Oral, non-absorbed", "b": "Gut flora reduction", "c": "Used for bowel prep before surgery and to lower ammonia-producing flora in hepatic encephalopathy"}, {"name": "Paromomycin", "a": "Oral, non-absorbed", "b": "Intestinal amebiasis, hepatic encephalopathy", "c": "Alternative to neomycin/lactulose; also used for luminal amebiasis"}, {"name": "Netilmicin", "a": "IV/IM", "b": "Similar to gentamicin, historically less ototoxic", "c": "Largely discontinued/limited availability in Canada; superseded by other agents"}, {"name": "Spectinomycin", "a": "IM", "b": "Historic alternative for gonorrhea in penicillin/cephalosporin allergy", "c": "Structurally an aminocyclitol (related class); no cross-resistance with true aminoglycosides"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Avoid when possible — crosses the placenta and can cause irreversible fetal ototoxicity/deafness; streptomycin carries the strongest documented risk."}, {"label": "Breastfeeding", "warn": false, "text": "Oral bioavailability is poor, so systemic infant exposure via breast milk is minimal; generally considered compatible."}, {"label": "Renal impairment", "warn": true, "text": "Renally eliminated and nephrotoxic — requires dose/interval adjustment guided by renal function and drug levels; nephrotoxicity itself can further impair clearance, creating a feedback risk."}, {"label": "Hepatic impairment", "warn": false, "text": "Not hepatically metabolized, so no specific dose adjustment is needed for liver disease alone."}, {"label": "Elderly", "warn": true, "text": "Higher baseline risk of age-related renal decline and hearing loss — use conservative dosing, extended-interval regimens where appropriate, and close monitoring."}, {"label": "Pediatrics", "warn": true, "text": "Used when indicated but requires weight-based dosing and careful TDM — children's changing renal clearance and growth make levels harder to predict."}]}, {"key": "azole-antifungals", "topic": "infd", "name": "Azole Antifungals", "pronunciation": "AY-zohl an-tie-FUN-gulz", "blurb": "CYP51-inhibiting antifungals that block ergosterol synthesis, with extensive CYP3A4-mediated drug interactions across the class.", "general": ["Mechanism: Inhibit fungal CYP51 (lanosterol 14-alpha-demethylase), blocking conversion of lanosterol to ergosterol and weakening the fungal cell membrane (fungistatic against most yeasts). Because CYP51 is a cytochrome P450 enzyme, azoles — especially ketoconazole, itraconazole, and voriconazole — are also potent inhibitors of human hepatic CYP3A4 (and other isoenzymes), which is the basis of the class's extensive drug interactions and, at higher systemic exposure, inhibition of human adrenal/gonadal steroidogenesis (adrenal insufficiency, gynecomastia most notable with ketoconazole).", "Class indications: Oral, vaginal, and invasive candidiasis; dermatophyte/tinea infections and seborrheic dermatitis (topical agents); invasive aspergillosis (voriconazole, isavuconazole); histoplasmosis and blastomycosis (itraconazole); and antifungal prophylaxis in neutropenic or transplant patients.", "Class side effects: Hepatotoxicity/transaminase elevation, QT prolongation (notably fluconazole and voriconazole), GI upset, rash/photosensitivity, and visual disturbances (transient, dose-related, characteristic of voriconazole).", "Class contraindications: High-dose fluconazole in pregnancy (teratogenic, associated with a pattern of craniofacial and skeletal defects); concurrent use with narrow-therapeutic-index CYP3A4 substrates (ergot alkaloids, certain statins, quinidine, pimozide); and significant hepatic impairment (dose reduction or avoidance depending on agent).", "Class monitoring: Baseline and periodic LFTs, ECG/QTc in patients with risk factors, therapeutic drug monitoring for voriconazole and posaconazole (narrow therapeutic window, variable pharmacokinetics), renal function for IV voriconazole (cyclodextrin vehicle accumulates in renal impairment), and clinical/mycological response."], "memberCols": ["Route", "Spectrum", "Notable"], "members": [{"name": "Fluconazole", "a": "Oral/IV", "b": "Candida (not C. krusei/glabrata-resistant strains), Cryptococcus", "c": "Excellent bioavailability and CSF penetration; weakest CYP3A4 inhibitor of the systemic azoles but still QT risk"}, {"name": "Itraconazole", "a": "Oral", "b": "Dermatophytes, histoplasmosis, blastomycosis, some Aspergillus", "c": "Erratic absorption (capsule needs acid/food; solution needs empty stomach); negative inotrope, avoid in heart failure"}, {"name": "Voriconazole", "a": "Oral/IV", "b": "Invasive aspergillosis (first-line), Candida", "c": "Nonlinear pharmacokinetics; visual disturbances and phototoxicity common; requires TDM"}, {"name": "Posaconazole", "a": "Oral (delayed-release/suspension)/IV", "b": "Broadest spectrum including some Mucorales/zygomycetes", "c": "Used for prophylaxis in high-risk neutropenic/GVHD patients; delayed-release tablet has more reliable absorption than suspension"}, {"name": "Isavuconazole", "a": "Oral/IV", "b": "Invasive aspergillosis and mucormycosis", "c": "Unlike other azoles, shortens QT interval rather than prolonging it; more predictable pharmacokinetics, no TDM routinely required"}, {"name": "Ketoconazole (topical/shampoo)", "a": "Topical/shampoo (oral discontinued)", "b": "Tinea, seborrheic dermatitis, dandruff", "c": "Oral form withdrawn/restricted in Canada due to hepatotoxicity and adrenal suppression risk; topical use remains common"}, {"name": "Clotrimazole", "a": "Topical/vaginal", "b": "Dermatophytes, vulvovaginal candidiasis", "c": "OTC vaginal and topical products; minimal systemic absorption/interactions"}, {"name": "Miconazole", "a": "Topical/vaginal", "b": "Dermatophytes, vulvovaginal candidiasis", "c": "OTC availability; oral gel formulation carries warfarin interaction warning even with topical/buccal use"}, {"name": "Terconazole", "a": "Vaginal", "b": "Vulvovaginal candidiasis", "c": "Prescription vaginal azole, sometimes used when OTC agents fail"}, {"name": "Econazole", "a": "Topical", "b": "Dermatophytes, cutaneous candidiasis", "c": "Once-daily topical dosing; negligible systemic exposure"}, {"name": "Tioconazole", "a": "Vaginal (single dose)", "b": "Vulvovaginal candidiasis", "c": "OTC single-dose ointment; convenient adherence option"}, {"name": "Sertaconazole", "a": "Topical", "b": "Tinea pedis/dermatophytes", "c": "Newer topical azole with additional antifungal (benzothiophene) ring structure"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "High-dose/prolonged fluconazole is teratogenic (craniofacial and skeletal anomalies) — avoid in the first trimester; a single low dose for vaginal candidiasis is more debated but topical azoles are preferred instead. Voriconazole and other systemic azoles are generally avoided unless benefit clearly outweighs risk."}, {"label": "Breastfeeding", "warn": false, "text": "Fluconazole is generally considered compatible at standard doses; topical/vaginal azoles have minimal systemic absorption and are preferred when adequate."}, {"label": "Renal impairment", "warn": true, "text": "Fluconazole requires dose adjustment (renally cleared unchanged); IV voriconazole's cyclodextrin vehicle accumulates in renal impairment — oral voriconazole is preferred when CrCl is low."}, {"label": "Hepatic impairment", "warn": true, "text": "Class-wide hepatotoxicity risk — dose reduction or avoidance needed with significant hepatic impairment; monitor LFTs closely, especially with itraconazole and voriconazole."}, {"label": "Elderly", "warn": true, "text": "Higher likelihood of polypharmacy increases CYP3A4 interaction risk (statins, anticoagulants, antiarrhythmics) — review the full medication list before starting any systemic azole."}, {"label": "Pediatrics", "warn": false, "text": "Fluconazole is commonly used and well studied in children with weight-based dosing; other systemic azoles are used more selectively based on indication and specialist input."}]}, {"key": "k-sparing-diuretics-mra", "topic": "renal", "name": "Potassium-Sparing Diuretics / Mineralocorticoid Receptor Antagonists", "pronunciation": "poh-TASS-ee-um SPAIR-ing DY-yoo-RET-iks / MIN-er-al-oh-KOR-tih-koyd ree-SEP-ter an-TAG-oh-nists", "blurb": "Weak diuretics used mainly to counteract kaliuresis from loop/thiazide diuretics or to block aldosterone in heart failure, resistant hypertension, and cirrhotic ascites.", "general": ["Mechanism: Two subtypes exist. Aldosterone (mineralocorticoid) receptor antagonists (spironolactone, eplerenone, finerenone) competitively block aldosterone at the distal nephron's principal cells, reducing Na+ reabsorption and K+/H+ secretion; epithelial sodium channel (ENaC) blockers (amiloride, triamterene) plug the channel directly without needing to compete with aldosterone. Both routes reduce distal Na+ reabsorption for weak diuresis but strong K+-sparing effects.", "Class indications: Add-on for resistant hypertension and hypokalemia prevention with loop/thiazide diuretics; HFrEF (mortality benefit for spironolactone/eplerenone at low dose); primary hyperaldosteronism; cirrhotic ascites (spironolactone first-line); finerenone specifically for diabetic kidney disease to slow CKD progression and reduce CV events.", "Class side effects: Hyperkalemia (all members, dose-limiting) and metabolic acidosis; steroidal MRAs (spironolactone) additionally cause gynecomastia, menstrual irregularities, and impotence via off-target progesterone/androgen receptor binding — eplerenone and finerenone are more receptor-selective and largely avoid this.", "Class contraindications: Hyperkalemia (K+ above ~5.0-5.5 depending on agent), severe renal impairment (eGFR thresholds vary by drug), Addison's disease, and concurrent strong CYP3A4 inhibitors with eplerenone/finerenone (raises drug levels and hyperkalemia risk).", "Class monitoring: Serum K+ and SCr/eGFR at baseline, at ~1 week, and periodically after initiation or dose changes — especially with concurrent ACEi/ARB/NSAID use (the 'triple whammy' combination)."], "memberCols": ["Type", "Usual Use", "Notable"], "members": [{"name": "Spironolactone", "a": "Steroidal MRA (nonselective)", "b": "HFrEF, ascites, resistant HTN, hyperaldosteronism", "c": "Binds progesterone/androgen receptors off-target — gynecomastia in ~10%; RALES trial showed HFrEF mortality benefit at low dose"}, {"name": "Eplerenone", "a": "Steroidal MRA (selective)", "b": "HFrEF post-MI, hypertension", "c": "More receptor-selective than spironolactone — minimal endocrine effects, but weaker aldosterone affinity requiring higher doses; many CYP3A4 interactions"}, {"name": "Finerenone", "a": "Nonsteroidal MRA", "b": "Diabetic kidney disease (CKD + T2DM)", "c": "FIDELIO-DKD/FIGARO-DKD trials — better cardiorenal-benefit-to-hyperkalemia ratio than steroidal MRAs; not indicated for HFrEF"}, {"name": "Amiloride", "a": "ENaC blocker", "b": "K+-sparing add-on with thiazides", "c": "Aldosterone-independent — works even without circulating aldosterone; also used off-label for lithium-induced nephrogenic diabetes insipidus"}, {"name": "Triamterene", "a": "ENaC blocker", "b": "K+-sparing add-on with thiazides", "c": "Can precipitate renal calculi, crystalluria, and interstitial nephritis; photosensitizing"}, {"name": "Amiloride/HCTZ (combination)", "a": "ENaC blocker + thiazide", "b": "Hypertension/edema needing K+ protection", "c": "Fixed-dose combination avoids separate K+ supplementation; still requires K+ monitoring if other RAAS drugs are added"}, {"name": "Triamterene/HCTZ (combination)", "a": "ENaC blocker + thiazide", "b": "Hypertension/edema needing K+ protection", "c": "Historically marketed as Dyazide/Triazide-type products; same crystalluria caution as triamterene alone"}, {"name": "Canrenone", "a": "Steroidal MRA (active metabolite of spironolactone)", "b": "Standalone MRA used in Europe", "c": "Demonstrates that much of spironolactone's effect comes from long-half-life active metabolites; not marketed in Canada"}, {"name": "Potassium canrenoate", "a": "Steroidal MRA (IV prodrug of canrenone)", "b": "Acute IV aldosterone blockade (e.g., ascites) in Europe", "c": "Water-soluble IV formulation enabling parenteral MRA therapy; not available in Canada/North America"}, {"name": "Drospirenone", "a": "Steroidal progestin with antimineralocorticoid activity", "b": "Component of certain combined oral contraceptives", "c": "Illustrates off-target MRA activity outside the diuretic class — caution combining with other K+-sparing drugs due to additive hyperkalemia risk"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Spironolactone's antiandrogenic activity carries a theoretical risk of feminizing a male fetus — avoid. Data are limited for eplerenone, finerenone, amiloride, and triamterene; avoid unless the benefit clearly outweighs the risk."}, {"label": "Breastfeeding", "warn": true, "text": "Spironolactone's active metabolite (canrenone) enters breast milk; data are limited for other members. Use the lowest effective dose and monitor the infant, or choose an alternative if possible."}, {"label": "Renal impairment", "warn": true, "text": "Contraindicated in severe renal impairment/anuria because hyperkalemia risk rises sharply; agent-specific eGFR cutoffs apply (e.g., finerenone contraindicated below eGFR 25, amiloride/triamterene generally avoided below eGFR 30)."}, {"label": "Hepatic impairment", "warn": true, "text": "Spironolactone and eplerenone are hepatically metabolized; severe hepatic impairment (especially with ascites) increases the risk of dangerous electrolyte shifts and CNS effects — spironolactone is still first-line for cirrhotic ascites but requires close monitoring."}, {"label": "Elderly", "warn": true, "text": "Higher baseline renal impairment and polypharmacy (ACEi/ARB/NSAID) substantially raise hyperkalemia risk — start at a low dose and monitor potassium more frequently."}, {"label": "Pediatrics", "warn": false, "text": "Spironolactone and amiloride have established pediatric uses (e.g., pediatric heart failure, edema) with weight-based dosing and the same potassium-monitoring principles as adults."}]}, {"key": "phosphate-binders", "topic": "renal", "name": "Phosphate Binders", "pronunciation": "FOSS-fayt BYN-ders", "blurb": "Oral agents taken with meals to bind dietary phosphate in the gut lumen, preventing its absorption and controlling hyperphosphatemia in CKD/dialysis patients.", "general": ["Mechanism: All members act locally in the GI lumen, forming insoluble complexes with dietary phosphate as it's released from food so it passes out in stool instead of being absorbed — the phosphate-lowering effect itself is not systemic. Must be taken WITH meals (chewed, crushed, or as a powder) so the binder is physically present when phosphate is released; taking them apart from food renders them ineffective.", "Class indications: Hyperphosphatemia in CKD stage 4-5 and dialysis (ESRD) patients who cannot control serum phosphate with diet and dialysis alone.", "Class side effects: GI upset (bloating, constipation, or diarrhea depending on agent) is near-universal; calcium-based binders risk hypercalcemia and vascular calcification with chronic use; aluminum-based binders risk aluminum accumulation/toxicity (encephalopathy, osteomalacia) with long-term use; iron-based binders can darken stool and cause iron overload.", "Class contraindications: Bowel obstruction (all members — risk of fecal impaction/bezoar); calcium-based agents avoided in hypercalcemia or adynamic bone disease; aluminum hydroxide avoided for chronic use due to accumulation toxicity; binders can reduce absorption of many co-administered oral drugs, so other medications are generally separated by 1-2 hours.", "Class monitoring: Serum phosphate, calcium, corrected calcium x phosphate product, and PTH (bone-mineral panel) periodically; iron studies with iron-based binders; aluminum levels if aluminum hydroxide is used long-term."], "memberCols": ["Binding Cation", "Ca/Metal Load", "Notable"], "members": [{"name": "Calcium acetate", "a": "Calcium", "b": "Yes — lower elemental Ca per unit binding capacity than carbonate", "c": "PhosLo-type agent; preferred over calcium carbonate when minimizing calcium load, but still risks hypercalcemia"}, {"name": "Calcium carbonate", "a": "Calcium", "b": "Yes — higher elemental Ca load", "c": "Cheapest option; needs an acidic environment for optimal binding, so efficacy drops with concurrent PPI use; risk of milk-alkali-like hypercalcemia"}, {"name": "Sevelamer carbonate", "a": "None (non-absorbed polymer)", "b": "No", "c": "Renvela-type agent — also lowers LDL cholesterol via bile acid binding; carbonate salt replaced the original HCl salt to avoid metabolic acidosis"}, {"name": "Sevelamer hydrochloride", "a": "None (non-absorbed polymer)", "b": "No", "c": "Original formulation (Renagel) — HCl load can worsen metabolic acidosis and cause more GI bloating; largely superseded by the carbonate salt"}, {"name": "Lanthanum carbonate", "a": "Lanthanum (rare earth metal)", "b": "No calcium", "c": "Fosrenol — chewable, potent binder with low pill burden; theoretical concern for GI lanthanum deposition with long-term use, though long-term data are reassuring"}, {"name": "Sucroferric oxyhydroxide", "a": "Iron (ferric)", "b": "No calcium", "c": "Velphoro — chewable, low pill burden; causes dark/discolored stool; minimal systemic iron absorption"}, {"name": "Ferric citrate", "a": "Iron (ferric)", "b": "No calcium", "c": "Auryxia — uniquely increases iron absorption/ferritin/TSAT, which can reduce IV iron and ESA requirements in dialysis patients"}, {"name": "Aluminum hydroxide", "a": "Aluminum", "b": "No calcium", "c": "Historical agent — very potent, reserved for short-term severe hyperphosphatemia due to accumulation toxicity (dialysis dementia, osteomalacia) with chronic use"}, {"name": "Magnesium carbonate/calcium acetate (combination)", "a": "Calcium + magnesium", "b": "Yes, but lower Ca dose than pure calcium binders", "c": "European combination product (e.g., Osvaren) — magnesium co-binding allows a lower calcium load; requires monitoring for hypermagnesemia in advanced CKD"}, {"name": "Colestilan (colestimide)", "a": "None (anion-exchange resin)", "b": "No calcium/metal", "c": "Bile-acid-sequestrant-type binder used in Japan that also modestly lowers LDL cholesterol; not marketed in Canada, included for class completeness"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Calcium-based binders are generally preferred and considered acceptable in pregnancy; non-calcium binders (sevelamer, lanthanum, iron-based) have limited pregnancy data, so calcium acetate/carbonate is favored if a binder is required."}, {"label": "Breastfeeding", "warn": false, "text": "Minimal systemic absorption for most binders makes the class generally considered compatible with breastfeeding; calcium-based agents are preferred given the larger safety database."}, {"label": "Renal impairment", "warn": false, "text": "This class is used specifically because of renal impairment (CKD/dialysis); dosing is titrated to serum phosphate rather than to renal function, since the agents act locally in the gut with no need for systemic dose adjustment."}, {"label": "Hepatic impairment", "warn": false, "text": "No significant hepatic metabolism occurs for this class (local, non-absorbed GI action), so no dose adjustment is required."}, {"label": "Elderly", "warn": true, "text": "Higher risk of constipation-related complications (fecal impaction, bowel obstruction) with calcium-based and aluminum binders — ensure adequate hydration and monitor bowel function."}, {"label": "Pediatrics", "warn": true, "text": "Data are limited; calcium-based binders are used cautiously because of a higher risk of hypercalcemia in growing children, and non-calcium binders are less well studied in this population."}]}, {"key": "ppi", "topic": "gi", "name": "Proton Pump Inhibitors (PPIs)", "pronunciation": "PROH-ton pump in-HIB-ih-ters", "blurb": "First-line acid-suppression therapy for GERD, peptic ulcer disease, and H. pylori eradication via irreversible blockade of the gastric H+/K+-ATPase.", "general": ["Mechanism: Lipophilic weak-base prodrugs that accumulate in the acidic canaliculi of activated parietal cells, where acid converts them to their active sulfenamide form, which covalently and irreversibly binds cysteine residues on the H+/K+-ATPase ('proton pump'). Because binding is irreversible, acid suppression outlasts plasma half-life — new acid secretion resumes only once new pump protein is synthesized (~24-48h), which is why PPIs are dosed once daily before a meal to catch actively cycling pumps.", "Class indications: GERD (including erosive esophagitis), peptic ulcer disease, H. pylori eradication (triple/quadruple therapy), NSAID-induced ulcer prophylaxis, Zollinger-Ellison syndrome, and stress ulcer prophylaxis in critically ill patients.", "Class side effects: Generally well tolerated short-term (headache, diarrhea, nausea); long-term use is linked to hypomagnesemia, vitamin B12 deficiency, increased fracture risk (reduced calcium absorption), and increased risk of C. difficile and other enteric infections from loss of the gastric acid barrier; abrupt discontinuation after prolonged use can cause rebound acid hypersecretion.", "Class contraindications: True contraindications are rare beyond hypersensitivity; caution with concurrent clopidogrel, since omeprazole/esomeprazole can reduce its antiplatelet activation via CYP2C19 inhibition (pantoprazole or rabeprazole preferred if a PPI is needed); avoid indefinite long-term use without periodic reassessment given the risks above.", "Class monitoring: Reassess ongoing need periodically and deprescribe when possible; check magnesium with long-term therapy (especially alongside diuretics or digoxin); watch for red-flag symptoms (dysphagia, weight loss, GI bleeding) that warrant endoscopy rather than continued empiric therapy."], "memberCols": ["CYP Interaction", "Dosing Timing", "Notable"], "members": [{"name": "Omeprazole", "a": "CYP2C19 substrate/inhibitor — significant clopidogrel interaction", "b": "30-60 min before breakfast", "c": "First PPI available and first OTC PPI in Canada; racemic mixture"}, {"name": "Esomeprazole", "a": "CYP2C19 — moderate interaction", "b": "30-60 min before a meal", "c": "S-isomer of omeprazole — slower hepatic clearance gives modestly higher/more consistent acid suppression"}, {"name": "Pantoprazole", "a": "Minimal CYP2C19 interaction (largely non-enzymatic activation)", "b": "Before a meal; IV formulation available", "c": "Preferred when a strong CYP2C19 interaction must be avoided (e.g., with clopidogrel); commonly used IV for stress ulcer prophylaxis in ICU"}, {"name": "Lansoprazole", "a": "CYP2C19/3A4", "b": "Before breakfast", "c": "Available as an orally-disintegrating tablet — useful for swallowing difficulty or feeding-tube administration"}, {"name": "Rabeprazole", "a": "Minimal CYP2C19 dependence (largely non-enzymatic activation)", "b": "Before a meal", "c": "Fastest onset of acid suppression among PPIs due to higher pKa; low interaction potential like pantoprazole"}, {"name": "Dexlansoprazole", "a": "CYP2C19/3A4", "b": "Can be taken without regard to meals", "c": "Dual delayed-release formulation gives two absorption peaks for longer acid control; not currently marketed in Canada"}, {"name": "Omeprazole/sodium bicarbonate", "a": "CYP2C19", "b": "Empty stomach, immediate-release", "c": "Bicarbonate protects omeprazole from acid degradation and speeds absorption, useful for rapid relief and NG-tube delivery; brand (Zegerid) not marketed in Canada"}, {"name": "Ilaprazole", "a": "Predominantly CYP3A4 (less CYP2C19-dependent)", "b": "Before a meal", "c": "Longer half-life than most PPIs; used mainly in Asia (China/Korea) — illustrates regional variation in available PPIs, not marketed in Canada"}, {"name": "Tenatoprazole", "a": "Not fully characterized (investigational)", "b": "Proposed once-daily dosing", "c": "An imidazopyridine (rather than benzimidazole) PPI with a much longer plasma half-life aimed at nocturnal acid breakthrough; never reached broad market"}, {"name": "Vonoprazan", "a": "Not a true PPI — potassium-competitive acid blocker (P-CAB)", "b": "Can be taken without regard to meals", "c": "Reversibly and competitively blocks the K+ site of the H+/K+-ATPase rather than binding it covalently — faster onset and more potent nocturnal control than PPIs; approved in the US (Voquezna) but not yet in Canada"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "PPIs (particularly omeprazole) are considered relatively safe in pregnancy based on extensive safety data and are used when needed for severe GERD."}, {"label": "Breastfeeding", "warn": false, "text": "Considered compatible with breastfeeding, with minimal transfer into breast milk at usual doses."}, {"label": "Renal impairment", "warn": false, "text": "No dose adjustment is generally needed, since PPIs undergo hepatic metabolism with minimal renal elimination."}, {"label": "Hepatic impairment", "warn": true, "text": "Severe hepatic impairment reduces clearance and increases systemic exposure (notably for esomeprazole) — dose reduction and caution are recommended."}, {"label": "Elderly", "warn": true, "text": "Long-term use carries a higher risk of fracture, C. difficile infection, and hypomagnesemia, with possible associations reported for dementia and kidney disease in observational studies — reassess need regularly and use the lowest effective dose and duration."}, {"label": "Pediatrics", "warn": false, "text": "Approved for pediatric GERD in several formulations (e.g., omeprazole, lansoprazole) with weight-based dosing and generally good short-term tolerability."}]}, {"key": "h2ra", "topic": "gi", "name": "H2 Receptor Antagonists (H2RAs)", "pronunciation": "aych-too ree-SEP-ter an-TAG-oh-nists", "blurb": "Reversible histamine H2-receptor blockers on parietal cells that reduce gastric acid secretion — less potent than PPIs and prone to tolerance with continuous use.", "general": ["Mechanism: Competitively and reversibly block histamine H2 receptors on the basolateral membrane of parietal cells, reducing the histamine-mediated (and indirectly gastrin/acetylcholine-potentiated) stimulation of the H+/K+-ATPase. Because blockade is reversible and acts at the receptor rather than the pump, acid suppression is less complete than with PPIs, and tachyphylaxis (tolerance) develops within days of continuous dosing as parietal cells upregulate H2 receptors.", "Class indications: GERD (mild/intermittent), peptic ulcer disease (second-line to PPIs), prevention of NSAID-induced dyspepsia, short-term adjunct to a PPI for nocturnal acid breakthrough, and stress ulcer prophylaxis as a PPI alternative.", "Class side effects: Generally well tolerated; cimetidine notably causes gynecomastia/impotence (antiandrogenic effect) and is a potent CYP450 inhibitor with many drug interactions; CNS effects (confusion, delirium) are more common in the elderly and in renal impairment, especially with cimetidine and (historically) ranitidine.", "Class contraindications: Caution and dose reduction are needed in renal impairment (renally eliminated, risk of CNS toxicity); cimetidine should be avoided with drugs highly dependent on CYP450 metabolism (e.g., warfarin, phenytoin) due to its interaction burden.", "Class monitoring: Renal-function-based dose adjustment; watch for tachyphylaxis with continuous use beyond about 2 weeks; in the elderly, monitor for confusion/delirium, particularly at higher doses or with renal impairment."], "memberCols": ["CYP/Interactions", "Renal Dose Adj?", "Notable"], "members": [{"name": "Cimetidine", "a": "Potent CYP1A2/2C9/2C19/3A4 inhibitor — many interactions (warfarin, phenytoin, theophylline)", "b": "Yes", "c": "First H2RA (prototype); antiandrogenic effects cause gynecomastia/impotence; largely replaced by safer agents"}, {"name": "Ranitidine", "a": "Minimal CYP interaction", "b": "Yes", "c": "Was the most widely used H2RA until global withdrawal (2020) after NDMA (a probable carcinogen) contamination was found — key historical/board fact"}, {"name": "Famotidine", "a": "Minimal CYP interaction — fewest drug interactions in class", "b": "Yes", "c": "Now the most commonly used H2RA post-ranitidine withdrawal; available OTC and Rx in Canada; preferred for patients on multiple interacting medications"}, {"name": "Nizatidine", "a": "Minimal CYP interaction", "b": "Yes", "c": "Unique among H2RAs for near-complete oral bioavailability (~90%); no active metabolites"}, {"name": "Roxatidine", "a": "Minimal CYP interaction", "b": "Yes", "c": "Marketed in Europe/Asia, not North America; prodrug (roxatidine acetate) hydrolyzed to its active form"}, {"name": "Lafutidine", "a": "Minimal CYP interaction; dual mechanism", "b": "Yes", "c": "Adds capsaicin-sensitive afferent neuron stimulation that enhances mucosal defense; marketed only in Japan/India"}, {"name": "Niperotidine", "a": "Minimal CYP interaction", "b": "Yes", "c": "Older H2RA marketed in some European/Latin American markets, largely obscure — included for class completeness"}, {"name": "Ebrotidine", "a": "Minimal CYP interaction", "b": "Yes", "c": "Withdrawn in the 1990s due to serious hepatotoxicity — a cautionary example of idiosyncratic H2RA liver injury"}, {"name": "Loxtidine", "a": "Minimal CYP interaction", "b": "Yes", "c": "Development halted after animal studies showed profound hypergastrinemia leading to gastric carcinoid tumors with very long-term dosing — classic teaching case on excessive/prolonged acid suppression"}, {"name": "Zaltidine", "a": "Minimal CYP interaction", "b": "Yes", "c": "Withdrawn in development due to agranulocytosis/hepatotoxicity signals — another H2RA that failed safety testing"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Considered relatively safe in pregnancy; famotidine has the most reassuring safety data and is generally preferred if an H2RA is needed."}, {"label": "Breastfeeding", "warn": false, "text": "Compatible with breastfeeding at usual doses; famotidine is preferred over cimetidine, which carries more off-target antiandrogenic and CYP-inhibition concerns."}, {"label": "Renal impairment", "warn": true, "text": "All members are substantially renally eliminated and require dose reduction in renal impairment to avoid accumulation and CNS toxicity (confusion, delirium)."}, {"label": "Hepatic impairment", "warn": false, "text": "Minimal hepatic metabolism for most agents means no significant dose adjustment is typically required, since renal function is the main driver of dosing."}, {"label": "Elderly", "warn": true, "text": "Increased risk of confusion/delirium, especially with renal impairment or higher doses — start low and monitor cognition."}, {"label": "Pediatrics", "warn": false, "text": "Famotidine (and historically ranitidine) has established pediatric dosing for GERD; famotidine is now the preferred pediatric H2RA post-ranitidine withdrawal."}]}, {"key": "laxatives", "topic": "gi", "name": "Laxatives", "pronunciation": "LAX-uh-tivs", "blurb": "A family of agents that relieve constipation through different mechanisms — bulk-forming, osmotic, stimulant, softener, and secretagogue.", "general": ["Mechanism: Each subtype acts at a different point in the gut. Bulk-forming agents (psyllium, methylcellulose) absorb water to swell and increase stool mass, stretching the bowel wall to trigger peristalsis. Osmotic agents (PEG, lactulose, magnesium salts) pull water into the lumen to soften and bulk stool. Stimulant laxatives (senna, bisacodyl) directly stimulate enteric nerves to increase colonic motility and secretion. Stool softeners (docusate) are surfactants that let water penetrate hardened stool. Secretagogues (lubiprostone, linaclotide) open intestinal chloride channels or activate guanylate cyclase-C to drive fluid secretion into the lumen; prucalopride instead stimulates colonic motility directly via 5-HT4 receptors.", "Class indications: Acute and chronic constipation, opioid-induced constipation, IBS-C, bowel preparation before procedures, and lactulose specifically for hepatic encephalopathy.", "Class side effects: Bloating, flatulence, and cramping are common across subtypes. Stimulants can cause cramping and, with chronic overuse, melanosis coli. Osmotic saline agents (magnesium, phosphate) can cause electrolyte disturbances. Bulk-forming agents can worsen obstruction if taken without adequate fluid.", "Class contraindications: Bowel obstruction or ileus (any subtype can worsen a mechanical blockage), undiagnosed abdominal pain, and suspected appendicitis.", "Class monitoring: Bowel movement frequency/consistency and symptom relief; electrolytes with chronic osmotic or stimulant use, especially in the elderly or renally impaired; adequate fluid intake with bulk-forming agents."], "memberCols": ["Subtype", "Onset", "Notable"], "members": [{"name": "Psyllium", "a": "Bulk-forming", "b": "12-72 h", "c": "Must be taken with plenty of water — risk of esophageal/bowel obstruction otherwise; first-line for chronic constipation and IBS-C"}, {"name": "Methylcellulose", "a": "Bulk-forming", "b": "12-72 h", "c": "Not fermented by colonic bacteria, so causes less gas/bloating than psyllium"}, {"name": "Polyethylene glycol 3350 (PEG)", "a": "Osmotic", "b": "1-3 days", "c": "Minimal electrolyte disturbance and well tolerated for daily long-term use; first-line osmotic agent"}, {"name": "Lactulose", "a": "Osmotic (non-absorbable sugar)", "b": "24-48 h", "c": "Also first-line for hepatic encephalopathy — traps ammonia as ammonium in the colon; significant flatulence"}, {"name": "Magnesium hydroxide", "a": "Osmotic (saline)", "b": "0.5-6 h", "c": "Fast-acting; avoid in renal impairment due to hypermagnesemia risk"}, {"name": "Sorbitol", "a": "Osmotic", "b": "24-48 h", "c": "Similar efficacy to lactulose, cheaper, but more flatulence"}, {"name": "Senna", "a": "Stimulant (anthraquinone)", "b": "6-12 h", "c": "Activated by colonic bacteria; common combined with a softener for opioid-induced constipation"}, {"name": "Bisacodyl", "a": "Stimulant (diphenylmethane)", "b": "6-12 h PO / 15-60 min PR", "c": "Enteric-coated tablets should not be taken with milk/antacids — premature dissolution causes cramping"}, {"name": "Sodium picosulfate", "a": "Stimulant", "b": "6-12 h", "c": "Common component of bowel-prep kits (e.g., combined with magnesium citrate)"}, {"name": "Docusate sodium", "a": "Stool softener (surfactant)", "b": "24-72 h", "c": "Weak evidence as monotherapy; typically paired with a stimulant rather than used for established constipation"}, {"name": "Glycerin suppository", "a": "Osmotic/lubricant (rectal)", "b": "15-30 min", "c": "Fast rectal option, useful in infants and the elderly"}, {"name": "Lubiprostone", "a": "Secretagogue (ClC-2 chloride channel activator)", "b": "24-48 h", "c": "Approved for chronic idiopathic constipation, opioid-induced constipation, and IBS-C in women"}, {"name": "Linaclotide", "a": "Secretagogue (guanylate cyclase-C agonist)", "b": "~24 h", "c": "Also reduces visceral pain signaling; used for IBS-C and chronic idiopathic constipation; take on an empty stomach"}, {"name": "Prucalopride", "a": "Prokinetic (selective 5-HT4 agonist)", "b": "24-48 h", "c": "Stimulates colonic motility directly rather than via secretion; reserved for chronic idiopathic constipation after other therapies fail"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Bulk-forming agents and PEG/lactulose are first-line and considered safe throughout pregnancy; short courses of stimulant laxatives can be used if needed."}, {"label": "Breastfeeding", "warn": false, "text": "PEG, bulk-forming agents, and docusate are preferred with minimal transfer into milk; senna is also considered compatible."}, {"label": "Renal impairment", "warn": true, "text": "Avoid magnesium- and phosphate-containing osmotic laxatives due to accumulation risk; PEG 3350 is preferred."}, {"label": "Hepatic impairment", "warn": false, "text": "No general restriction; lactulose is in fact first-line therapy for hepatic encephalopathy in this population."}, {"label": "Elderly", "warn": true, "text": "Highest-risk group for chronic constipation; avoid saline/magnesium products with declining renal function, and ensure adequate fluid intake with bulk-forming agents to prevent impaction."}, {"label": "Pediatrics", "warn": true, "text": "PEG 3350 is first-line for pediatric functional constipation; avoid mineral oil due to aspiration risk in infants, and avoid prolonged stimulant use without identifying the underlying cause."}]}, {"key": "antiemetics", "topic": "gi", "name": "Antiemetics", "pronunciation": "an-tie-eh-MET-iks", "blurb": "A family of agents that suppress nausea and vomiting by acting at different points along the vomiting reflex arc — 5-HT3, D2, H1/muscarinic, and NK1 pathways.", "general": ["Mechanism: Antiemetic classes target different inputs to the vomiting reflex. 5-HT3 antagonists block serotonin receptors on vagal afferents in the gut and in the chemoreceptor trigger zone (CTZ) — most useful when serotonin release drives nausea, as in chemotherapy, radiation, or post-op. D2 antagonists block dopamine receptors in the CTZ; some (e.g., metoclopramide) also have peripheral prokinetic activity via GI D2 blockade. Antihistamines/anticholinergics block H1 and muscarinic input from the vestibular system, making them most effective for motion sickness and vertigo. NK1 antagonists block substance P at neurokinin-1 receptors in the CTZ, adding delayed-phase coverage on top of 5-HT3 antagonist/steroid regimens for chemotherapy.", "Class indications: Chemotherapy-induced nausea/vomiting (CINV), post-operative nausea/vomiting (PONV), motion sickness and vertigo, nausea/vomiting of pregnancy, and gastroparesis (prokinetic agents).", "Class side effects: Sedation is common with antihistaminic and D2-blocking agents. D2 antagonists carry extrapyramidal symptoms (EPS)/tardive dyskinesia risk and QT prolongation. 5-HT3 antagonists cause headache, constipation, and dose-dependent QT prolongation. Anticholinergic agents cause dry mouth, blurred vision, and urinary retention.", "Class contraindications: Metoclopramide is contraindicated in Parkinson's disease and GI obstruction (EPS and mechanical risk); domperidone is contraindicated with prolonged QT interval or concurrent QT-prolonging drugs; scopolamine is contraindicated in narrow-angle glaucoma.", "Class monitoring: Symptom control; QT interval with 5-HT3 antagonists, domperidone, or high-dose metoclopramide; EPS with D2 antagonists, especially with prolonged or high-dose use."], "memberCols": ["Subtype", "Best-suited use", "Notable"], "members": [{"name": "Ondansetron", "a": "5-HT3 antagonist", "b": "CINV, PONV, gastroenteritis", "c": "No effect on motion sickness; can prolong QT; available as orally-disintegrating tablet"}, {"name": "Granisetron", "a": "5-HT3 antagonist", "b": "CINV", "c": "Longer half-life than ondansetron; also available as a transdermal patch (Sancuso)"}, {"name": "Dolasetron", "a": "5-HT3 antagonist", "b": "CINV/PONV", "c": "Oral formulation only in Canada — IV use restricted due to QT prolongation risk"}, {"name": "Palonosetron", "a": "5-HT3 antagonist (second-generation)", "b": "Delayed-phase CINV", "c": "Highest 5-HT3 receptor affinity and longest half-life (~40 h) of the class; preferred for delayed CINV"}, {"name": "Metoclopramide", "a": "D2 antagonist + prokinetic", "b": "Gastroparesis, PONV, migraine-associated nausea", "c": "Crosses the blood-brain barrier — EPS/tardive dyskinesia risk; Health Canada limits use to under 12 weeks"}, {"name": "Domperidone", "a": "D2 antagonist (mostly peripheral)", "b": "Gastroparesis, nausea", "c": "Fewer EPS than metoclopramide but carries QT prolongation risk; Health Canada dose/duration restrictions apply"}, {"name": "Prochlorperazine", "a": "D2 antagonist (phenothiazine)", "b": "Nausea/vomiting of various causes, vertigo", "c": "More sedating; EPS risk similar to antipsychotics of the same class"}, {"name": "Dimenhydrinate", "a": "Antihistamine (H1)", "b": "Motion sickness, vertigo, general nausea", "c": "OTC in Canada (Gravol); sedating with anticholinergic effects"}, {"name": "Scopolamine", "a": "Anticholinergic (transdermal patch)", "b": "Motion sickness prevention", "c": "Applied behind the ear at least 4 h before travel; typical anticholinergic side effects"}, {"name": "Doxylamine/pyridoxine", "a": "Antihistamine + vitamin B6 combination", "b": "Nausea/vomiting of pregnancy", "c": "Delayed-release combination (Diclectin) — first-line for NVP in Canada"}, {"name": "Aprepitant", "a": "NK1 antagonist", "b": "Delayed-phase CINV with highly emetogenic regimens", "c": "Added to a 5-HT3 antagonist plus dexamethasone; CYP3A4 inhibitor — interacts with chemo agents and corticosteroids"}, {"name": "Netupitant/palonosetron", "a": "NK1 + 5-HT3 combination (Akynzeo)", "b": "Single-dose coverage of acute and delayed CINV", "c": "Convenient one-capsule regimen given before chemotherapy"}, {"name": "Nabilone", "a": "Cannabinoid", "b": "Refractory CINV when standard agents fail", "c": "Psychoactive effects; controlled substance in Canada"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Doxylamine-pyridoxine and dimenhydrinate are first-line with good safety data; ondansetron has conflicting data on a small increase in fetal cardiac/orofacial risk and is generally reserved for refractory cases; avoid NK1 antagonists and nabilone (insufficient safety data)."}, {"label": "Breastfeeding", "warn": false, "text": "Ondansetron and dimenhydrinate are generally considered compatible; metoclopramide can be used short-term but may increase infant EPS-related risk with prolonged maternal use."}, {"label": "Renal impairment", "warn": true, "text": "Reduce metoclopramide dose (renally eliminated, accumulation risk of EPS); most 5-HT3 antagonists need no adjustment except dolasetron in severe impairment."}, {"label": "Hepatic impairment", "warn": true, "text": "Ondansetron dose is capped in severe hepatic impairment (Child-Pugh C, max 8 mg/day); use metoclopramide and domperidone cautiously."}, {"label": "Elderly", "warn": true, "text": "Increased sensitivity to EPS with metoclopramide/prochlorperazine, higher anticholinergic burden with dimenhydrinate/scopolamine (fall and confusion risk), and higher baseline QT prolongation risk."}, {"label": "Pediatrics", "warn": true, "text": "Ondansetron is widely used and preferred for pediatric gastroenteritis-related vomiting; avoid prochlorperazine and metoclopramide where possible due to higher EPS susceptibility in children."}]}, {"key": "nsaids", "topic": "pain", "name": "NSAIDs (Nonsteroidal Anti-Inflammatory Drugs)", "pronunciation": "EN-sedz (non-ster-OY-dul an-tie-in-FLAM-uh-tor-ee drugz)", "blurb": "Agents that relieve pain, inflammation, and fever by inhibiting cyclooxygenase, with GI, renal, and cardiovascular risks that track COX-1/COX-2 selectivity.", "general": ["Mechanism: NSAIDs inhibit cyclooxygenase (COX-1 and/or COX-2), blocking conversion of arachidonic acid to prostaglandins. COX-1 inhibition reduces protective gastric mucosal prostaglandins (raising GI bleed/ulcer risk) and platelet thromboxane A2 (giving ASA its antiplatelet effect). COX-2 inhibition provides most of the anti-inflammatory/analgesic/antipyretic benefit, but also reduces renal prostaglandins that maintain glomerular perfusion (AKI/fluid retention risk) and vascular prostacyclin, which contributes to increased cardiovascular thrombotic risk — most notable with COX-2-selective agents and high-dose non-selective agents.", "Class indications: Mild-to-moderate pain, inflammatory conditions (osteoarthritis, rheumatoid arthritis, gout flares), fever, dysmenorrhea; low-dose ASA is used separately for cardiovascular/antiplatelet prophylaxis.", "Class side effects: GI ulceration and bleeding, renal impairment/fluid retention/hypertension, increased cardiovascular thrombotic risk (MI/stroke, especially with COX-2-selective and high-dose non-selective agents), and platelet inhibition/bleeding risk with non-selective agents.", "Class contraindications: Active GI bleed or peptic ulcer disease, severe renal impairment, severe heart failure, third-trimester pregnancy, ASA-exacerbated respiratory disease, and concurrent use with other NSAIDs or anticoagulants.", "Class monitoring: Blood pressure, renal function (SCr) with chronic use or in elderly/CKD patients, GI symptoms or occult bleeding, and CBC with long-term therapy."], "memberCols": ["COX selectivity", "Dosing", "Notable"], "members": [{"name": "Ibuprofen", "a": "Non-selective", "b": "TID-QID", "c": "OTC first-line for mild-moderate pain/fever; short half-life"}, {"name": "Naproxen", "a": "Non-selective", "b": "BID", "c": "Longer half-life allows less frequent dosing; possibly the lowest relative CV risk among non-selective NSAIDs"}, {"name": "Acetylsalicylic acid (ASA)", "a": "Non-selective (irreversible COX inhibition)", "b": "Variable (analgesic vs. low-dose antiplatelet)", "c": "Irreversible platelet inhibition lasts the life of the platelet (~7-10 days); avoid in children/teens with viral illness (Reye's syndrome)"}, {"name": "Diclofenac", "a": "Non-selective (COX-2 preferential)", "b": "BID-TID oral, or topical", "c": "Topical gel gives lower systemic absorption/GI risk; oral form has relatively higher CV risk among non-selective NSAIDs"}, {"name": "Ketorolac", "a": "Non-selective", "b": "Short-term only (max 5 days combined routes)", "c": "Potent parenteral/oral analgesic for acute post-op pain; high GI bleed risk limits duration"}, {"name": "Indomethacin", "a": "Non-selective", "b": "BID-TID", "c": "Used for acute gout flares and to close a patent ductus arteriosus in neonates; more CNS side effects (headache, dizziness)"}, {"name": "Meloxicam", "a": "COX-2 preferential", "b": "Once daily", "c": "Once-daily convenience for OA/RA; lower GI risk than non-selective agents at low doses, though not fully COX-2 selective"}, {"name": "Celecoxib", "a": "COX-2 selective", "b": "OD-BID", "c": "Lower GI ulcer/bleed risk and no antiplatelet effect; contains a sulfonamide moiety (caution with sulfa allergy); CV risk still present"}, {"name": "Etodolac", "a": "COX-2 preferential", "b": "BID", "c": "Alternative for patients needing moderate GI sparing without full COX-2 selectivity"}, {"name": "Piroxicam", "a": "Non-selective", "b": "Once daily", "c": "Very long half-life (~50 h) — higher accumulation and GI risk with chronic use; less preferred in the elderly"}, {"name": "Ketoprofen", "a": "Non-selective", "b": "TID-QID oral, or topical", "c": "Also available topically; overall profile similar to ibuprofen"}, {"name": "Nabumetone", "a": "Non-selective (prodrug)", "b": "OD-BID", "c": "Prodrug activated in the liver; may carry somewhat lower GI risk than other non-selective agents"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Avoid from around 20 weeks and especially in the third trimester — risk of premature ductus arteriosus closure and oligohydramnios; low-dose ASA for pre-eclampsia prophylaxis is a specialist-guided exception."}, {"label": "Breastfeeding", "warn": false, "text": "Ibuprofen is preferred due to minimal transfer into milk and a short half-life; considered compatible at usual doses."}, {"label": "Renal impairment", "warn": true, "text": "Use with extreme caution or avoid — reduced renal prostaglandin-mediated perfusion raises AKI risk, especially combined with ACEi/ARB and diuretics (\"triple whammy\"); avoid if eGFR is under 30."}, {"label": "Hepatic impairment", "warn": true, "text": "Avoid in severe hepatic impairment or cirrhosis with ascites — worsens fluid retention, renal function, and bleeding risk from impaired clotting factor synthesis."}, {"label": "Elderly", "warn": true, "text": "Highest-risk group for GI bleed, AKI, and cardiovascular events; use the lowest effective dose for the shortest duration and consider a PPI if an NSAID is necessary."}, {"label": "Pediatrics", "warn": true, "text": "Ibuprofen is approved from 6 months of age; avoid ASA in children and teens under 18 with viral illness due to Reye's syndrome risk; use of other agents like ketorolac is generally limited."}]}, {"key": "opioids", "topic": "pain", "name": "Opioids", "pronunciation": "OH-pee-oidz", "blurb": "Mu-receptor agonists used for moderate-to-severe pain, with a shared risk of respiratory depression and constipation but important differences in potency and metabolism relevant to equianalgesic dosing.", "general": ["Mechanism: Opioids act primarily as agonists at mu-opioid receptors in the CNS and periphery, mimicking endogenous endorphins to inhibit ascending pain signal transmission and activate descending inhibitory pathways. Mu-receptor activation in the brainstem respiratory centers causes dose-dependent respiratory depression, and activation in the gut myenteric plexus slows motility — unlike most opioid side effects, tolerance does NOT develop to constipation, so a prophylactic laxative is needed for ongoing use.", "Class indications: Moderate-to-severe acute pain, cancer pain, selected chronic non-cancer pain after risk-benefit assessment, cough suppression (codeine), and opioid use disorder maintenance (methadone/buprenorphine).", "Class side effects: Respiratory depression (dose-limiting, worsened by other CNS depressants), constipation (no tolerance develops), sedation/euphoria, nausea/vomiting (tolerance develops over days), pruritus, miosis, and tolerance/physical dependence/withdrawal with regular use.", "Class contraindications: Significant respiratory depression or severe asthma exacerbation, paralytic ileus/bowel obstruction, and concurrent MAOI use (particularly with meperidine or tramadol — serotonin syndrome/CNS toxicity risk).", "Class monitoring: Pain scores, sedation level (a better early predictor of respiratory depression than respiratory rate alone), respiratory rate/oxygen saturation, bowel function with a prophylactic laxative, and signs of misuse or opioid use disorder with chronic therapy; ensure naloxone access and counselling."], "memberCols": ["Relative potency (equianalgesic reference: oral morphine)", "Duration/formulation", "Notable"], "members": [{"name": "Morphine", "a": "Reference standard (1x)", "b": "IR q4h, or extended-release BID/OD", "c": "Active metabolite (morphine-6-glucuronide) accumulates in renal impairment — avoid or reduce dose"}, {"name": "Hydromorphone", "a": "~5x oral morphine", "b": "IR q4h, ER OD", "c": "Preferred alternative in renal impairment, though caution is still needed with prolonged use"}, {"name": "Oxycodone", "a": "~1.5-2x oral morphine", "b": "IR q4-6h, controlled-release q12h", "c": "High misuse/diversion potential; tamper-resistant CR formulation available in Canada"}, {"name": "Codeine", "a": "Prodrug — CYP2D6 converts only ~10% to morphine", "b": "q4-6h", "c": "Highly variable efficacy due to CYP2D6 polymorphism; contraindicated under age 12 and in breastfeeding (ultrarapid metabolizer neonatal toxicity risk)"}, {"name": "Fentanyl", "a": "~100x parenteral morphine", "b": "Transdermal patch q72h, or IV/SL for breakthrough", "c": "Transdermal use restricted to opioid-tolerant patients; highly lipophilic — fast IV onset but slow patch onset/offset (12-24 h to steady state)"}, {"name": "Methadone", "a": "Non-linear — potency ratio increases at higher morphine doses (requires specialist conversion)", "b": "Long, unpredictable half-life (8-59 h)", "c": "Also has NMDA-antagonist activity (may help neuropathic pain); QT prolongation risk; used in OUD maintenance"}, {"name": "Tramadol", "a": "Weak mu-agonist (~0.1x morphine) plus SNRI activity", "b": "IR q4-6h, ER OD", "c": "Lowers seizure threshold; serotonin syndrome risk with other serotonergic drugs; active metabolite is CYP2D6-dependent"}, {"name": "Tapentadol", "a": "Mu-agonist plus norepinephrine reuptake inhibition", "b": "ER BID or IR q4-6h", "c": "Less serotonergic activity than tramadol (lower serotonin syndrome risk) and better GI tolerability than pure mu agonists"}, {"name": "Meperidine", "a": "~0.1x oral morphine", "b": "q3-4h (short duration)", "c": "Normeperidine metabolite accumulates in renal impairment causing CNS excitotoxicity/seizures; rarely used now, avoid with MAOIs"}, {"name": "Hydrocodone", "a": "~1x oral morphine (in combination products)", "b": "q4-6h", "c": "Usually combined with acetaminophen in Canada — watch total daily acetaminophen dose"}, {"name": "Buprenorphine", "a": "Partial mu-agonist with a ceiling on respiratory depression", "b": "Sublingual (Suboxone) or transdermal patch q7d", "c": "High mu-receptor affinity can precipitate withdrawal if started too soon after a full agonist; used in both OUD treatment and pain management"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Chronic use is associated with neonatal opioid withdrawal syndrome; avoid abrupt discontinuation (taper instead to prevent fetal distress); methadone or buprenorphine is preferred maintenance therapy for opioid use disorder in pregnancy."}, {"label": "Breastfeeding", "warn": true, "text": "Codeine and tramadol are contraindicated due to the risk of fatal infant morphine toxicity in CYP2D6 ultrarapid metabolizer mothers; morphine or hydromorphone at the lowest effective dose with infant monitoring is preferred."}, {"label": "Renal impairment", "warn": true, "text": "Avoid morphine (active metabolite accumulation) and meperidine (normeperidine toxicity); fentanyl and hydromorphone are relatively preferred with dose caution."}, {"label": "Hepatic impairment", "warn": true, "text": "Reduce doses or extend intervals for most agents (hepatic metabolism); avoid meperidine and codeine due to unpredictable conversion, and use tramadol/methadone cautiously."}, {"label": "Elderly", "warn": true, "text": "Increased sensitivity to sedation, respiratory depression, and falls — start low and go slow; avoid meperidine and long-acting agents like methadone where possible."}, {"label": "Pediatrics", "warn": true, "text": "Codeine and tramadol are contraindicated under age 12 due to unpredictable CYP2D6 metabolism causing fatal respiratory depression in ultrarapid metabolizers; weight-based dosing is required for all agents."}]}, {"key": "gabapentinoids", "topic": "pain", "name": "Gabapentinoids", "pronunciation": "GAB-a-PEN-tin-oyds", "blurb": "Alpha-2-delta calcium channel ligands used for neuropathic pain, adjunct seizure control, and (off-label) anxiety.", "general": ["Mechanism: Bind the alpha-2-delta-1 subunit of voltage-gated calcium channels on presynaptic neurons, reducing calcium influx and downstream release of excitatory neurotransmitters (glutamate, substance P, norepinephrine). This dampens hyperexcitable pain signaling without acting on GABA receptors despite the name.", "Class indications: Neuropathic pain (diabetic peripheral neuropathy, postherpetic neuralgia, central neuropathic pain), adjunctive therapy for partial seizures, fibromyalgia (pregabalin), off-label for anxiety and alcohol withdrawal.", "Class side effects: Sedation, dizziness, peripheral edema, weight gain, ataxia; dose-related and usually improve with slow titration.", "Class contraindications: No absolute contraindications, but caution with concurrent CNS depressants (opioids, benzodiazepines, alcohol) due to additive sedation and respiratory depression risk; known hypersensitivity.", "Class monitoring: Monitor for sedation/dizziness (especially at initiation and dose increases), signs of misuse or dependence, renal function (both are renally cleared and need dose adjustment), and mood/suicidal ideation."], "memberCols": ["Bioavailability/PK", "Renal Dosing?", "Notable"], "members": [{"name": "Gabapentin capsules/tablets (Neurontin, generic)", "a": "Saturable absorption — decreases as dose rises (~60% at low dose, <35% at high dose)", "b": "Yes — major renal adjustment required", "c": "TID dosing due to short half-life and saturable absorption; cheapest option, first-line in most Canadian formularies"}, {"name": "Gabapentin oral solution", "a": "Same saturable absorption as solid dosage forms", "b": "Yes — major renal adjustment required", "c": "Used for pediatric patients or adults with swallowing difficulty; concentration-based dosing increases error risk — verify mg vs mL carefully"}, {"name": "Gabapentin (multiple generic manufacturers)", "a": "Bioequivalent to brand at approved doses", "b": "Yes — major renal adjustment required", "c": "Many interchangeable generics on Canadian formularies; useful counselling point since patients may see different pill shapes/colours on refill"}, {"name": "Pregabalin capsules (Lyrica, generic)", "a": "Linear, ~90% bioavailability (dose-independent, unlike gabapentin)", "b": "Yes — renal adjustment required", "c": "BID-TID dosing; faster titration than gabapentin; Schedule IV controlled substance in Canada due to misuse/diversion potential; approved for fibromyalgia and GAD"}, {"name": "Pregabalin oral solution", "a": "Linear absorption, same as capsules", "b": "Yes — renal adjustment required", "c": "Alternative for patients unable to swallow capsules; same controlled-substance status as capsule form"}, {"name": "Pregabalin (generic, since ~2019 in Canada)", "a": "Bioequivalent to Lyrica", "b": "Yes — renal adjustment required", "c": "Now much less costly than brand Lyrica; remains a targeted controlled substance requiring prescription monitoring in most provinces"}, {"name": "Gabapentin enacarbil (Horizant)", "a": "Higher, more consistent absorption than gabapentin — actively transported, not saturable", "b": "Yes — renal adjustment required", "c": "Prodrug of gabapentin; once-daily extended-release; approved mainly for restless legs syndrome; limited Canadian availability/coverage"}, {"name": "Mirogabalin (Tarlige)", "a": "High, consistent absorption; more selective alpha-2-delta-1 binding", "b": "Yes — renal adjustment required", "c": "Newer-generation gabapentinoid used in Japan/South Korea for neuropathic pain; not currently marketed in Canada — relevant mainly as an emerging-therapy exam concept"}, {"name": "Gabapentin — off-label alcohol withdrawal/anxiety use", "a": "Same saturable PK as standard gabapentin", "b": "Yes — major renal adjustment required", "c": "Increasingly used off-label as a non-benzodiazepine option for mild alcohol withdrawal and anxiety, capitalizing on its abuse-deterrent profile relative to pregabalin"}, {"name": "Pregabalin — fibromyalgia-labelled use", "a": "Linear PK, same as standard pregabalin", "b": "Yes — renal adjustment required", "c": "One of only a few agents with a Health Canada-approved fibromyalgia indication; typically dosed BID for this indication"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Limited human data; animal studies show developmental toxicity at high doses. Use only if benefit outweighs risk — reserve for cases where alternative analgesics have failed."}, {"label": "Breastfeeding", "warn": true, "text": "Both drugs pass into breast milk in small amounts. Monitor breastfed infant for sedation and poor feeding; considered compatible with caution by most references."}, {"label": "Renal impairment", "warn": true, "text": "Both gabapentin and pregabalin are renally eliminated essentially unchanged — dose must be reduced based on creatinine clearance, and accumulation causes marked sedation, myoclonus, and confusion in renal failure."}, {"label": "Hepatic impairment", "warn": false, "text": "Not hepatically metabolized, so no dose adjustment is needed for liver disease specifically — renal function remains the key determinant of dosing."}, {"label": "Elderly", "warn": true, "text": "Increased sensitivity to sedation, dizziness, and falls risk; age-related decline in renal function often necessitates lower starting doses and slower titration."}, {"label": "Pediatrics", "warn": true, "text": "Gabapentin is approved for adjunctive seizure therapy in children ≥3 years; pregabalin pediatric neuropathic pain data is more limited. Both require weight-based dosing and monitoring for behavioural side effects."}]}, {"key": "dmards", "topic": "pain", "name": "DMARDs (Disease-Modifying Antirheumatic Drugs)", "pronunciation": "DEE-mards (DMARDs); DIH-zeez-mah-DIF-eye-ing an-tie-roo-MAT-ik drugz", "blurb": "Conventional, biologic, and targeted synthetic agents that slow or halt joint damage in rheumatoid arthritis and other autoimmune conditions, unlike NSAIDs which only control symptoms.", "general": ["Mechanism: Conventional DMARDs (methotrexate, sulfasalazine, hydroxychloroquine, leflunomide) broadly dampen immune/inflammatory pathways (e.g., methotrexate inhibits dihydrofolate reductase and increases anti-inflammatory adenosine; leflunomide inhibits pyrimidine synthesis in activated lymphocytes). Biologics target a specific inflammatory mediator or cell (e.g., adalimumab/etanercept/infliximab neutralize TNF-alpha; rituximab depletes CD20+ B cells). JAK inhibitors (tofacitinib, baricitinib, upadacitinib) block intracellular Janus kinase signaling downstream of multiple cytokine receptors. All aim to halt the immune-driven synovial inflammation that erodes cartilage and bone over time.", "Class indications: Rheumatoid arthritis, psoriatic arthritis, ankylosing spondylitis, inflammatory bowel disease (some agents), and other autoimmune conditions where early treatment prevents irreversible joint damage.", "Class side effects: Broad immunosuppression with increased infection risk across all agents; conventional DMARDs add hepatotoxicity/myelosuppression (methotrexate), GI upset (sulfasalazine), retinopathy (hydroxychloroquine); biologics add infusion/injection site reactions and TB/hepatitis B reactivation risk; JAK inhibitors carry a boxed warning for VTE, MACE, and malignancy.", "Class contraindications: Active serious infection (all agents), untreated latent TB or active TB (biologics, JAK inhibitors), pregnancy (methotrexate and leflunomide are teratogenic), significant hepatic impairment (methotrexate, leflunomide), live vaccines during therapy (biologics, JAK inhibitors).", "Class monitoring: Baseline TB screening (biologics, JAK inhibitors) and hepatitis B/C serology before starting; CBC, liver enzymes, and renal function periodically for conventional DMARDs; lipid panel and VTE risk assessment for JAK inhibitors; annual ophthalmologic exam for hydroxychloroquine; ongoing vigilance for signs of infection with all agents."], "memberCols": ["Type", "Monitoring", "Notable"], "members": [{"name": "Methotrexate", "a": "Conventional (anchor drug)", "b": "CBC, LFTs, SCr q1-3 months; folic acid supplementation required", "c": "First-line for RA; weekly (not daily!) dosing — dosing errors can be fatal; teratogenic, needs contraception"}, {"name": "Sulfasalazine", "a": "Conventional", "b": "CBC, LFTs periodically; G6PD status if applicable", "c": "Sulfa allergy cross-reactivity; safest conventional DMARD in pregnancy"}, {"name": "Hydroxychloroquine", "a": "Conventional", "b": "Baseline and annual ophthalmologic exam (retinopathy risk)", "c": "Mildest conventional DMARD; often used in combination or mild disease; also used in lupus"}, {"name": "Leflunomide", "a": "Conventional", "b": "CBC, LFTs monthly initially", "c": "Very long half-life (active metabolite persists months) — requires cholestyramine washout before pregnancy or if toxicity occurs"}, {"name": "Adalimumab (Humira)", "a": "Biologic — TNF inhibitor", "b": "TB/hepatitis B screen before starting; monitor for infection", "c": "Subcutaneous self-injection; many biosimilars now available in Canada"}, {"name": "Etanercept (Enbrel)", "a": "Biologic — TNF inhibitor (fusion protein)", "b": "TB/hepatitis B screen before starting; monitor for infection", "c": "Weekly subcutaneous injection; shorter half-life than monoclonal TNF inhibitors"}, {"name": "Infliximab (Remicade)", "a": "Biologic — TNF inhibitor (chimeric monoclonal antibody)", "b": "TB/hepatitis B screen; monitor infusion reactions and anti-drug antibodies", "c": "IV infusion given with methotrexate to reduce immunogenicity"}, {"name": "Rituximab", "a": "Biologic — anti-CD20 (B-cell depletion)", "b": "Immunoglobulin levels, hepatitis B screen; monitor for infusion reactions", "c": "Used in RA refractory to TNF inhibitors; also an oncology/lymphoma agent"}, {"name": "Tocilizumab", "a": "Biologic — IL-6 receptor inhibitor", "b": "LFTs, lipid panel, neutrophil/platelet counts", "c": "Can mask signs of infection (blunts CRP/fever response) — high index of suspicion needed"}, {"name": "Abatacept", "a": "Biologic — T-cell costimulation blocker", "b": "TB/hepatitis B screen; monitor for infection", "c": "Available as IV or subcutaneous; alternative for TNF-inhibitor failures"}, {"name": "Tofacitinib (Xeljanz)", "a": "Targeted synthetic — JAK 1/3 inhibitor (oral)", "b": "CBC, lipids, LFTs; VTE and cardiovascular risk assessment", "c": "Oral option (no injections); boxed warning for VTE, MACE, malignancy, especially age 50+ with CV risk factors"}, {"name": "Baricitinib (Olumiant)", "a": "Targeted synthetic — JAK 1/2 inhibitor (oral)", "b": "CBC, lipids, renal function; VTE risk assessment", "c": "Once-daily oral dosing; renal dose adjustment required"}, {"name": "Upadacitinib (Rinvoq)", "a": "Targeted synthetic — JAK1-selective inhibitor (oral)", "b": "CBC, lipids, LFTs; VTE and malignancy risk assessment", "c": "More JAK1-selective; also approved for psoriatic arthritis, ankylosing spondylitis, and atopic dermatitis"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Methotrexate and leflunomide are contraindicated (teratogenic) — require effective contraception and washout before conception. Sulfasalazine (with folic acid) and hydroxychloroquine are considered the safest DMARDs to continue in pregnancy. Most biologics can often be continued into pregnancy under specialist guidance but are typically held before the third trimester; JAK inhibitors are generally avoided."}, {"label": "Breastfeeding", "warn": true, "text": "Methotrexate and leflunomide contraindicated. Hydroxychloroquine and sulfasalazine are generally considered compatible. Data are limited for biologics and JAK inhibitors — decisions individualized with rheumatology."}, {"label": "Renal impairment", "warn": true, "text": "Methotrexate is renally cleared and accumulates dangerously in renal impairment, raising toxicity risk — dose reduction or avoidance is needed. Baricitinib also requires renal dose adjustment."}, {"label": "Hepatic impairment", "warn": true, "text": "Methotrexate and leflunomide carry hepatotoxicity risk and are contraindicated or used cautiously with pre-existing liver disease or significant alcohol use; regular LFT monitoring is essential for these agents."}, {"label": "Elderly", "warn": true, "text": "Increased infection risk with all immunosuppressants; JAK inhibitors carry a boxed warning for higher VTE, cardiovascular event, and malignancy risk specifically in patients age 50 and older with cardiovascular risk factors."}, {"label": "Pediatrics", "warn": false, "text": "Methotrexate and several biologics (e.g., etanercept, adalimumab) are approved for juvenile idiopathic arthritis with weight-based dosing; use is specialist-directed with close growth and infection monitoring."}]}, {"key": "combined-hormonal-contraceptives", "topic": "womens", "name": "Combined Hormonal Contraceptives (CHCs)", "pronunciation": "kom-BINED hor-MOH-nal KON-tra-SEP-tivz", "blurb": "Estrogen-progestin combinations (pill, patch, or ring) that prevent pregnancy primarily by suppressing ovulation.", "general": ["Mechanism: The estrogen component (usually ethinyl estradiol) suppresses FSH to prevent follicular development, while the progestin component suppresses the LH surge to block ovulation; progestin also thickens cervical mucus and thins the endometrium as backup mechanisms. The estrogen additionally stabilizes the endometrium to give predictable withdrawal bleeding.", "Class indications: Contraception, cycle regulation, dysmenorrhea, heavy menstrual bleeding, acne/hirsutism (antiandrogenic progestins), endometriosis-related pain management.", "Class side effects: Nausea, breast tenderness, breakthrough bleeding (especially first 3 months), headache, mood changes; small increased risk of venous thromboembolism (VTE) and, in smokers over 35, arterial events (MI, stroke).", "Class contraindications: Per the WHO/CDC Medical Eligibility Criteria — smoking plus age >35, history of VTE/thrombophilia, migraine with aura, uncontrolled hypertension, current breast cancer, active liver disease, <21 days postpartum, and major surgery with prolonged immobilization.", "Class monitoring: Baseline and periodic blood pressure checks; screen for new headache-with-aura, leg swelling/pain, chest pain, or visual changes (VTE/stroke red flags) at each visit or refill; review smoking status and cardiovascular risk factors, especially approaching age 35."], "memberCols": ["Progestin/Type", "Estrogen Dose", "Notable"], "members": [{"name": "Alesse (levonorgestrel/EE)", "a": "Levonorgestrel — second-generation", "b": "20 mcg ethinyl estradiol", "c": "Lower-dose pill; good first-line option; less breakthrough bleeding tolerance"}, {"name": "Marvelon / Apri (desogestrel/EE)", "a": "Desogestrel — third-generation", "b": "30 mcg ethinyl estradiol", "c": "Third-generation progestins carry a slightly higher VTE risk than levonorgestrel-containing pills"}, {"name": "Yasmin (drospirenone/EE)", "a": "Drospirenone — antiandrogenic, spironolactone-like", "b": "30 mcg ethinyl estradiol", "c": "Mild antimineralocorticoid effect — monitor potassium if combined with ACEi/ARB/K-sparing diuretics; helps acne/hirsutism"}, {"name": "Yaz (drospirenone/EE)", "a": "Drospirenone", "b": "20 mcg ethinyl estradiol", "c": "24 active/4 placebo regimen (shortened hormone-free interval); approved for PMDD and acne"}, {"name": "Diane-35 (cyproterone/EE)", "a": "Cyproterone acetate — strongly antiandrogenic", "b": "35 mcg ethinyl estradiol", "c": "Indicated specifically for severe acne/hirsutism, not marketed as a primary contraceptive; higher VTE risk than levonorgestrel pills"}, {"name": "Triquilar / Triphasil (levonorgestrel/EE)", "a": "Levonorgestrel — triphasic", "b": "30-40 mcg ethinyl estradiol (varies by phase)", "c": "Triphasic dosing mimics natural hormone fluctuation; must be taken in correct pill order"}, {"name": "Min-Ovral (levonorgestrel/EE)", "a": "Levonorgestrel — second-generation", "b": "30 mcg ethinyl estradiol", "c": "Common, inexpensive monophasic option; also used off-label for emergency contraception (Yuzpe method) historically"}, {"name": "Loestrin 1.5/30 (norethindrone acetate/EE)", "a": "Norethindrone acetate", "b": "30 mcg ethinyl estradiol", "c": "Estrogen-dominant profile; sometimes preferred for breakthrough bleeding issues on other pills"}, {"name": "Zovia / Demulen (ethynodiol diacetate/EE)", "a": "Ethynodiol diacetate", "b": "35-50 mcg ethinyl estradiol", "c": "Older-generation progestin, less commonly prescribed now"}, {"name": "Evra patch (norelgestromin/EE)", "a": "Norelgestromin (active metabolite of norgestimate) — transdermal", "b": "~20 mcg/day ethinyl estradiol delivered transdermally", "c": "Weekly patch x3 weeks then patch-free week; may be less effective in patients >90 kg; avoids first-pass GI absorption issues but still systemic estrogen exposure"}, {"name": "NuvaRing (etonogestrel/EE)", "a": "Etonogestrel — vaginal ring", "b": "~15 mcg/day ethinyl estradiol released locally", "c": "Self-inserted, worn 3 weeks then removed for 1 week; lower peak estrogen levels than oral pills due to steady-state vaginal delivery"}, {"name": "Annovera ring (segesterone/EE)", "a": "Segesterone acetate — vaginal ring", "b": "~13 mcg/day ethinyl estradiol", "c": "Reusable for up to 1 year (13 cycles); limited Canadian availability"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Contraindicated — not used once pregnancy is confirmed (no therapeutic role and no benefit); rule out pregnancy before initiation if there is any uncertainty."}, {"label": "Breastfeeding", "warn": true, "text": "Avoid until breastfeeding is well established and at least 4-6 weeks postpartum (WHO); estrogen can reduce milk supply. Progestin-only methods are preferred while breastfeeding."}, {"label": "Renal impairment", "warn": false, "text": "No specific dose adjustment required; hepatic metabolism predominates over renal clearance for these hormones."}, {"label": "Hepatic impairment", "warn": true, "text": "Contraindicated in active liver disease, liver tumours, or severe cirrhosis — estrogens are hepatically metabolized and can worsen cholestasis or tumour growth."}, {"label": "Elderly", "warn": false, "text": "Not a relevant population for contraception — CHCs are generally not used past menopause; cardiovascular risk (which increases with age) is the more relevant consideration as women approach perimenopause."}, {"label": "Pediatrics", "warn": false, "text": "Can be used in adolescents once regular ovulatory cycles are established, typically at least 2 years post-menarche; also used for non-contraceptive indications like acne or heavy bleeding, with attention to bone density with prolonged use."}]}, {"key": "hrt-progestin-only", "topic": "womens", "name": "Hormone Replacement Therapy (HRT) & Progestin-Only Options", "pronunciation": "HOR-mohn ree-PLAYS-ment THAIR-uh-pee; PROH-jes-tin-OHN-lee", "blurb": "Estrogen (± progestin) therapy for menopausal symptom relief, and progestin-only agents used for contraception or endometrial protection without estrogen.", "general": ["Mechanism: Menopausal HRT replaces declining endogenous estrogen to relieve vasomotor symptoms (hot flashes, night sweats) and genitourinary atrophy by restoring estrogen receptor activation in the hypothalamus and urogenital tissue; a progestin is added in women with an intact uterus to oppose estrogen's proliferative effect on the endometrium and prevent hyperplasia/cancer. Progestin-only options (POPs, injectables, IUDs, implants) work mainly by thickening cervical mucus and, depending on the agent/dose, may also suppress ovulation — they avoid estrogen-related risks entirely.", "Class indications: HRT — moderate-to-severe vasomotor symptoms, genitourinary syndrome of menopause, prevention of osteoporosis in select patients. Progestin-only — contraception (especially when estrogen is contraindicated: breastfeeding, VTE history, migraine with aura, smokers >35), endometrial protection alongside unopposed estrogen therapy, heavy menstrual bleeding (levonorgestrel IUD).", "Class side effects: HRT — breast tenderness, bloating, breakthrough bleeding, small increased risk of VTE (oral more than transdermal) and, with combined long-term use, breast cancer. Progestin-only — irregular/unpredictable bleeding or amenorrhea, weight gain, mood changes, acne; injectable (medroxyprogesterone) causes reversible bone mineral density loss.", "Class contraindications: Estrogen-containing HRT — history of breast or endometrial cancer, active VTE or history of VTE, active liver disease, undiagnosed vaginal bleeding, known thrombophilia. Progestin-only — current breast cancer is a contraindication; otherwise a much safer option in patients with estrogen contraindications.", "Class monitoring: Annual reassessment of ongoing need for HRT (lowest effective dose, shortest duration consistent with goals); mammography per screening guidelines; monitor for abnormal bleeding (requires endometrial evaluation); bone density monitoring with long-term medroxyprogesterone injection use."], "memberCols": ["Type/Route", "Estrogen Component?", "Notable"], "members": [{"name": "Estrace / generic estradiol (oral)", "a": "Systemic HRT — oral estrogen", "b": "Yes — estradiol", "c": "Must add a progestin if uterus intact; oral route has higher VTE risk than transdermal due to first-pass hepatic effect on clotting factors"}, {"name": "Estradot / Climara (estradiol patch)", "a": "Systemic HRT — transdermal estrogen", "b": "Yes — estradiol", "c": "Transdermal route bypasses first-pass metabolism — lower VTE risk than oral; preferred in women with cardiovascular risk factors"}, {"name": "Divigel / EstroGel (estradiol gel)", "a": "Systemic HRT — transdermal estrogen", "b": "Yes — estradiol", "c": "Flexible dosing; transdermal VTE-risk profile similar to patch; avoid transferring gel to others via skin contact"}, {"name": "Premarin (conjugated equine estrogens)", "a": "Systemic HRT — oral estrogen", "b": "Yes — conjugated equine estrogens", "c": "Studied in the WHI trial; oral route, same VTE considerations as other oral estrogens"}, {"name": "Vagifem / Premarin vaginal cream (local estrogen)", "a": "Local HRT — vaginal estrogen", "b": "Yes, but minimal systemic absorption", "c": "First-line for genitourinary syndrome of menopause (vaginal dryness/atrophy) without need for progestin, even with intact uterus, due to negligible systemic absorption"}, {"name": "Prometrium (micronized progesterone, oral)", "a": "Progestin component for combined HRT", "b": "No — progestin only", "c": "Bioidentical micronized progesterone; taken at bedtime due to sedating effect; preferred for endometrial protection with fewer adverse metabolic effects than synthetic progestins"}, {"name": "Provera (medroxyprogesterone acetate, oral)", "a": "Progestin component for combined HRT / progestin-only therapy", "b": "No — progestin only", "c": "Synthetic progestin; used cyclically or continuously with estrogen, or alone for endometrial hyperplasia/abnormal bleeding"}, {"name": "Depo-Provera (medroxyprogesterone injection)", "a": "Progestin-only contraceptive — IM/SC injection", "b": "No — progestin only", "c": "Given every 12-13 weeks; causes reversible bone mineral density loss with prolonged use — not first-line for adolescents needing bone accrual; delayed return to fertility after stopping"}, {"name": "Micronor / Norlutin (norethindrone, oral POP)", "a": "Progestin-only pill (POP)", "b": "No — progestin only", "c": "Must be taken at the same time every day (±3 hours) — narrower window than combined pills because it relies more on cervical mucus effect; safe while breastfeeding"}, {"name": "Slynd (drospirenone POP)", "a": "Progestin-only pill (POP)", "b": "No — progestin only", "c": "Newer POP with a 24-hour missed-dose window (more forgiving than traditional POPs) and a 4-day hormone-free interval; antiandrogenic progestin"}, {"name": "Mirena (levonorgestrel IUD, 52 mg)", "a": "Progestin-only intrauterine device", "b": "No — progestin only, local endometrial release", "c": "Lasts up to 8 years for contraception; also used for heavy menstrual bleeding and as the progestin component of HRT in women with a uterus"}, {"name": "Kyleena / Jaydess (levonorgestrel IUD, lower dose)", "a": "Progestin-only intrauterine device", "b": "No — progestin only, local endometrial release", "c": "Lower hormone dose and smaller frame than Mirena; shorter duration of approved use (up to 5 years for Kyleena)"}, {"name": "Nexplanon (etonogestrel implant)", "a": "Progestin-only subdermal implant", "b": "No — progestin only", "c": "Single rod inserted in the upper arm, effective for up to 3 years; most effective reversible contraceptive method (failure rate <1%)"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "HRT has no role in pregnancy and should be discontinued if pregnancy occurs. Progestin-only contraceptives are stopped once pregnancy is confirmed, though accidental early exposure has not been shown to cause major harm."}, {"label": "Breastfeeding", "warn": false, "text": "Progestin-only methods (POP, injection, IUD, implant) are preferred and considered safe during breastfeeding as they do not reduce milk supply; combined estrogen-containing products are avoided until breastfeeding is established. HRT is not typically relevant during lactation (premenopausal state)."}, {"label": "Renal impairment", "warn": false, "text": "No major dose adjustments required for either HRT or progestin-only agents based on renal function alone."}, {"label": "Hepatic impairment", "warn": true, "text": "Oral estrogens and oral progestins are hepatically metabolized and are contraindicated or used with caution in active liver disease; transdermal/vaginal estrogen and the levonorgestrel IUD (minimal systemic absorption) are safer alternatives."}, {"label": "Elderly", "warn": true, "text": "Risk of VTE, stroke, and breast cancer with combined HRT rises with age and years since menopause onset — HRT is generally not recommended to be started after age 60 or more than 10 years post-menopause; use lowest effective dose for shortest duration for symptom control."}, {"label": "Pediatrics", "warn": true, "text": "Not applicable to HRT. Progestin-only contraceptives can be used in adolescents, but Depo-Provera's bone mineral density effects warrant caution as a first-line choice in this age group given ongoing bone accrual."}]}, {"key": "alkylating-agents", "topic": "onc", "name": "Alkylating Agents", "pronunciation": "AL-kih-lay-ting AY-jents", "blurb": "Cell-cycle-nonspecific chemotherapy that cross-links DNA strands, causing broad myelosuppression and long-term risk of secondary malignancy.", "general": ["Mechanism: Attach alkyl groups to DNA (often at the N7 of guanine), forming intra- and inter-strand cross-links that prevent DNA strands from separating for replication and transcription. This damage is cell-cycle-nonspecific (hits resting and dividing cells) but rapidly dividing tissues (bone marrow, GI mucosa, gonads) are most affected.", "Class indications: Hematologic malignancies (leukemias, lymphomas, myeloma), solid tumors (ovarian, lung, breast), and as conditioning regimens before hematopoietic stem cell transplant; some members (cyclophosphamide) are also used as immunosuppressants for autoimmune disease.", "Class side effects: Dose-limiting myelosuppression (nadir ~7-14 days), nausea/vomiting (often highly emetogenic), infertility/gonadal failure, and a class-defining long-term risk of secondary acute myeloid leukemia and myelodysplastic syndrome from cumulative DNA damage; specific agents add hemorrhagic cystitis, pulmonary fibrosis, or nephrotoxicity.", "Class contraindications: Severe active infection or profound myelosuppression from recent chemotherapy, pregnancy (teratogenic/mutagenic), and known hypersensitivity; use caution with prior extensive radiation or chemotherapy that has already compromised marrow reserve.", "Class monitoring: CBC with differential before each cycle and at nadir, renal and hepatic function, urinalysis for agents with urothelial toxicity (cyclophosphamide, ifosfamide), and long-term surveillance for secondary malignancy in survivors."], "memberCols": ["Subclass", "Key Toxicity", "Notable"], "members": [{"name": "Cyclophosphamide", "a": "Nitrogen mustard (oxazaphosphorine)", "b": "Hemorrhagic cystitis (acrolein metabolite) — give mesna and hydrate", "c": "Most versatile member; used in CHOP, breast cancer regimens, and as an immunosuppressant for lupus nephritis/vasculitis"}, {"name": "Ifosfamide", "a": "Nitrogen mustard (oxazaphosphorine)", "b": "Hemorrhagic cystitis and CNS toxicity (encephalopathy) from chloroacetaldehyde", "c": "Requires mandatory mesna co-administration; used for sarcomas and germ cell tumors"}, {"name": "Chlorambucil", "a": "Nitrogen mustard", "b": "Mild, gradual myelosuppression", "c": "Oral agent historically used in CLL; slowest-acting and best-tolerated nitrogen mustard"}, {"name": "Melphalan", "a": "Nitrogen mustard", "b": "Profound myelosuppression, mucositis at high dose", "c": "Backbone of autologous stem cell transplant conditioning for multiple myeloma"}, {"name": "Busulfan", "a": "Alkyl sulfonate", "b": "Pulmonary fibrosis ('busulfan lung'), seizures at high dose, hepatic veno-occlusive disease", "c": "Requires seizure prophylaxis (phenytoin/levetiracetam); key conditioning agent pre-HSCT"}, {"name": "Carmustine (BCNU)", "a": "Nitrosourea", "b": "Delayed/cumulative myelosuppression, pulmonary fibrosis", "c": "Highly lipophilic — crosses blood-brain barrier; used for brain tumors and as implantable wafer (Gliadel)"}, {"name": "Lomustine (CCNU)", "a": "Nitrosourea", "b": "Delayed myelosuppression (nadir 4-6 weeks)", "c": "Oral nitrosourea used for brain tumors and Hodgkin lymphoma salvage"}, {"name": "Dacarbazine", "a": "Triazene (non-classical alkylator)", "b": "Severe nausea/vomiting, flu-like syndrome, photosensitivity", "c": "Requires hepatic activation by CYP1A; component of ABVD for Hodgkin lymphoma"}, {"name": "Temozolomide", "a": "Triazene (non-classical alkylator, oral prodrug of MTIC)", "b": "Myelosuppression, fatigue; lymphopenia raises PJP pneumonia risk", "c": "Oral, crosses blood-brain barrier; standard of care with radiation for glioblastoma"}, {"name": "Carboplatin", "a": "Platinum analog (functions as alkylator via DNA cross-linking)", "b": "Thrombocytopenia-predominant myelosuppression", "c": "Dosed by Calvert formula (AUC x [GFR+25]) rather than BSA; less nephro/oto/neurotoxic than cisplatin"}, {"name": "Cisplatin", "a": "Platinum analog (functions as alkylator via DNA cross-linking)", "b": "Nephrotoxicity, ototoxicity, severe emetogenicity, peripheral neuropathy", "c": "Requires aggressive IV hydration and magnesium repletion; used across many solid tumors"}, {"name": "Oxaliplatin", "a": "Platinum analog (functions as alkylator via DNA cross-linking)", "b": "Acute and chronic cold-triggered peripheral sensory neuropathy", "c": "Minimal nephrotoxicity vs cisplatin; backbone of FOLFOX for colorectal cancer"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Contraindicated — alkylating agents are teratogenic and mutagenic, especially in the first trimester; effective contraception is required during and for months after treatment for patients of any reproductive potential."}, {"label": "Breastfeeding", "warn": true, "text": "Contraindicated — cytotoxic alkylating agents and their metabolites pass into breast milk and can cause serious harm to the infant; discontinue breastfeeding during treatment."}, {"label": "Renal impairment", "warn": true, "text": "Many members (carboplatin, cisplatin, ifosfamide) require dose adjustment or are renally eliminated; cisplatin is particularly nephrotoxic and generally avoided with significant baseline renal impairment."}, {"label": "Hepatic impairment", "warn": true, "text": "Agents requiring hepatic activation (cyclophosphamide, ifosfamide, dacarbazine) may have altered efficacy or toxicity; dose reduction is often needed with significant hepatic dysfunction."}, {"label": "Elderly", "warn": true, "text": "Increased susceptibility to myelosuppression, mucositis, and organ toxicity; renal function (and thus platinum dosing) should be reassessed frequently as it commonly declines with age."}, {"label": "Pediatrics", "warn": true, "text": "Used in pediatric leukemias, lymphomas, sarcomas, and brain tumors with weight/BSA-based dosing; long-term survivors need surveillance for gonadal toxicity, growth effects, and secondary malignancy given decades of remaining life expectancy."}]}, {"key": "antimetabolites", "topic": "onc", "name": "Antimetabolites", "pronunciation": "an-tee-meh-TAB-oh-lytes", "blurb": "Structural analogs of normal DNA/RNA building blocks that are cell-cycle-specific for S-phase, disrupting nucleotide synthesis and incorporation.", "general": ["Mechanism: Mimic natural folates, purines, or pyrimidines and either inhibit key synthetic enzymes (e.g., methotrexate blocks dihydrofolate reductase; 5-FU blocks thymidylate synthase) or get falsely incorporated into DNA/RNA, halting synthesis. Because they target active nucleotide synthesis, they are S-phase specific — most damaging to rapidly dividing cells.", "Class indications: Leukemias/lymphomas (methotrexate, cytarabine, 6-mercaptopurine), GI and breast cancers (5-fluorouracil, capecitabine), pancreatic cancer (gemcitabine), and methotrexate additionally for autoimmune disease (RA, psoriasis) at low, non-oncologic doses.", "Class side effects: Mucositis/stomatitis and diarrhea (rapidly dividing GI epithelium), myelosuppression, and agent-specific toxicities — hand-foot syndrome and cardiotoxicity with fluoropyrimidines, hepatotoxicity and pulmonary fibrosis with methotrexate, cerebellar toxicity and 'cytarabine syndrome' with high-dose cytarabine.", "Class contraindications: Pregnancy (folate antagonists and pyrimidine/purine analogs are teratogenic), severe renal impairment for renally cleared agents (methotrexate can precipitate in renal tubules causing life-threatening toxicity), and DPD enzyme deficiency for fluoropyrimidines (risk of fatal toxicity).", "Class monitoring: CBC with differential, renal and hepatic function, methotrexate levels with leucovorin rescue timing for high-dose regimens, and consideration of DPD or TPMT/NUDT15 pharmacogenomic testing before starting fluoropyrimidines or thiopurines respectively."], "memberCols": ["Subclass", "Key Toxicity", "Notable"], "members": [{"name": "Methotrexate", "a": "Folate antagonist (DHFR inhibitor)", "b": "Mucositis, hepatotoxicity, nephrotoxicity at high dose", "c": "High-dose regimens require leucovorin rescue and urine alkalinization; low-dose also used for RA/psoriasis"}, {"name": "Pemetrexed", "a": "Folate antagonist (multi-target)", "b": "Myelosuppression, rash, mucositis", "c": "Requires folic acid and vitamin B12 supplementation to reduce toxicity; used in non-squamous NSCLC and mesothelioma"}, {"name": "Fluorouracil (5-FU)", "a": "Fluoropyrimidine (thymidylate synthase inhibitor)", "b": "Hand-foot syndrome, diarrhea, coronary vasospasm/cardiotoxicity", "c": "DPD-deficient patients can develop fatal toxicity from standard doses; often given as continuous infusion in FOLFOX/FOLFIRI"}, {"name": "Capecitabine", "a": "Fluoropyrimidine (oral prodrug of 5-FU)", "b": "Hand-foot syndrome (dose-limiting), diarrhea", "c": "Enzymatically converted to 5-FU preferentially in tumor tissue; convenient oral alternative to infusional 5-FU"}, {"name": "Cytarabine (ara-C)", "a": "Pyrimidine analog", "b": "Cerebellar toxicity and conjunctivitis at high dose ('cytarabine syndrome')", "c": "Backbone of AML induction (7+3 regimen); high-dose regimens require prophylactic corticosteroid eye drops"}, {"name": "Gemcitabine", "a": "Pyrimidine analog (deoxycytidine analog)", "b": "Flu-like syndrome, capillary leak, rare pulmonary toxicity", "c": "Radiosensitizer; standard for pancreatic and bladder cancer"}, {"name": "Azacitidine", "a": "Pyrimidine analog / hypomethylating agent", "b": "Myelosuppression, injection site reactions (SC formulation)", "c": "Incorporates into DNA to inhibit DNA methyltransferase, reversing epigenetic gene silencing in MDS/AML"}, {"name": "Decitabine", "a": "Pyrimidine analog / hypomethylating agent", "b": "Myelosuppression", "c": "More potent DNMT inhibitor per molecule than azacitidine; IV or oral (with cedazuridine) for MDS"}, {"name": "6-Mercaptopurine (6-MP)", "a": "Purine analog", "b": "Myelosuppression (markedly increased with TPMT/NUDT15 deficiency)", "c": "Maintenance therapy for ALL; requires TPMT/NUDT15 genotyping or phenotyping before starting"}, {"name": "6-Thioguanine", "a": "Purine analog", "b": "Myelosuppression, hepatotoxicity (veno-occlusive disease with prolonged use)", "c": "Similar metabolism/pharmacogenomic concerns to 6-MP; used in AML/ALL protocols"}, {"name": "Fludarabine", "a": "Purine analog", "b": "Profound and prolonged lymphopenia, immunosuppression (PJP/viral reactivation risk)", "c": "Used for CLL and low-grade lymphomas; requires irradiated blood products to prevent transfusion-associated GVHD"}, {"name": "Hydroxyurea", "a": "Ribonucleotide reductase inhibitor", "b": "Myelosuppression, mucocutaneous ulcers with long-term use", "c": "Mainstay for sickle cell disease and myeloproliferative neoplasms (polycythemia vera, essential thrombocythemia)"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Contraindicated — folate antagonists and nucleoside analogs are potent teratogens (methotrexate causes a recognized embryopathy); effective contraception required during and after treatment per agent-specific washout periods."}, {"label": "Breastfeeding", "warn": true, "text": "Contraindicated — antimetabolites are excreted into breast milk and can cause hematologic and GI toxicity in the infant."}, {"label": "Renal impairment", "warn": true, "text": "Methotrexate is primarily renally cleared and can precipitate in renal tubules, causing a dangerous feedback loop of worsening renal function and drug accumulation; high-dose methotrexate requires hydration, urine alkalinization, and level monitoring, and is avoided with significant renal impairment."}, {"label": "Hepatic impairment", "warn": true, "text": "Methotrexate and thiopurines (6-MP, 6-thioguanine) can cause hepatotoxicity and veno-occlusive disease; dose adjustment and closer LFT monitoring are needed with pre-existing liver dysfunction."}, {"label": "Elderly", "warn": true, "text": "Increased risk of mucositis, myelosuppression, and renal-clearance-related toxicity (especially methotrexate); renal function should be reassessed before each high-dose cycle."}, {"label": "Pediatrics", "warn": false, "text": "Antimetabolites (methotrexate, 6-MP, cytarabine) are foundational to pediatric ALL and AML protocols with well-established weight/BSA-based pediatric dosing; TPMT/NUDT15 testing guides thiopurine dosing to avoid excess toxicity."}]}, {"key": "checkpoint-inhibitors", "topic": "onc", "name": "Immune Checkpoint Inhibitors", "pronunciation": "im-YOON CHEK-point in-HIB-ih-ters", "blurb": "Monoclonal antibodies that block inhibitory immune checkpoints (PD-1, PD-L1, CTLA-4) to unleash T-cell activity against tumors, at the cost of autoimmune-like toxicity.", "general": ["Mechanism: Block inhibitory 'checkpoint' receptors/ligands that tumors exploit to evade immune attack — PD-1 (on T cells) or PD-L1 (on tumor/antigen-presenting cells) blockade prevents the tumor from switching off activated T cells, while CTLA-4 blockade removes an early brake on T-cell priming in lymph nodes. The result is a reactivated, less-restrained immune system that can attack cancer — but also self-tissue.", "Class indications: Melanoma, non-small cell lung cancer, renal cell carcinoma, urothelial carcinoma, Hodgkin lymphoma, and an increasing list of other solid tumors, often as first-line therapy alone or combined with chemotherapy or another checkpoint inhibitor (e.g., nivolumab plus ipilimumab).", "Class side effects: Immune-related adverse events (irAEs) from loss of self-tolerance — colitis, pneumonitis, hepatitis, endocrinopathies (thyroiditis, hypophysitis, adrenal insufficiency, type 1 diabetes), dermatitis, and rarer but serious myocarditis or neurologic toxicity; onset can be delayed weeks to months after starting or even after stopping therapy.", "Class contraindications: Active autoimmune disease requiring immunosuppression and prior organ/stem cell transplant are relative contraindications (risk of flare or graft rejection/GVHD); used cautiously, if at all, with active untreated infections given reliance on an intact immune response.", "Class monitoring: Baseline and periodic thyroid function, comprehensive metabolic panel, LFTs, and cortisol/ACTH; clinical vigilance for new diarrhea, rash, cough, or fatigue at every visit, with prompt corticosteroid initiation and endocrine/GI/pulmonary specialist involvement for grade 2+ irAEs."], "memberCols": ["Target", "Dosing Schedule", "Notable"], "members": [{"name": "Pembrolizumab", "a": "PD-1", "b": "IV every 3 or 6 weeks", "c": "Broadest tumor-agnostic approval list including MSI-high/dMMR tumors regardless of tumor type"}, {"name": "Nivolumab", "a": "PD-1", "b": "IV every 2 or 4 weeks", "c": "Often combined with ipilimumab (CTLA-4) for synergistic but more toxic dual checkpoint blockade in melanoma and renal cell carcinoma"}, {"name": "Cemiplimab", "a": "PD-1", "b": "IV every 3 weeks", "c": "Key agent for advanced cutaneous squamous cell carcinoma, a tumor with few systemic options"}, {"name": "Dostarlimab", "a": "PD-1", "b": "IV every 3 or 6 weeks", "c": "Approved for dMMR endometrial and other solid tumors; notable for dramatic complete response data in MMR-deficient rectal cancer"}, {"name": "Atezolizumab", "a": "PD-L1", "b": "IV every 2, 3, or 4 weeks", "c": "Combined with bevacizumab for hepatocellular carcinoma; used in small cell and non-small cell lung cancer"}, {"name": "Durvalumab", "a": "PD-L1", "b": "IV every 2 or 4 weeks", "c": "Standard consolidation therapy after chemoradiation in unresectable stage III NSCLC (PACIFIC regimen)"}, {"name": "Avelumab", "a": "PD-L1", "b": "IV every 2 weeks", "c": "Used as first-line maintenance in metastatic urothelial carcinoma after platinum chemotherapy; also approved for Merkel cell carcinoma"}, {"name": "Ipilimumab", "a": "CTLA-4", "b": "IV every 3 weeks (induction, limited cycles)", "c": "First-in-class checkpoint inhibitor; higher rate of severe colitis and hypophysitis than PD-1/PD-L1 agents, especially at higher monotherapy doses"}, {"name": "Tremelimumab", "a": "CTLA-4", "b": "IV, single or limited priming doses combined with durvalumab", "c": "Used in a single-priming-dose combination strategy with durvalumab (STRIDE regimen) for hepatocellular carcinoma and NSCLC"}, {"name": "Relatlimab (with nivolumab)", "a": "LAG-3", "b": "IV every 4 weeks (fixed-dose combination with nivolumab)", "c": "First approved LAG-3 inhibitor; fixed-dose combo (Opdualag) for melanoma represents a third distinct checkpoint target beyond PD-1/CTLA-4"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Avoid — animal and mechanistic data suggest checkpoint inhibition can disrupt maternal-fetal immune tolerance, risking fetal loss or harm; effective contraception is advised during and for several months after treatment."}, {"label": "Breastfeeding", "warn": true, "text": "Not recommended during treatment and for a period after the last dose, given the potential for serious adverse effects in a breastfed infant and limited data on transfer into milk."}, {"label": "Renal impairment", "warn": false, "text": "No dose adjustment is required based on renal function, as these are large monoclonal antibodies cleared by catabolism rather than renal excretion; however, immune-related nephritis should be monitored for and can itself impair renal function."}, {"label": "Hepatic impairment", "warn": false, "text": "No dose adjustment is required for mild hepatic impairment; monitor LFTs closely given the risk of immune-related hepatitis, which can be mistaken for progressive liver dysfunction."}, {"label": "Elderly", "warn": false, "text": "No dose adjustment needed based on age alone; efficacy and toxicity profiles are generally similar to younger adults, though comorbidities may complicate management of irAEs."}, {"label": "Pediatrics", "warn": true, "text": "Limited pediatric data; a few agents have approvals for specific pediatric indications (e.g., classical Hodgkin lymphoma), but safety and efficacy are not established broadly across childhood cancers — use is generally restricted to approved indications or clinical trials."}]}, {"key": "topical-corticosteroids", "topic": "derm", "name": "Topical Corticosteroids", "pronunciation": "TOP-ih-kal kor-tih-koh-STAIR-oydz", "blurb": "Mainstay anti-inflammatory treatment for eczema, psoriasis, and other dermatoses, classified by potency from mild to super-high.", "general": ["Mechanism: Diffuse into skin cells and bind cytoplasmic glucocorticoid receptors, which translocate to the nucleus and switch off pro-inflammatory gene transcription (cytokines, prostaglandins) while inducing anti-inflammatory proteins. They also cause vasoconstriction (the basis of the vasoconstrictor assay used to rank potency) and inhibit fibroblast/keratinocyte proliferation, which underlies both the anti-inflammatory benefit and the skin-thinning risk.", "Class indications: Atopic dermatitis/eczema, psoriasis, contact dermatitis, seborrheic dermatitis, lichen planus, and other inflammatory or pruritic dermatoses; potency and vehicle are chosen based on body site, skin thickness, and chronicity.", "Class side effects: Local skin atrophy, telangiectasia, striae, purpura, and perioral dermatitis/acneiform eruptions with prolonged use; tachyphylaxis with continuous use; hypopigmentation especially in darker skin; systemic HPA-axis suppression, Cushingoid features, and hyperglycemia can occur with high-potency agents used over large surface areas, under occlusion, or for prolonged periods (higher risk in infants due to greater surface-area-to-weight ratio).", "Class contraindications: Untreated bacterial, fungal, or viral skin infections (including herpes, varicella) at the treatment site; rosacea and perioral dermatitis (can worsen); known hypersensitivity to the corticosteroid or vehicle components.", "Class monitoring: Clinical response and duration of use (reassess if no improvement in 2-4 weeks); watch for signs of skin atrophy/striae with ongoing use; limit high/super-high potency agents to short courses (typically 2-4 weeks) and to <5-10% body surface area; consider HPA-axis suppression if high-potency use is extensive, occluded, or prolonged, particularly in children."], "memberCols": ["Potency Class", "Vehicle", "Notable"], "members": [{"name": "Hydrocortisone 0.5-1%", "a": "Class VII (mild/least potent)", "b": "Cream, lotion", "c": "OTC in Canada; first choice for face, groin, axillae, and infants due to lowest atrophy risk"}, {"name": "Desonide 0.05%", "a": "Class VI-VII (mild)", "b": "Cream, lotion, foam", "c": "Preferred mild agent for pediatric eczema on face/flexures when hydrocortisone is insufficient"}, {"name": "Clobetasone butyrate 0.05%", "a": "Class VI (mild-moderate)", "b": "Cream, ointment", "c": "Often used as a step-up from hydrocortisone for facial/flexural dermatitis"}, {"name": "Triamcinolone acetonide 0.1%", "a": "Class IV-V (moderate)", "b": "Cream, ointment, lotion", "c": "Workhorse moderate-potency agent for trunk/extremities; ointment more potent than cream"}, {"name": "Betamethasone valerate 0.05-0.1%", "a": "Class III-IV (moderate-potent)", "b": "Cream, lotion, ointment", "c": "Versatile mid-tier agent; valerate ester distinguishes it from the more potent dipropionate salt"}, {"name": "Fluocinonide 0.05%", "a": "Class II (potent)", "b": "Cream, gel, ointment", "c": "Used for thicker plaques (e.g., psoriasis) on trunk/limbs; not for face or intertriginous areas"}, {"name": "Mometasone furoate 0.1%", "a": "Class II-III (potent)", "b": "Cream, ointment, lotion", "c": "Once-daily dosing improves adherence; relatively favourable atrophy profile for its potency"}, {"name": "Betamethasone dipropionate 0.05% (regular base)", "a": "Class II (potent)", "b": "Cream, ointment", "c": "More potent than the valerate salt at the same concentration due to the dipropionate ester and vehicle"}, {"name": "Fluocinonide 0.05% (emulsified base)", "a": "Class I-II (very potent)", "b": "Cream (optimized base)", "c": "Optimized/emulsified vehicles enhance penetration, pushing some formulations into very-potent tier"}, {"name": "Betamethasone dipropionate 0.05% (optimized/augmented)", "a": "Class I (super-potent)", "b": "Augmented gel, ointment, lotion", "c": "Augmented formulation enhances penetration; reserve for short courses on palms/soles or resistant plaques"}, {"name": "Clobetasol propionate 0.05%", "a": "Class I (super-potent)", "b": "Cream, ointment, gel, foam, shampoo, spray", "c": "Most potent topical steroid available in Canada; limit to 2 weeks, <50 g/week, and never on face/groin/folds"}, {"name": "Halobetasol propionate 0.05%", "a": "Class I (super-potent)", "b": "Cream, ointment", "c": "Alternative super-potent agent for thick plaque psoriasis; same strict duration/site limits as clobetasol"}], "specialPopulations": [{"label": "Pregnancy", "warn": false, "text": "Low-to-moderate potency agents are generally considered safe in pregnancy; large quantities of potent/super-potent agents have been associated with low birth weight in some studies, so use the lowest effective potency and smallest area/duration needed."}, {"label": "Breastfeeding", "warn": false, "text": "Compatible with breastfeeding; if applying near the breast/nipple, wash off before feeding to avoid direct infant ingestion."}, {"label": "Renal impairment", "warn": false, "text": "No dose adjustment needed — topical corticosteroids have minimal systemic absorption at recommended use and are not renally dosed."}, {"label": "Hepatic impairment", "warn": false, "text": "No specific dose adjustment; systemic absorption and hepatic metabolism are negligible with appropriate topical use, but avoid extensive/prolonged high-potency use where systemic exposure could rise."}, {"label": "Elderly", "warn": true, "text": "Aged skin is thinner and more prone to atrophy, purpura, and tearing — prefer lower potency agents and ointment vehicles, and monitor closely if potent agents are needed."}, {"label": "Pediatrics", "warn": true, "text": "Greater surface-area-to-weight ratio increases systemic absorption risk — use the lowest effective potency (hydrocortisone or desonide first-line), avoid super-potent agents, limit duration, and avoid occlusion (including diapers) unless directed."}]}, {"key": "glaucoma-agents", "topic": "derm", "name": "Glaucoma Agents", "pronunciation": "glaw-KOH-mah AY-jents", "blurb": "Topical ophthalmic agents that lower intraocular pressure in open-angle glaucoma by increasing aqueous outflow or reducing aqueous production.", "general": ["Mechanism: Four main subtypes lower IOP by different routes — prostaglandin analogs increase uveoscleral (secondary) outflow by remodeling the ciliary muscle extracellular matrix; beta-blockers and carbonic anhydrase inhibitors reduce aqueous humor production (beta-blockers via ciliary epithelium beta-2 receptor blockade, CAIs by inhibiting carbonic anhydrase-mediated bicarbonate/aqueous formation); alpha-2 agonists both decrease aqueous production and modestly increase uveoscleral outflow.", "Class indications: Open-angle glaucoma and ocular hypertension, to reduce intraocular pressure and slow optic nerve damage/visual field loss; prostaglandin analogs are first-line for most patients due to once-daily dosing, efficacy, and systemic safety.", "Class side effects: Prostaglandins cause conjunctival hyperemia, eyelash growth, and irreversible iris/periocular skin pigmentation; beta-blockers can cause systemic bradycardia, bronchospasm, and fatigue via systemic absorption through the nasolacrimal duct; CAIs cause stinging/bitter taste (topical) or paresthesias/metabolic acidosis (oral); alpha agonists cause allergic conjunctivitis, dry mouth, and drowsiness (especially in young children).", "Class contraindications: Non-selective beta-blockers are contraindicated in asthma/COPD, bradycardia, and heart block; brimonidine (alpha agonist) is contraindicated in infants and young children due to CNS depression/apnea risk; sulfonamide-based CAIs are avoided with sulfa allergy; prostaglandins are used cautiously in active uveitis/CME risk and herpetic keratitis.", "Class monitoring: Intraocular pressure at follow-up visits, optic disc appearance and visual fields over time for disease progression, and adherence/technique (punctal occlusion to reduce systemic absorption); monitor heart rate/pulmonary status with beta-blockers and electrolytes/bicarbonate with oral CAIs."], "memberCols": ["Class", "Dosing", "Notable"], "members": [{"name": "Latanoprost", "a": "Prostaglandin analog", "b": "OD (evening)", "c": "First-line agent for most patients; generic, well-studied; store per product (some formulations need refrigeration)"}, {"name": "Travoprost", "a": "Prostaglandin analog", "b": "OD (evening)", "c": "Similar efficacy to latanoprost; some formulations are preservative-free (SofZia) for sensitive eyes"}, {"name": "Bimatoprost", "a": "Prostaglandin analog (prostamide)", "b": "OD (evening)", "c": "May be slightly more effective at lowering IOP but more hyperemia; also marketed for eyelash growth (Latisse)"}, {"name": "Tafluprost", "a": "Prostaglandin analog", "b": "OD (evening)", "c": "Available preservative-free — preferred option for patients with ocular surface disease or BAK sensitivity"}, {"name": "Timolol", "a": "Non-selective beta-blocker", "b": "OD-BID", "c": "Long-standing first-line adjunct; gel-forming solution allows once-daily dosing; systemic absorption can cause bradycardia/bronchospasm"}, {"name": "Betaxolol", "a": "Cardioselective (beta-1) blocker", "b": "BID", "c": "Relatively safer than timolol in mild reactive airway disease due to beta-1 selectivity, though not risk-free"}, {"name": "Dorzolamide", "a": "Carbonic anhydrase inhibitor (topical)", "b": "TID (or BID combined)", "c": "Causes transient stinging and bitter taste; avoid in sulfa allergy; often combined with timolol (Cosopt)"}, {"name": "Brinzolamide", "a": "Carbonic anhydrase inhibitor (topical)", "b": "BID-TID", "c": "Suspension formulation causes less stinging than dorzolamide but can blur vision transiently"}, {"name": "Acetazolamide", "a": "Carbonic anhydrase inhibitor (oral)", "b": "BID-QID (or ER OD-BID)", "c": "Used for acute angle-closure or refractory IOP; systemic effects include paresthesias, metabolic acidosis, and hypokalemia"}, {"name": "Brimonidine", "a": "Alpha-2 agonist", "b": "BID-TID", "c": "Contraindicated in infants/young children (CNS depression, apnea risk); allergic conjunctivitis common with long-term use"}, {"name": "Apraclonidine", "a": "Alpha-2 agonist", "b": "TID (short-term) / BID-TID (peri-procedure)", "c": "Mainly used short-term to blunt IOP spikes after laser procedures; tachyphylaxis limits long-term use"}, {"name": "Latanoprost/Timolol (fixed combo)", "a": "Prostaglandin + beta-blocker combo", "b": "OD", "c": "Fixed-dose combination improves adherence when monotherapy is insufficient; avoids washout effect of separate drops"}, {"name": "Pilocarpine", "a": "Cholinergic (miotic) agonist", "b": "TID-QID", "c": "Older agent that increases trabecular meshwork outflow via ciliary muscle contraction; largely reserved for angle-closure or when other classes fail due to miosis/brow ache side effects"}], "specialPopulations": [{"label": "Pregnancy", "warn": true, "text": "Data are limited for most agents; prostaglandins and CAIs are generally avoided unless necessary, and beta-blockers should be used with punctal occlusion to minimize systemic absorption — consult ophthalmology on risk/benefit given the disease's low urgency in most cases."}, {"label": "Breastfeeding", "warn": true, "text": "Systemic absorption is low with proper technique (punctal occlusion), but data are limited for most classes — beta-blockers can theoretically affect the infant (bradycardia); use the lowest effective dose and monitor if a systemic agent (e.g., oral acetazolamide) is required."}, {"label": "Renal impairment", "warn": true, "text": "Oral acetazolamide is renally eliminated and can worsen metabolic acidosis and electrolyte disturbances in renal impairment — avoid or use cautiously; topical agents have minimal systemic exposure and generally require no adjustment."}, {"label": "Hepatic impairment", "warn": false, "text": "Topical agents undergo minimal hepatic metabolism at ocular doses and generally require no adjustment; use oral CAIs cautiously as they are contraindicated in severe hepatic impairment/cirrhosis due to risk of hepatic encephalopathy exacerbation."}, {"label": "Elderly", "warn": true, "text": "Increased risk of systemic beta-blocker effects (bradycardia, falls, masking hypoglycemia) due to age-related comorbidities and polypharmacy — reinforce punctal occlusion and review for interacting oral beta-blockers/non-dihydropyridine calcium channel blockers."}, {"label": "Pediatrics", "warn": true, "text": "Brimonidine is contraindicated under age 2 (and used cautiously in older children) due to risk of CNS/respiratory depression; pediatric glaucoma is uncommon and typically managed by ophthalmology with close monitoring of any systemic agent."}]}];
